import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

// Register Service Worker for PWA
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/service-worker.js').catch(err => {
      console.log('Service worker registration failed: ', err);
    });
  });
}

export enum MealType {
  BREAKFAST = '아침',
  LUNCH = '점심',
  SNACK = '간식',
  DINNER = '저녁'
}

export interface Ingredient {
  uuid: string;
  name: string;
  base_amount: number;
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  sugar: number;
  fiber: number;
}

export interface MealRecord {
  uuid: string;
  type: MealType;
  date: string; // YYYY-MM-DD
  time: string; // HH:mm
  ingredient_uuid: string;
  ingredient_name?: string; // Derived field
  amount: number;
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  sugar: number;
  fiber: number;
  pending?: boolean; // For optimistic UI
}

export interface DailySummary {
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import { fetchInitialData, saveMealToGAS, saveIngredientToGAS } from './services/gasService';

const App: React.FC = () => {
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);

  // Initial Load
  useEffect(() => {
    const loadData = async () => {
      try {
        const data = await fetchInitialData();
        setMeals(data.meals);
        setIngredients(data.ingredients);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(isLoading => false);
      }
    };
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const filteredMeals = useMemo(() => {
    return meals.filter(m => m.date === selectedDate);
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    return filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + cur.kcal,
      carbs: acc.carbs + cur.carbs,
      protein: acc.protein + cur.protein,
      fat: acc.fat + cur.fat,
    }), { kcal: 0, carbs: 0, protein: 0, fat: 0 });
  }, [filteredMeals]);

  const handleAddMeal = useCallback((type: MealType) => {
    setPrefilledType(type);
    setIsInputOpen(true);
  }, []);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    // 1. Optimistic Update
    const optimisticMeal = { ...newMeal, pending: true };
    setMeals(prev => [...prev, optimisticMeal]);

    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      // Sync ingredient background
      saveIngredientToGAS(newIngredient).catch(err => console.error("Sync ingredient failed", err));
    }

    // 2. Sync meal background
    try {
      await saveMealToGAS(newMeal);
      setMeals(prev => prev.map(m => m.uuid === newMeal.uuid ? { ...m, pending: false } : m));
    } catch (error) {
      console.error("Sync meal failed", error);
      // Rollback on hard failure could be implemented here
    }
  }, []);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium">데이터를 불러오는 중...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50">
      <header className="bg-indigo-600 text-white p-4 sticky top-0 z-10 shadow-md">
        <h1 className="text-xl font-bold">효정님의 식단 일기</h1>
      </header>

      <main className="p-4 space-y-6">
        <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} />

        <DailySummaryView summary={summary} />

        <div className="space-y-4">
          {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
            <MealSection 
              key={type} 
              type={type} 
              meals={filteredMeals.filter(m => m.type === type)} 
              ingredients={ingredients}
              onAdd={() => handleAddMeal(type)}
            />
          ))}
        </div>

        <button 
          onClick={() => setAdviceModalOpen(true)}
          className="w-full mt-8 py-3 bg-gradient-to-r from-teal-500 to-indigo-500 text-white font-bold rounded-xl shadow-lg active:scale-95 transition-transform"
        >
          ✨ AI 영양 추천 받기
        </button>
      </main>

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => setIsInputOpen(false)}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          ingredients={ingredients}
          onSave={onSaveMeal}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.kcal}
          currentProtein={summary.protein}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';

interface CalendarProps {
  selectedDate: string;
  onSelectDate: (date: string) => void;
}

const Calendar: React.FC<CalendarProps> = ({ selectedDate, onSelectDate }) => {
  const today = new Date();

  // Generate last 7 days + next 7 days
  const dates = Array.from({ length: 15 }, (_, i) => {
    const d = new Date();
    d.setDate(today.getDate() - 7 + i);
    return d.toISOString().split('T')[0];
  });

  const getDayName = (dateStr: string) => {
    const d = new Date(dateStr);
    return d.toLocaleDateString('ko-KR', { weekday: 'short' });
  };

  const getDayNum = (dateStr: string) => {
    return dateStr.split('-')[2];
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm p-4 overflow-x-auto">
      <div className="flex space-x-4 min-w-max pb-2">
        {dates.map((date) => {
          const isSelected = date === selectedDate;
          const isToday = date === new Date().toISOString().split('T')[0];

          return (
            <button
              key={date}
              onClick={() => onSelectDate(date)}
              className={`flex flex-col items-center justify-center w-12 h-16 rounded-xl transition-all ${
                isSelected 
                  ? 'bg-indigo-600 text-white shadow-md' 
                  : isToday 
                    ? 'bg-indigo-50 text-indigo-600'
                    : 'bg-gray-50 text-gray-500'
              }`}
            >
              <span className="text-xs font-medium mb-1">{getDayName(date)}</span>
              <span className="text-lg font-bold">{getDayNum(date)}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default Calendar;

import React from 'react';
import { DailySummary } from '../types';

interface Props {
  summary: DailySummary;
}

const DailySummaryView: React.FC<Props> = ({ summary }) => {
  const targetKcal = 1500;
  const targetProtein = 100;

  const kcalProgress = Math.min((summary.kcal / targetKcal) * 100, 100);

  return (
    <div className="bg-white rounded-2xl shadow-sm p-5 space-y-4">
      <div className="flex justify-between items-end">
        <div>
          <h3 className="text-gray-400 text-sm font-medium">오늘 섭취 칼로리</h3>
          <p className="text-3xl font-black text-indigo-600">{Math.round(summary.kcal)} <span className="text-lg font-normal text-gray-400">/ {targetKcal} kcal</span></p>
        </div>
        <div className="text-right">
          <p className="text-sm font-bold text-gray-500">{Math.round(kcalProgress)}%</p>
        </div>
      </div>

      <div className="w-full bg-gray-100 h-2 rounded-full overflow-hidden">
        <div 
          className="bg-indigo-500 h-full transition-all duration-500" 
          style={{ width: `${kcalProgress}%` }}
        />
      </div>

      <div className="grid grid-cols-3 gap-2 pt-2 border-t border-gray-50">
        <NutrientBadge label="탄수화물" val={summary.carbs} color="bg-orange-100 text-orange-600" />
        <NutrientBadge label="단백질" val={summary.protein} color="bg-emerald-100 text-emerald-600" />
        <NutrientBadge label="지방" val={summary.fat} color="bg-blue-100 text-blue-600" />
      </div>
    </div>
  );
};

const NutrientBadge: React.FC<{ label: string, val: number, color: string }> = ({ label, val, color }) => (
  <div className="flex flex-col items-center">
    <span className="text-[10px] text-gray-400 mb-1">{label}</span>
    <div className={`${color} px-3 py-1 rounded-lg font-bold text-sm w-full text-center`}>
      {Math.round(val)}g
    </div>
  </div>
);

export default DailySummaryView;

import React from 'react';
import { MealRecord, Ingredient, MealType } from '../types';

interface Props {
  type: MealType;
  meals: MealRecord[];
  ingredients: Ingredient[];
  onAdd: () => void;
}

const MealSection: React.FC<Props> = ({ type, meals, ingredients, onAdd }) => {
  const getIngredientName = (uuid: string) => {
    return ingredients.find(i => i.uuid === uuid)?.name || '알 수 없는 식재료';
  };

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center px-1">
        <h4 className="font-bold text-gray-700 flex items-center">
          <span className={`w-2 h-2 rounded-full mr-2 ${
            type === MealType.BREAKFAST ? 'bg-amber-400' :
            type === MealType.LUNCH ? 'bg-green-400' :
            type === MealType.SNACK ? 'bg-pink-400' : 'bg-indigo-400'
          }`} />
          {type}
        </h4>
        <button 
          onClick={onAdd}
          className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded-full text-gray-500 hover:bg-gray-200"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
          </svg>
        </button>
      </div>

      <div className="space-y-2">
        {meals.length === 0 ? (
          <div className="bg-white/50 border border-dashed border-gray-200 p-4 rounded-xl text-center text-xs text-gray-400 italic">
            기록된 {type}이 없습니다.
          </div>
        ) : (
          meals.map(meal => (
            <div key={meal.uuid} className={`bg-white p-4 rounded-xl shadow-sm flex justify-between items-center border-l-4 ${meal.pending ? 'opacity-50 grayscale border-gray-300' : 'border-indigo-500'}`}>
              <div>
                <p className="font-bold text-sm text-gray-800">{getIngredientName(meal.ingredient_uuid)}</p>
                <p className="text-xs text-gray-500">{meal.amount}g • {meal.time}</p>
              </div>
              <div className="text-right">
                <p className="font-bold text-indigo-600">{Math.round(meal.kcal)} kcal</p>
                <div className="flex space-x-2 text-[10px] text-gray-400">
                  <span>탄 {Math.round(meal.carbs)}</span>
                  <span>단 {Math.round(meal.protein)}</span>
                  <span>지 {Math.round(meal.fat)}</span>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default MealSection;

import React, { useState, useMemo, useEffect } from 'react';
import { MealRecord, Ingredient, MealType } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  ingredients: Ingredient[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, ingredients, onSave }) => {
  const [date, setDate] = useState(selectedDate);
  const [time, setTime] = useState(new Date().toTimeString().slice(0, 5));
  const [type, setType] = useState<MealType>(prefilledType || MealType.BREAKFAST);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(null);
  const [amount, setAmount] = useState<string>('100');

  // New Ingredient Mode
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newName, setNewName] = useState('');
  const [newBase, setNewBase] = useState('100');
  const [newKcal, setNewKcal] = useState('');
  const [newCarbs, setNewCarbs] = useState('');
  const [newProtein, setNewProtein] = useState('');
  const [newFat, setNewFat] = useState('');

  // Auto-set type based on time if not manually selected
  useEffect(() => {
    if (!prefilledType) {
      const h = parseInt(time.split(':')[0]);
      const m = parseInt(time.split(':')[1]);
      const totalMin = h * 60 + m;

      if (totalMin >= 360 && totalMin < 710) setType(MealType.BREAKFAST);
      else if (totalMin >= 710 && totalMin < 840) setType(MealType.LUNCH);
      else if (totalMin >= 840 && totalMin < 1080) setType(MealType.SNACK);
      else if (totalMin >= 1080 || totalMin < 360) setType(MealType.DINNER);
    }
  }, [time, prefilledType]);

  const filteredIngredients = useMemo(() => {
    if (!searchTerm) return [];
    return ingredients.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).slice(0, 5);
  }, [searchTerm, ingredients]);

  const preview = useMemo(() => {
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: ing.carbs * factor,
      protein: ing.protein * factor,
      fat: ing.fat * factor,
      sugar: ing.sugar * factor,
      fiber: ing.fiber * factor,
    };
  }, [selectedIngredient, amount]);

  const handleSave = (keepOpen: boolean) => {
    let finalIngredient = selectedIngredient;
    let newIngData: Ingredient | undefined;

    if (isAddingNew) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: newName,
        base_amount: parseFloat(newBase),
        kcal: parseFloat(newKcal),
        carbs: parseFloat(newCarbs),
        protein: parseFloat(newProtein),
        fat: parseFloat(newFat),
        sugar: 0,
        fiber: 0
      };
      finalIngredient = newIngData;
    }

    if (!finalIngredient || !preview) return;

    const newMeal: MealRecord = {
      uuid: crypto.randomUUID(),
      type,
      date,
      time,
      ingredient_uuid: finalIngredient.uuid,
      amount: parseFloat(amount),
      ...preview
    };

    onSave(newMeal, newIngData);

    if (keepOpen) {
      // Reset form but keep persistent values
      setSearchTerm('');
      setSelectedIngredient(null);
      setAmount('100');
      setIsAddingNew(false);
      setNewName('');
    } else {
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4">
      <div className="bg-white w-full max-w-md rounded-t-3xl sm:rounded-3xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">
        <div className="p-4 border-b flex justify-between items-center sticky top-0 bg-white">
          <h2 className="text-lg font-bold">식단 입력</h2>
          <button onClick={onClose} className="text-gray-400 p-1">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-4 overflow-y-auto">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-400 mb-1 uppercase">날짜</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-gray-50 p-2 rounded-lg border focus:ring-2 focus:ring-indigo-500 outline-none" />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 mb-1 uppercase">시간</label>
              <input type="time" value={time} onChange={e => setTime(e.target.value)} className="w-full bg-gray-50 p-2 rounded-lg border focus:ring-2 focus:ring-indigo-500 outline-none" />
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-400 mb-1 uppercase">분류</label>
            <div className="flex bg-gray-50 p-1 rounded-xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(t => (
                <button
                  key={t}
                  onClick={() => setType(t)}
                  className={`flex-1 py-1.5 text-xs rounded-lg transition-colors ${type === t ? 'bg-white shadow-sm font-bold text-indigo-600' : 'text-gray-400'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div>
              <label className="block text-xs font-bold text-gray-400 mb-1 uppercase">식재료 검색</label>
              <input 
                autoFocus
                type="text" 
                placeholder="식재료 이름을 입력하세요..." 
                value={searchTerm} 
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full p-3 rounded-xl border focus:ring-2 focus:ring-indigo-500 outline-none" 
              />
              <div className="mt-2 space-y-1">
                {filteredIngredients.map(i => (
                  <button 
                    key={i.uuid} 
                    onClick={() => { setSelectedIngredient(i); setSearchTerm(''); }}
                    className="w-full text-left p-3 bg-gray-50 hover:bg-gray-100 rounded-xl flex justify-between items-center"
                  >
                    <span className="font-medium text-sm">{i.name}</span>
                    <span className="text-[10px] text-gray-400">{i.kcal} kcal / {i.base_amount}g</span>
                  </button>
                ))}
                {searchTerm && filteredIngredients.length === 0 && (
                  <button 
                    onClick={() => { setIsAddingNew(true); setNewName(searchTerm); }}
                    className="w-full p-4 border border-dashed border-indigo-300 rounded-xl text-indigo-500 text-sm font-bold bg-indigo-50"
                  >
                    + "{searchTerm}" 신규 식재료 등록하기
                  </button>
                )}
              </div>
            </div>
          ) : isAddingNew ? (
            <div className="space-y-3 bg-indigo-50/50 p-4 rounded-2xl border border-indigo-100">
              <div className="flex justify-between">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-widest">신규 식재료 정보</h3>
                <button onClick={() => setIsAddingNew(false)} className="text-[10px] text-gray-400 underline">검색으로 돌아가기</button>
              </div>
              <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름" className="w-full p-2 rounded-lg border" />
              <div className="grid grid-cols-2 gap-2">
                <input value={newBase} onChange={e => setNewBase(e.target.value)} placeholder="기준양(g)" className="p-2 rounded-lg border text-sm" />
                <input value={newKcal} onChange={e => setNewKcal(e.target.value)} placeholder="칼로리" className="p-2 rounded-lg border text-sm" />
                <input value={newCarbs} onChange={e => setNewCarbs(e.target.value)} placeholder="탄수화물(g)" className="p-2 rounded-lg border text-sm" />
                <input value={newProtein} onChange={e => setNewProtein(e.target.value)} placeholder="단백질(g)" className="p-2 rounded-lg border text-sm" />
                <input value={newFat} onChange={e => setNewFat(e.target.value)} placeholder="지방(g)" className="p-2 rounded-lg border text-sm col-span-2" />
              </div>
              {newName && newKcal && (
                <div className="pt-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1">이번에 먹은 양(g)</label>
                  <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-3 rounded-xl border-2 border-indigo-500 font-bold" />
                </div>
              )}
            </div>
          ) : (
            <div className="bg-indigo-50 p-4 rounded-2xl flex flex-col space-y-4">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-black text-indigo-600 text-lg">{selectedIngredient?.name}</h3>
                  <p className="text-xs text-gray-400">기준: {selectedIngredient?.base_amount}g 당 {selectedIngredient?.kcal}kcal</p>
                </div>
                <button onClick={() => setSelectedIngredient(null)} className="text-xs text-gray-400 underline">다른 식재료 선택</button>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-600 mb-1">섭취량 (g)</label>
                <input 
                  type="number" 
                  step="0.1" 
                  value={amount} 
                  onChange={e => setAmount(e.target.value)} 
                  className="w-full p-4 rounded-xl border-2 border-indigo-500 text-2xl font-black focus:ring-0 outline-none" 
                />
              </div>

              {preview && (
