import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  deleteMealFromGAS,
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => {
    return meals.filter(m => String(m.date).startsWith(selectedDate));
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    return filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { kcal: 0, carbs: 0, protein: 0, fat: 0 });
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    const isUpdate = meals.some(m => m.uuid === newMeal.uuid);

    if (isUpdate) {
      setMeals(prev => prev.map(m => m.uuid === newMeal.uuid ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }

    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }

    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => m.uuid === newMeal.uuid ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals]);

  const onDeleteMeal = useCallback(async (uuid: string) => {
    if (!confirm('기록을 삭제할까요?')) return;
    const previousMeals = [...meals];
    setMeals(prev => prev.filter(m => m.uuid !== uuid));

    try {
      const success = await deleteMealFromGAS(uuid);
      if (!success) setMeals(previousMeals);
    } catch (err) {
      setMeals(previousMeals);
    }
  }, [meals]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    const target = ingredients.find(i => i.uuid === uuid);
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => i.uuid === uuid ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => i.uuid === uuid ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, []);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    setIngredients(prev => prev.map(i => i.uuid === ing.uuid ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, []);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => i.uuid !== uuid));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl">
      <header className="bg-indigo-600 text-white p-4 sticky top-0 z-50 shadow-lg flex items-center">
        <button 
          onClick={() => setIsSidebarOpen(true)}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
        <h1 className="ml-2 text-xl font-bold">
          {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
        </h1>
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar 
              selectedDate={selectedDate} 
              onSelectDate={setSelectedDate} 
              meals={meals}
            />

            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  onAdd={() => {
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                />
              ))}
            </div>

            <button 
              onClick={() => setAdviceModalOpen(true)}
              className="w-full mt-8 py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"
            >
              <span className="text-xl">✨</span>
              <span>AI 영양 추천 받기</span>
            </button>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement 
            ingredients={ingredients}
            onToggleBookmark={handleToggleBookmark}
            onAddIngredient={handleAddIngredient}
            onUpdateIngredient={handleUpdateIngredient}
            onDeleteIngredient={handleDeleteIngredient}
          />
        ) : (
          <Statistics meals={meals} />
        )}
      </main>

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => {
            setIsInputOpen(false);
            setEditMealTarget(null);
          }}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          editTarget={editMealTarget}
          ingredients={ingredients}
          onSave={onSaveMeal}
          onDelete={onDeleteMeal}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.kcal}
          currentProtein={summary.protein}
        />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";

/**
 * 쿠쿠님의 현재 영양 섭취 상태를 기반으로 Gemini AI 추천을 가져옵니다.
 */
export async function getAIRecommendation(currentKcal: number, currentProtein: number): Promise<string | undefined> {
  /**
   * 가이드라인에 따라 process.env.API_KEY를 사용합니다.
   * Vite 빌드 도구가 이 코드를 "undefined" 문자열로 치환하는 것을 방지하기 위해 
   * 런타임 체크 로직을 강화합니다.
   */
  let apiKey = process.env.API_KEY;

  // 만약 빌드 타임에 "undefined" 문자열로 박혔거나 실제 undefined라면 window 객체에서 재확인
  if (!apiKey || apiKey === "undefined") {
    apiKey = (window as any).process?.env?.API_KEY;
  }

  if (!apiKey || apiKey === "undefined") {
    console.error("Gemini API Key is missing even after runtime check.");
    return "API 키를 인식하지 못했습니다. Vercel 설정에서 [VITE_API_KEY]를 다시 확인하고, 수정 후 'Redeploy' (기존 빌드 캐시 무시)를 진행해 주세요.";
  }

  const ai = new GoogleGenAI({ apiKey });

  const prompt = `당신은 쿠쿠님의 다정한 전담 영양사입니다. 
쿠쿠님의 현재 상태: 오늘 ${currentKcal.toFixed(0)}kcal 섭취, 단백질 ${currentProtein.toFixed(1)}g 섭취. 
일일 목표: 1500kcal, 단백질 100g. 
남은 할당량 내에서 먹어야 하는 단백질의 양과 kcal를 먼저 숫자로 명시하고, 부족한 양이 없다면 부족함 없이 잘 챙겨 섭취했다는 내용의 칭찬 한마디를 해주세요.
부족한 양이 있다면 남은 할당량 내에서 부족한 단백질을 채울 수 있는 맛있는 메뉴 1가지를 추천하고 응원 한 마디를 해주세요. 
답변은 다양한 이모지를 사용해서 한국어로 3문장 이내로 작성하세요.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    const text = response.text;

    if (!text) {
      return "AI가 답변을 생성하지 못했습니다. 잠시 후 다시 시도해 주세요.";
    }

    return text;
  } catch (error: any) {
    console.error("Gemini API Error:", error);

    if (error.message?.includes("API key not valid")) {
      return "설정된 API 키가 유효하지 않습니다. 키 값을 다시 확인해 주세요.";
    }

    return "AI 분석 중 오류가 발생했습니다. (네트워크 또는 서버 이슈)";
  }
}

import React, { useState, useMemo, useEffect } from 'react';
import { MealRecord, Ingredient, MealType } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => void;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    editTarget ? (ingredients.find(i => i.uuid === editTarget.ingredient_uuid) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '100');

  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newName, setNewName] = useState('');
  const [newBase, setNewBase] = useState('100');
  const [newKcal, setNewKcal] = useState('');
  const [newCarbs, setNewCarbs] = useState('');
  const [newProtein, setNewProtein] = useState('');
  const [newFat, setNewFat] = useState('');

  // 탄/단/지 입력 시 칼로리 자동 계산 로직
  useEffect(() => {
    if (isAddingNew) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated > 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew]);

  useEffect(() => {
    if (!prefilledType && !editTarget) {
      const h = parseInt(time.split(':')[0]);
      const totalMin = h * 60 + parseInt(time.split(':')[1]);
      if (totalMin >= 360 && totalMin < 710) setType(MealType.BREAKFAST);
      else if (totalMin >= 710 && totalMin < 840) setType(MealType.LUNCH);
      else if (totalMin >= 840 && totalMin < 1080) setType(MealType.SNACK);
      else setType(MealType.DINNER);
    }
  }, [time, prefilledType, editTarget]);

  const bookmarkedIngredients = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 8);
  }, [ingredients]);

  const filteredIngredients = useMemo(() => {
    if (!searchTerm) return [];
    return ingredients
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => (b.is_bookmarked ? 1 : 0) - (a.is_bookmarked ? 1 : 0))
      .slice(0, 8);
  }, [searchTerm, ingredients]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const factor = parseFloat(amount) / (parseFloat(newBase) || 100);
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
        sugar: 0,
        fiber: 0,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
      sugar: (ing.sugar || 0) * factor,
      fiber: (ing.fiber || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (keepOpen: boolean) => {
    let finalIngredient = selectedIngredient;
    let newIngData: Ingredient | undefined;

    if (isAddingNew) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: newName || '직접 입력 식단',
        base_amount: parseFloat(newBase) || 100,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredient = newIngData;
    }

    if (!finalIngredient || !preview) return;

    const newMeal: MealRecord = {
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      date,
      time,
      ingredient_uuid: finalIngredient.uuid,
      amount: parseFloat(amount),
      ...preview
    };

    onSave(newMeal, newIngData);

    if (keepOpen) {
      setSearchTerm('');
      setSelectedIngredient(null);
      setAmount('100');
      setIsAddingNew(false);
      setNewName('');
      setNewKcal('');
      setNewCarbs('');
      setNewProtein('');
      setNewFat('');
    } else {
      onClose();
    }
  };

  const handleDelete = () => {
    if (editTarget && onDelete) {
      onDelete(editTarget.uuid);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4">
      <div className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden">
        <div className="p-6 border-b flex justify-between items-center bg-white">
