import React, { useMemo, useState } from 'react';
import { MealRecord } from '../types';

interface StatisticsProps {
  meals: MealRecord[];
}

type DisplayFilter = 'all' | 'protein' | 'kcal';

const Statistics: React.FC<StatisticsProps> = ({ meals }) => {
  const [filter, setFilter] = useState<DisplayFilter>('all');

  const TARGET_KCAL = 1500;
  const TARGET_PROTEIN = 100;
  const KCAL_THRESHOLD = 0.2; // 20%

  // 요일 헤더 (월~일) - Calendar.tsx와 동일하게 구성
  const weekDays = ['월', '화', '수', '목', '금', '토', '일'];

  // 일별 데이터 집계
  const dailyAggregates = useMemo(() => {
    const agg: Record<string, { kcal: number; protein: number; count: number }> = {};
    meals.forEach(m => {
      const date = m.date.split('T')[0];
      if (!agg[date]) agg[date] = { kcal: 0, protein: 0, count: 0 };
      agg[date].kcal += Number(m.kcal) || 0;
      agg[date].protein += Number(m.protein) || 0;
      agg[date].count += 1;
    });
    return agg;
  }, [meals]);

  // 최근 3개월 월별 데이터 생성 (요일 정렬 포함)
  const monthGrids = useMemo(() => {
    const months = [];
    const now = new Date();
    for (let i = 0; i < 3; i++) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const year = d.getFullYear();
      const month = d.getMonth();

      // 해당 월의 1일 요일 인덱스 (월0...일6)
      const firstDay = new Date(year, month, 1);
      const firstDayIdx = (firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1);

      const lastDay = new Date(year, month + 1, 0).getDate();

      const dates = [];
      // 1일 앞의 빈 공간 채우기
      for (let p = 0; p < firstDayIdx; p++) {
        dates.push(null);
      }
      // 실제 날짜 채우기
      for (let day = 1; day <= lastDay; day++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        dates.push(dateStr);
      }
      months.push({ year, month: month + 1, dates });
    }
    return months;
  }, []);

  const getStats = (date: string) => {
    const data = dailyAggregates[date];
    if (!data) return null;

    const isProteinSuccess = data.protein >= TARGET_PROTEIN;
    const isKcalSuccess = 
      data.kcal >= TARGET_KCAL * (1 - KCAL_THRESHOLD) && 
      data.kcal <= TARGET_KCAL * (1 + KCAL_THRESHOLD);

    return { isProteinSuccess, isKcalSuccess, ...data };
  };

  const perfectDaysCount = useMemo(() => {
    // d의 타입을 명시적으로 지정하여 unknown 타입 에러를 방지합니다.
    return Object.values(dailyAggregates).filter((d: { kcal: number; protein: number; count: number }) => {
      const isProteinSuccess = d.protein >= TARGET_PROTEIN;
      const isKcalSuccess = 
        d.kcal >= TARGET_KCAL * (1 - KCAL_THRESHOLD) && 
        d.kcal <= TARGET_KCAL * (1 + KCAL_THRESHOLD);
      return isProteinSuccess && isKcalSuccess;
    }).length;
  }, [dailyAggregates]);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8 pb-10">
      {/* 요약 카드 */}
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 p-6 rounded-[32px] text-white shadow-xl shadow-indigo-100">
        <h3 className="text-sm font-bold opacity-80 mb-1">나의 달성 기록</h3>
        <p className="text-4xl font-black mb-4">{perfectDaysCount} <span className="text-xl font-normal opacity-60 italic">Perfect Days</span></p>
        <div className="flex space-x-4 pt-4 border-t border-white/10">
          <div>
            <p className="text-[10px] opacity-60 font-bold uppercase">총 기록수</p>
            <p className="text-lg font-bold">{meals.length}회</p>
          </div>
          <div>
            <p className="text-[10px] opacity-60 font-bold uppercase">기록된 일수</p>
            <p className="text-lg font-bold">{Object.keys(dailyAggregates).length}일</p>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        {/* 필터 탭 */}
        <div className="flex bg-gray-100 p-1 rounded-2xl">
          <button 
            onClick={() => setFilter('all')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'all' ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'}`}
          >
            모두 보기
          </button>
          <button 
            onClick={() => setFilter('protein')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'protein' ? 'bg-white shadow-sm text-emerald-600' : 'text-gray-400'}`}
          >
            단백질만
          </button>
          <button 
            onClick={() => setFilter('kcal')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'kcal' ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'}`}
          >
            칼로리만
          </button>
        </div>

        <div className="space-y-8">
          {monthGrids.map(m => (
            <div key={`${m.year}-${m.month}`} className="bg-white p-5 rounded-[24px] shadow-sm border border-gray-100">
              <div className="flex justify-between items-center mb-4">
                <h5 className="text-sm font-black text-gray-800">{m.year}년 {m.month}월</h5>
                <div className="flex space-x-1">
                  {(filter === 'all' || filter === 'protein') && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>}
                  {(filter === 'all' || filter === 'kcal') && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>}
                </div>
              </div>

              {/* 요일 헤더 */}
              <div className="grid grid-cols-7 gap-1 mb-2">
                {weekDays.map(wd => (
                  <span key={wd} className="text-center text-[10px] font-bold text-gray-300 uppercase">{wd}</span>
                ))}
              </div>

              {/* 날짜 그리드 */}
              <div className="grid grid-cols-7 gap-1">
                {m.dates.map((date, idx) => {
                  if (!date) return <div key={`pad-${idx}`} className="aspect-square" />;

                  const stat = getStats(date);
                  const day = parseInt(date.split('-')[2]);

                  return (
                    <div 
                      key={date}
                      className={`relative aspect-square rounded-xl flex flex-col items-center justify-center transition-all ${stat ? 'bg-gray-50/50' : ''}`}
                    >
                      <span className={`text-[11px] font-bold ${stat ? 'text-gray-900' : 'text-gray-300'}`}>{day}</span>

                      {stat && (
                        <div className="flex space-x-0.5 mt-0.5">
                          {(filter === 'all' || filter === 'protein') && (
                            <div className={`w-1.5 h-1.5 rounded-full ${stat.isProteinSuccess ? 'bg-emerald-500' : 'bg-gray-200'}`} />
                          )}
                          {(filter === 'all' || filter === 'kcal') && (
                            <div className={`w-1.5 h-1.5 rounded-full ${stat.isKcalSuccess ? 'bg-indigo-500' : 'bg-gray-200'}`} />
                          )}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* 가이드 카드 */}
      <div className="bg-white p-6 rounded-[24px] border border-gray-100 text-xs text-gray-400 leading-relaxed">
        <p className="font-bold text-gray-800 mb-2">💡 통계 가이드</p>
        <ul className="space-y-1 list-disc pl-4">
          <li><span className="text-emerald-500 font-bold">초록색 점</span>: 단백질 100g 이상 섭취 성공</li>
          <li><span className="text-indigo-500 font-bold">보라색 점</span>: 1500kcal 기준 ±20% 범위 안착 성공</li>
          <li>기록이 없는 날은 점이 표시되지 않습니다.</li>
        </ul>
      </div>
    </div>
  );
};

export default Statistics;

import { GoogleGenAI } from "@google/genai";

/**
 * 쿠쿠님의 현재 영양 섭취 상태를 기반으로 Gemini AI 추천을 가져옵니다.
 */
export async function getAIRecommendation(currentKcal: number, currentProtein: number): Promise<string | undefined> {
  // Always use const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `당신은 쿠쿠님의 다정한 전담 영양사입니다. 
쿠쿠님의 현재 상태: 오늘 ${currentKcal.toFixed(0)}kcal 섭취, 단백질 ${currentProtein.toFixed(1)}g 섭취. 
일일 목표: 1500kcal, 단백질 100g. 
남은 할당량 내에서 먹어야 하는 단백질의 양과 kcal를 먼저 숫자로 명시하고, 부족한 양이 없다면 부족함 없이 잘 챙겨 섭취했다는 내용의 칭찬 한마디를 해주세요.
부족한 양이 있다면 남은 할당량 내에서 부족한 단백질을 채울 수 있는 맛있는 메뉴 1가지를 추천하고 응원 한 마디를 해주세요. 
답변은 다양한 이모지를 사용해서 한국어로 3문장 이내로 작성하세요.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    // Extracting Text Output from GenerateContentResponse using .text property (not a method).
    const text = response.text;

    if (!text) {
      return "AI가 답변을 생성하지 못했습니다. 잠시 후 다시 시도해 주세요.";
    }

    return text;
  } catch (error: any) {
    console.error("Gemini API Error:", error);

    if (error.message?.includes("API key not valid")) {
      return "설정된 API 키가 유효하지 않습니다. 키 값을 다시 확인해 주세요.";
    }

    return "AI 분석 중 오류가 발생했습니다. (네트워크 또는 서버 이슈)";
  }
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  deleteMealFromGAS,
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => {
    return meals.filter(m => String(m.date).startsWith(selectedDate));
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    return filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { kcal: 0, carbs: 0, protein: 0, fat: 0 });
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    const isUpdate = meals.some(m => m.uuid === newMeal.uuid);

    if (isUpdate) {
      setMeals(prev => prev.map(m => m.uuid === newMeal.uuid ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }

    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }

    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => m.uuid === newMeal.uuid ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals]);

  const onDeleteMeal = useCallback(async (uuid: string) => {
    if (!confirm('기록을 삭제할까요?')) return;
    const previousMeals = [...meals];
    setMeals(prev => prev.filter(m => m.uuid !== uuid));

    try {
      const success = await deleteMealFromGAS(uuid);
      if (!success) setMeals(previousMeals);
    } catch (err) {
      setMeals(previousMeals);
    }
  }, [meals]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    const target = ingredients.find(i => i.uuid === uuid);
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => i.uuid === uuid ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => i.uuid === uuid ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, []);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    setIngredients(prev => prev.map(i => i.uuid === ing.uuid ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, []);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => i.uuid !== uuid));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients]);

  const handleOpenQuickInput = () => {
    setEditMealTarget(null);
    setPrefilledType(null);
    setSelectedDate(getKSTDate());
    setIsInputOpen(true);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl">
      <header className="bg-indigo-600 text-white p-4 sticky top-0 z-50 shadow-lg flex items-center">
        <button 
          onClick={() => setIsSidebarOpen(true)}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
        <h1 className="ml-2 text-xl font-bold">
          {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
        </h1>
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar 
              selectedDate={selectedDate} 
              onSelectDate={setSelectedDate} 
              meals={meals}
            />

            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  onAdd={() => {
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                />
              ))}
            </div>

            <button 
              onClick={() => setAdviceModalOpen(true)}
