import React, { useState, useMemo } from 'react';
import { MealRecord } from '../types';

interface CalendarProps {
  selectedDate: string;
  onSelectDate: (date: string) => void;
  meals: MealRecord[];
}

const Calendar: React.FC<CalendarProps> = ({ selectedDate, onSelectDate, meals }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [viewMonth, setViewMonth] = useState(new Date(selectedDate));

  const getKSTToday = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const todayStr = getKSTToday();

  // 요일 헤더 (월~일)
  const weekDays = ['월', '화', '수', '목', '금', '토', '일'];

  // 식단 데이터가 있는 날짜들을 Set으로 관리
  const mealDates = useMemo(() => {
    const dates = new Set<string>();
    meals.forEach(m => {
      if (m.date) dates.add(m.date.split('T')[0]);
    });
    return dates;
  }, [meals]);

  // 선택된 날짜가 포함된 주의 월요일~일요일 구하기
  const currentWeek = useMemo(() => {
    const curr = new Date(selectedDate);
    const day = curr.getDay(); // 0(일) ~ 6(토)
    // 월요일 시작으로 변환 (월:0, ..., 일:6)
    const diff = curr.getDate() - (day === 0 ? 6 : day - 1);

    return Array.from({ length: 7 }, (_, i) => {
      const d = new Date(curr);
      d.setDate(diff + i);
      return d.toISOString().split('T')[0];
    });
  }, [selectedDate]);

  // 전체 달력용 날짜 계산 (월요일 시작 기준)
  const monthDays = useMemo(() => {
    const year = viewMonth.getFullYear();
    const month = viewMonth.getMonth();

    const firstDay = new Date(year, month, 1);
    const firstDayIdx = (firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1);

    const startDate = new Date(firstDay);
    startDate.setDate(firstDay.getDate() - firstDayIdx);

    return Array.from({ length: 42 }, (_, i) => {
      const d = new Date(startDate);
      d.setDate(startDate.getDate() + i);
      return d.toISOString().split('T')[0];
    });
  }, [viewMonth]);

  const changeMonth = (offset: number) => {
    const next = new Date(viewMonth);
    next.setMonth(next.getMonth() + offset);
    setViewMonth(next);
  };

  const handleGoToday = () => {
    const today = getKSTToday();
    onSelectDate(today);
    setViewMonth(new Date(today));
    // 선택한 날짜가 잘 보이도록 오늘로 가면 리스트 뷰를 유지하거나 상황에 맞게 처리
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden transition-all duration-300">
      {/* Header */}
      <div className="flex justify-between items-center p-4 pb-2">
        <button 
          onClick={() => setIsExpanded(!isExpanded)}
          className="flex items-center space-x-2 group"
        >
          <span className="text-lg font-black text-gray-800">
            {viewMonth.getFullYear()}년 {viewMonth.getMonth() + 1}월
          </span>
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className={`h-5 w-5 text-gray-400 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} 
            fill="none" viewBox="0 0 24 24" stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
        </button>

        <div className="flex items-center space-x-2">
          <button 
            onClick={handleGoToday}
            className="text-[10px] font-black px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-full hover:bg-indigo-100 transition-colors"
          >
            TODAY
          </button>

          {isExpanded && (
            <div className="flex space-x-1">
              <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 rounded-full">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                </svg>
              </button>
              <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 rounded-full">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                </svg>
              </button>
            </div>
          )}
        </div>
      </div>

      {/* 요일 라벨 */}
      <div className="grid grid-cols-7 gap-1 px-4 text-center">
        {weekDays.map(d => (
          <span key={d} className="text-[10px] font-bold text-gray-300 py-1 uppercase">{d}</span>
        ))}
      </div>

      {/* 날짜 그리드 */}
      <div className={`px-4 pb-4 transition-all duration-300 ease-in-out ${isExpanded ? 'max-h-96 opacity-100' : 'max-h-20 opacity-100'}`}>
        <div className="grid grid-cols-7 gap-1 mt-1">
          {(isExpanded ? monthDays : currentWeek).map((date) => {
            const d = new Date(date);
            const isSelected = date === selectedDate;
            const isToday = date === todayStr;
            const hasMeal = mealDates.has(date);
            const isCurrentMonth = d.getMonth() === viewMonth.getMonth();
            const dayNum = d.getDate();

            return (
              <button
                key={date}
                onClick={() => {
                  onSelectDate(date);
                  setViewMonth(new Date(date));
                }}
                className={`
                  relative flex flex-col items-center justify-center py-2 rounded-2xl transition-all h-12
                  ${isSelected ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 scale-105 z-10' : 'hover:bg-gray-50'}
                  ${!isSelected && isToday ? 'bg-indigo-50 text-indigo-600' : ''}
                  ${isExpanded && !isCurrentMonth ? 'opacity-20' : 'opacity-100'}
                `}
              >
                <span className={`text-sm font-bold ${isSelected ? 'text-white' : isToday ? 'text-indigo-600' : 'text-gray-700'}`}>
                  {dayNum}
                </span>
                {hasMeal && (
                  <span className={`absolute bottom-1.5 w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-indigo-500'}`}></span>
                )}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Calendar;

import React, { useMemo, useState } from 'react';
import { MealRecord } from '../types';

interface StatisticsProps {
  meals: MealRecord[];
  onDateSelect?: (date: string) => void;
}

type DisplayFilter = 'all' | 'protein' | 'kcal';

const Statistics: React.FC<StatisticsProps> = ({ meals, onDateSelect }) => {
  const [filter, setFilter] = useState<DisplayFilter>('all');

  const TARGET_KCAL = 1500;
  const TARGET_PROTEIN = 100;
  const KCAL_THRESHOLD = 0.2; // 20%

  // 요일 헤더 (월~일)
  const weekDays = ['월', '화', '수', '목', '금', '토', '일'];

  // 일별 데이터 집계
  const dailyAggregates = useMemo(() => {
    const agg: Record<string, { kcal: number; protein: number; count: number }> = {};
    meals.forEach(m => {
      const date = m.date.split('T')[0];
      if (!agg[date]) agg[date] = { kcal: 0, protein: 0, count: 0 };
      agg[date].kcal += Number(m.kcal) || 0;
      agg[date].protein += Number(m.protein) || 0;
      agg[date].count += 1;
    });
    return agg;
  }, [meals]);

  // 최근 3개월 월별 데이터 생성
  const monthGrids = useMemo(() => {
    const months = [];
    const now = new Date();
    for (let i = 0; i < 3; i++) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const year = d.getFullYear();
      const month = d.getMonth();

      const firstDay = new Date(year, month, 1);
      const firstDayIdx = (firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1);

      const lastDay = new Date(year, month + 1, 0).getDate();

      const dates = [];
      for (let p = 0; p < firstDayIdx; p++) {
        dates.push(null);
      }
      for (let day = 1; day <= lastDay; day++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        dates.push(dateStr);
      }
      months.push({ year, month: month + 1, dates });
    }
    return months;
  }, []);

  const getStats = (date: string) => {
    const data = dailyAggregates[date];
    if (!data) return null;

    const isProteinSuccess = data.protein >= TARGET_PROTEIN;
    const isKcalSuccess = 
      data.kcal >= TARGET_KCAL * (1 - KCAL_THRESHOLD) && 
      data.kcal <= TARGET_KCAL * (1 + KCAL_THRESHOLD);

    return { isProteinSuccess, isKcalSuccess, ...data };
  };

  const perfectDaysCount = useMemo(() => {
    return Object.values(dailyAggregates).filter((d: { kcal: number; protein: number; count: number }) => {
      const isProteinSuccess = d.protein >= TARGET_PROTEIN;
      const isKcalSuccess = 
        d.kcal >= TARGET_KCAL * (1 - KCAL_THRESHOLD) && 
        d.kcal <= TARGET_KCAL * (1 + KCAL_THRESHOLD);
      return isProteinSuccess && isKcalSuccess;
    }).length;
  }, [dailyAggregates]);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8 pb-10">
      {/* 요약 카드 */}
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 p-6 rounded-[32px] text-white shadow-xl shadow-indigo-100">
        <h3 className="text-sm font-bold opacity-80 mb-1">나의 달성 기록</h3>
        <p className="text-4xl font-black mb-4">{perfectDaysCount} <span className="text-xl font-normal opacity-60 italic">Perfect Days</span></p>
        <div className="flex space-x-4 pt-4 border-t border-white/10">
          <div>
            <p className="text-[10px] opacity-60 font-bold uppercase">총 기록수</p>
            <p className="text-lg font-bold">{meals.length}회</p>
          </div>
          <div>
            <p className="text-[10px] opacity-60 font-bold uppercase">기록된 일수</p>
            <p className="text-lg font-bold">{Object.keys(dailyAggregates).length}일</p>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        {/* 필터 탭 */}
        <div className="flex bg-gray-100 p-1 rounded-2xl">
          <button 
            onClick={() => setFilter('all')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'all' ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'}`}
          >
            모두 보기
          </button>
          <button 
            onClick={() => setFilter('protein')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'protein' ? 'bg-white shadow-sm text-emerald-600' : 'text-gray-400'}`}
          >
            단백질만
          </button>
          <button 
            onClick={() => setFilter('kcal')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'kcal' ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'}`}
          >
            칼로리만
          </button>
        </div>

        <div className="space-y-8">
          {monthGrids.map(m => (
            <div key={`${m.year}-${m.month}`} className="bg-white p-5 rounded-[24px] shadow-sm border border-gray-100">
              <div className="flex justify-between items-center mb-4">
                <h5 className="text-sm font-black text-gray-800">{m.year}년 {m.month}월</h5>
                <div className="flex space-x-1">
                  {(filter === 'all' || filter === 'protein') && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>}
                  {(filter === 'all' || filter === 'kcal') && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>}
                </div>
              </div>

              {/* 요일 헤더 */}
              <div className="grid grid-cols-7 gap-1 mb-2">
                {weekDays.map(wd => (
                  <span key={wd} className="text-center text-[10px] font-bold text-gray-300 uppercase">{wd}</span>
                ))}
              </div>

              {/* 날짜 그리드 */}
              <div className="grid grid-cols-7 gap-1">
                {m.dates.map((date, idx) => {
                  if (!date) return <div key={`pad-${idx}`} className="aspect-square" />;

                  const stat = getStats(date);
                  const day = parseInt(date.split('-')[2]);

                  return (
                    <div 
                      key={date}
                      onClick={() => onDateSelect && onDateSelect(date)}
                      className={`relative aspect-square rounded-xl flex flex-col items-center justify-center transition-all cursor-pointer hover:bg-gray-100 active:scale-90 ${stat ? 'bg-gray-50/50' : ''}`}
                    >
                      <span className={`text-[11px] font-bold ${stat ? 'text-gray-900' : 'text-gray-300'}`}>{day}</span>

                      {stat && (
                        <div className="flex space-x-0.5 mt-0.5">
                          {(filter === 'all' || filter === 'protein') && (
                            <div className={`w-1.5 h-1.5 rounded-full ${stat.isProteinSuccess ? 'bg-emerald-500' : 'bg-gray-200'}`} />
                          )}
                          {(filter === 'all' || filter === 'kcal') && (
                            <div className={`w-1.5 h-1.5 rounded-full ${stat.isKcalSuccess ? 'bg-indigo-500' : 'bg-gray-200'}`} />
                          )}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* 가이드 카드 */}
      <div className="bg-white p-6 rounded-[24px] border border-gray-100 text-xs text-gray-400 leading-relaxed">
        <p className="font-bold text-gray-800 mb-2">💡 통계 가이드</p>
        <ul className="space-y-1 list-disc pl-4">
          <li><span className="text-emerald-500 font-bold">초록색 점</span>: 단백질 100g 이상 섭취 성공</li>
          <li><span className="text-indigo-500 font-bold">보라색 점</span>: 1500kcal 기준 ±20% 범위 안착 성공</li>
          <li>날짜를 클릭하면 해당 일의 상세 식단을 볼 수 있습니다.</li>
        </ul>
      </div>
    </div>
  );
};

export default Statistics;

export enum MealType {
  BREAKFAST = '아침',
  LUNCH = '점심',
  SNACK = '간식',
  DINNER = '저녁'
}

export enum MealStatus {
  PLANNED = 'PLANNED',
  ACTUAL = 'ACTUAL'
}

export interface Ingredient {
  uuid: string;
  name: string;
  base_amount: number;
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  sugar: number;
  fiber: number;
  is_bookmarked?: boolean; // 즐겨찾기 여부
}

export interface MealRecord {
  uuid: string;
  type: MealType;
  status: MealStatus; // 예정(PLANNED) 또는 실제(ACTUAL)
  date: string; // YYYY-MM-DD
  time: string; // HH:mm
  ingredient_uuid: string;
  ingredient_name?: string; // 저장된 이름 (일회성 식단 대응)
  amount: number;
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  sugar: number;
  fiber: number;
  pending?: boolean; // For optimistic UI
}

export interface DailySummary {
  actual: {
    kcal: number;
    carbs: number;
    protein: number;
    fat: number;
  };
  planned: {
    kcal: number;
    carbs: number;
    protein: number;
    fat: number;
  };
}

function doGet(e) {
  const action = e.parameter.action;
  if (action === 'getData') {
    return ContentService.createTextOutput(JSON.stringify(getAllData()))
      .setMimeType(ContentService.MimeType.JSON);
  }
  return ContentService.createTextOutput('Hello GAS Backend');
}

function doPost(e) {
  const body = JSON.parse(e.postData.contents);
  const action = body.action;
  const data = body.data;

  if (action === 'saveMeal') {
    saveMeal(data);
  } else if (action === 'updateMeal') {
    updateRowByUuid('Meals', data.uuid, data);
  } else if (action === 'deleteMeal') {
    deleteRowByUuid('Meals', data.uuid);
  } else if (action === 'saveIngredient') {
    saveIngredient(data);
  } else if (action === 'updateIngredient') {
    updateRowByUuid('Ingredients', data.uuid, data);
  } else if (action === 'deleteIngredient') {
    deleteRowByUuid('Ingredients', data.uuid);
  } else if (action === 'updateBookmark') {
    updateBookmark(data.uuid, data.is_bookmarked);
  }

  return ContentService.createTextOutput(JSON.stringify({success: true}))
    .setMimeType(ContentService.MimeType.JSON);
}

function getSheets() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let ingredientsSheet = ss.getSheetByName('Ingredients');
  let mealsSheet = ss.getSheetByName('Meals');

  if (!ingredientsSheet) {
    ingredientsSheet = ss.insertSheet('Ingredients');
    ingredientsSheet.appendRow(['uuid', 'name', 'base_amount', 'kcal', 'carbs', 'protein', 'fat', 'sugar', 'fiber', 'is_bookmarked']);
  }

  if (!mealsSheet) {
    mealsSheet = ss.insertSheet('Meals');
    // status 컬럼 포함 헤더 정의
    mealsSheet.appendRow(['uuid', 'type', 'status', 'date', 'time', 'ingredient_name', 'ingredient_uuid', 'amount', 'kcal', 'carbs', 'protein', 'fat', 'sugar', 'fiber']);
  } else {
    // 기존 시트에 status 컬럼이 없는 경우 대응 (두 번째 열에 추가)
    const headers = mealsSheet.getRange(1, 1, 1, mealsSheet.getLastColumn()).getValues()[0];
    if (headers.indexOf('status') === -1) {
      mealsSheet.insertColumnAfter(2);
      mealsSheet.getRange(1, 3).setValue('status');
    }
  }

  return { ingredientsSheet, mealsSheet };
}

function getAllData() {
  const { ingredientsSheet, mealsSheet } = getSheets();
  const ingData = ingredientsSheet.getDataRange().getDisplayValues();
  const mealData = mealsSheet.getDataRange().getDisplayValues();
  return { 
    ingredients: dataToJson(ingData), 
    meals: dataToJson(mealData) 
  };
}

function dataToJson(data) {
  if (data.length <= 1) return [];
  const headers = data[0].map(h => String(h).trim().toLowerCase());
  const rows = data.slice(1);
  return rows.map(row => {
    const obj = {};
    headers.forEach((header, i) => {
      let val = row[i];
      obj[header] = (val !== null && val !== undefined) ? String(val).trim() : "";
    });
    return obj;
  });
}

function saveMeal(meal) {
  const { mealsSheet } = getSheets();
  const headers = mealsSheet.getRange(1, 1, 1, mealsSheet.getLastColumn()).getValues()[0].map(h => h.trim().toLowerCase());

  const rowData = headers.map(header => {
    if (header === 'uuid') return meal.uuid;
    if (header === 'type') return meal.type;
    if (header === 'status') return meal.status || 'ACTUAL';
    if (header === 'date') return meal.date;
    if (header === 'time') return meal.time;
    if (header === 'ingredient_name') return meal.ingredient_name || '';
    if (header === 'ingredient_uuid') return meal.ingredient_uuid;
    if (header === 'amount') return meal.amount;
    if (header === 'kcal') return meal.kcal;
    if (header === 'carbs') return meal.carbs;
    if (header === 'protein') return meal.protein;
    if (header === 'fat') return meal.fat;
    if (header === 'sugar') return meal.sugar;
    if (header === 'fiber') return meal.fiber;
    return '';
  });

  mealsSheet.appendRow(rowData);
}

function saveIngredient(ing) {
  const { ingredientsSheet } = getSheets();
  ingredientsSheet.appendRow([ing.uuid, ing.name, ing.base_amount, ing.kcal, ing.carbs, ing.protein, ing.fat, ing.sugar, ing.fiber, ing.is_bookmarked || false]);
}

function updateRowByUuid(sheetName, uuid, newData) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const data = sheet.getDataRange().getValues();
  const headers = data[0].map(h => String(h).trim().toLowerCase());
  const uuidIndex = headers.indexOf('uuid');

  for (let i = 1; i < data.length; i++) {
    if (String(data[i][uuidIndex]) === String(uuid)) {
      const row = headers.map(header => {
        if (newData[header] !== undefined) return newData[header];
        return data[i][headers.indexOf(header)];
      });
      sheet.getRange(i + 1, 1, 1, headers.length).setValues([row]);
      break;
    }
  }
}

function deleteRowByUuid(sheetName, uuid) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const data = sheet.getDataRange().getValues();
  const headers = data[0].map(h => String(h).trim().toLowerCase());
  const uuidIndex = headers.indexOf('uuid');

  for (let i = 1; i < data.length; i++) {
    if (String(data[i][uuidIndex]) === String(uuid)) {
      sheet.deleteRow(i + 1);
      break;
    }
  }
}

function updateBookmark(uuid, isBookmarked) {
  const { ingredientsSheet } = getSheets();
  const data = ingredientsSheet.getDataRange().getValues();
  const headers = data[0].map(h => String(h).trim().toLowerCase());
  const uuidIndex = headers.indexOf('uuid');
  const bookmarkIndex = headers.indexOf('is_bookmarked');

  for (let i = 1; i < data.length; i++) {
    if (String(data[i][uuidIndex]) === String(uuid)) {
      ingredientsSheet.getRange(i + 1, bookmarkIndex + 1).setValue(isBookmarked);
      break;
    }
  }
}

import { MealRecord, Ingredient, MealStatus } from '../types';

const GAS_WEB_APP_URL = 'https://script.google.com/macros/s/AKfycbz9j4qBdGB131uFq1sdgGvbjcdeGQuFSnXRSvQX3SescpIz6bjIbP84Vt4OZU64byih/exec';

export async function fetchInitialData(): Promise<{ meals: MealRecord[], ingredients: Ingredient[] }> {
  try {
    const response = await fetch(`${GAS_WEB_APP_URL}?action=getData`, {
      method: 'GET',
      redirect: 'follow'
    });

    if (!response.ok) {
      throw new Error(`GAS HTTP error! status: ${response.status}`);
    }

    const data = await response.json();

    const sanitizedIngredients = (data.ingredients || []).map((ing: any) => ({
      ...ing,
      is_bookmarked: String(ing.is_bookmarked).toLowerCase() === 'true',
      base_amount: Number(ing.base_amount) || 100,
      kcal: Number(ing.kcal) || 0,
      carbs: Number(ing.carbs) || 0,
      protein: Number(ing.protein) || 0,
      fat: Number(ing.fat) || 0,
      sugar: Number(ing.sugar) || 0,
      fiber: Number(ing.fiber) || 0
    }));

    const sanitizedMeals = (data.meals || []).map((meal: any) => ({
      ...meal,
      status: (meal.status as MealStatus) || MealStatus.ACTUAL,
      amount: Number(meal.amount) || 0,
      kcal: Number(meal.kcal) || 0,
      carbs: Number(meal.carbs) || 0,
      protein: Number(meal.protein) || 0,
      fat: Number(meal.fat) || 0,
      sugar: Number(meal.sugar) || 0,
      fiber: Number(meal.fiber) || 0
    }));

    return { meals: sanitizedMeals, ingredients: sanitizedIngredients };
  } catch (error) {
    console.error("Failed to fetch from GAS", error);
    return { meals: [], ingredients: [] };
  }
}

export async function saveMealToGAS(meal: MealRecord): Promise<boolean> {
  return callGAS('saveMeal', meal);
}

export async function updateMealInGAS(meal: MealRecord): Promise<boolean> {
  return callGAS('updateMeal', meal);
}

export async function deleteMealFromGAS(uuid: string): Promise<boolean> {
  return callGAS('deleteMeal', { uuid });
}

export async function saveIngredientToGAS(ingredient: Ingredient): Promise<boolean> {
  return callGAS('saveIngredient', ingredient);
}

export async function updateIngredientInGAS(ingredient: Ingredient): Promise<boolean> {
  return callGAS('updateIngredient', ingredient);
}

export async function deleteIngredientFromGAS(uuid: string): Promise<boolean> {
  return callGAS('deleteIngredient', { uuid });
}

export async function updateIngredientBookmark(uuid: string, isBookmarked: boolean): Promise<boolean> {
  return callGAS('updateBookmark', { uuid, is_bookmarked: isBookmarked });
}

async function callGAS(action: string, data: any): Promise<boolean> {
  try {
    const response = await fetch(GAS_WEB_APP_URL, {
      method: 'POST',
      redirect: 'follow',
      body: JSON.stringify({ action, data }),
    });
    return response.ok;
  } catch (e) {
    console.error(`GAS Action failed: ${action}`, e);
    return false;
  }
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  deleteMealFromGAS,
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => {
    return meals.filter(m => String(m.date).startsWith(selectedDate));
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };

    const actual = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((acc, cur) => ({
        kcal: acc.kcal + (Number(cur.kcal) || 0),
        carbs: acc.carbs + (Number(cur.carbs) || 0),
        protein: acc.protein + (Number(cur.protein) || 0),
        fat: acc.fat + (Number(cur.fat) || 0),
      }), { ...initial });

    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });

    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    const isUpdate = meals.some(m => m.uuid === newMeal.uuid);

    if (isUpdate) {
      setMeals(prev => prev.map(m => m.uuid === newMeal.uuid ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }

    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }

    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => m.uuid === newMeal.uuid ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals]);

  const handleToggleMealStatus = useCallback(async (uuid: string) => {
    const target = meals.find(m => m.uuid === uuid);
    if (!target) return;

    const nextStatus = target.status === MealStatus.ACTUAL ? MealStatus.PLANNED : MealStatus.ACTUAL;
    const updatedMeal: MealRecord = { 
      ...target, 
      status: nextStatus,
      // 실제 섭취로 전환할 때만 현재 시각으로 업데이트
      time: nextStatus === MealStatus.ACTUAL ? getKSTTime() : target.time,
      pending: true 
    };

    setMeals(prev => prev.map(m => m.uuid === uuid ? updatedMeal : m));

    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) {
        setMeals(prev => prev.map(m => m.uuid === uuid ? { ...updatedMeal, pending: false } : m));
      }
    } catch (err) {
      setMeals(prev => prev.map(m => m.uuid === uuid ? { ...target, pending: false } : m));
    }
  }, [meals]);

  const onDeleteMeal = useCallback(async (uuid: string) => {
    if (!confirm('기록을 삭제할까요?')) return;
    const previousMeals = [...meals];
    setMeals(prev => prev.filter(m => m.uuid !== uuid));

    try {
      const success = await deleteMealFromGAS(uuid);
      if (!success) setMeals(previousMeals);
    } catch (err) {
      setMeals(previousMeals);
    }
  }, [meals]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    const target = ingredients.find(i => i.uuid === uuid);
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => i.uuid === uuid ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => i.uuid === uuid ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, []);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    setIngredients(prev => prev.map(i => i.uuid === ing.uuid ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, []);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => i.uuid !== uuid));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients]);

  const handleOpenQuickInput = () => {
    setEditMealTarget(null);
    setPrefilledType(null);
    setSelectedDate(getKSTDate());
    setIsInputOpen(true);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl">
      <header className="bg-indigo-600 text-white p-4 sticky top-0 z-50 shadow-lg flex items-center">
        <button 
          onClick={() => setIsSidebarOpen(true)}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
        <h1 className="ml-2 text-xl font-bold">
          {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
        </h1>
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar 
              selectedDate={selectedDate} 
              onSelectDate={setSelectedDate} 
              meals={meals}
            />

            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  onAdd={() => {
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                  onToggleStatus={handleToggleMealStatus}
                />
              ))}
            </div>

            <button 
              onClick={() => setAdviceModalOpen(true)}
              className="w-full mt-8 py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"
            >
              <span className="text-xl">✨</span>
              <span>AI 영양 추천 받기</span>
            </button>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement 
            ingredients={ingredients}
            onToggleBookmark={handleToggleBookmark}
            onAddIngredient={handleAddIngredient}
            onUpdateIngredient={handleUpdateIngredient}
            onDeleteIngredient={handleDeleteIngredient}
          />
        ) : (
          <Statistics 
            meals={meals} 
            onDateSelect={(date) => {
              setSelectedDate(date);
              setCurrentView('main');
            }} 
          />
        )}
      </main>

      {currentView === 'main' && (
        <button 
          onClick={handleOpenQuickInput}
          className="fixed bottom-6 right-6 w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 hover:scale-105 transition-all animate-in zoom-in slide-in-from-bottom-10 duration-500"
          aria-label="식단 추가"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
          </svg>
        </button>
      )}

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => {
            setIsInputOpen(false);
            setEditMealTarget(null);
          }}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          editTarget={editMealTarget}
          ingredients={ingredients}
          onSave={onSaveMeal}
          onDelete={onDeleteMeal}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.actual.kcal}
          currentProtein={summary.actual.protein}
        />
      )}
    </div>
  );
};

export default App;

