const SwipeableMealCard: React.FC<{ 
  meal: MealRecord; 
  displayName: string;
  onEdit: (meal: MealRecord) => void;
  onSetStatus: (uuid: string, status: MealStatus) => void;
}> = ({ meal, displayName, onEdit, onSetStatus }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const bgActualRef = useRef<HTMLDivElement>(null);
  const bgPlannedRef = useRef<HTMLDivElement>(null);

  const startX = useRef(0);
  const currentDiff = useRef(0);
  const isDragging = useRef(false);
  const threshold = 80; // 스와이프 발동 기준

  const updateStyles = (diff: number) => {
    if (!cardRef.current) return;
    const dragX = diff * 0.6; // 저항 계수

    // 카드 위치 직접 이동 (translate3d로 하드웨어 가속)
    cardRef.current.style.transform = `translate3d(${dragX}px, 0, 0)`;

    // 실제 섭취(Actual) 피드백 (오른쪽 드래그)
    if (bgActualRef.current) {
      const opacity = Math.min(Math.max(dragX / 60, 0), 1);
      bgActualRef.current.style.opacity = opacity.toString();
      bgActualRef.current.style.transform = `scale(${0.9 + opacity * 0.1})`;
    }

    // 예정 식단(Planned) 피드백 (왼쪽 드래그)
    if (bgPlannedRef.current) {
      const opacity = Math.min(Math.max(-dragX / 60, 0), 1);
      bgPlannedRef.current.style.opacity = opacity.toString();
      bgPlannedRef.current.style.transform = `scale(${0.9 + opacity * 0.1})`;
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    if (meal.pending) return;
    startX.current = e.touches[0].clientX;
    isDragging.current = true;
    if (cardRef.current) {
      cardRef.current.style.transition = 'none'; // 드래그 중에는 애니메이션 끔
    }
  };

  const onTouchMove = (e: React.TouchEvent) => {
    if (!isDragging.current) return;
    currentDiff.current = e.touches[0].clientX - startX.current;

    // 성능을 위해 rAF(requestAnimationFrame) 사용
    requestAnimationFrame(() => {
      updateStyles(currentDiff.current);
    });
  };

  const onTouchEnd = () => {
    if (!isDragging.current) return;
    isDragging.current = false;

    const dragX = currentDiff.current * 0.6;

    // 원복 애니메이션 설정
    if (cardRef.current) {
      cardRef.current.style.transition = 'transform 0.4s cubic-bezier(0.25, 1, 0.5, 1)';
      cardRef.current.style.transform = `translate3d(0, 0, 0)`;
    }

    // 배경 피드백 페이드 아웃
    if (bgActualRef.current) bgActualRef.current.style.opacity = '0';
    if (bgPlannedRef.current) bgPlannedRef.current.style.opacity = '0';

    // 임계값 확인 후 상태 변경 실행
    if (dragX > threshold) {
      onSetStatus(meal.uuid, MealStatus.ACTUAL);
    } else if (dragX < -threshold) {
      onSetStatus(meal.uuid, MealStatus.PLANNED);
    }

    currentDiff.current = 0;
  };

  const isPlanned = meal.status === MealStatus.PLANNED;

  return (
    <div className="relative overflow-hidden rounded-xl bg-gray-100 touch-pan-y">
      {/* Background Actions Layer */}
      <div className="absolute inset-0 flex items-center justify-between px-6 z-0 pointer-events-none">
        <div ref={bgActualRef} className="opacity-0 flex items-center space-x-2 transition-opacity duration-200">
          <div className="w-9 h-9 rounded-full bg-green-500 flex items-center justify-center shadow-lg text-white">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
             </svg>
          </div>
          <span className="text-[10px] font-black text-green-600 uppercase tracking-tighter">Actual</span>
        </div>
        <div ref={bgPlannedRef} className="opacity-0 flex items-center space-x-2 transition-opacity duration-200">
          <span className="text-[10px] font-black text-gray-500 uppercase tracking-tighter">Planned</span>
          <div className="w-9 h-9 rounded-full bg-gray-400 flex items-center justify-center shadow-lg text-white">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <rect x="3" y="3" width="18" height="18" rx="4" strokeWidth="2" />
             </svg>
          </div>
        </div>
      </div>

      {/* Main Content Card Layer */}
      <div 
        ref={cardRef}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        onClick={() => onEdit(meal)}
        className={`relative z-10 flex-1 text-left p-4 rounded-xl shadow-sm flex justify-between items-center border-l-4 will-change-transform cursor-pointer select-none ${
          meal.pending ? 'opacity-50 grayscale border-gray-300 cursor-wait' : 
          isPlanned ? 'bg-gray-50 border-gray-300 border-dashed' : 'bg-white border-indigo-500 hover:border-indigo-600'
        }`}
      >
        <div className="flex-1">
          <div className="flex items-center space-x-2">
            <p className={`font-bold text-sm ${isPlanned ? 'text-gray-400 italic' : 'text-gray-800'}`}>
              {displayName}
              {isPlanned && <span className="ml-2 text-[9px] bg-gray-200 text-gray-500 px-1.5 py-0.5 rounded-sm font-black not-italic uppercase tracking-tighter">Planned</span>}
            </p>
          </div>
          <p className="text-xs text-gray-400 font-medium">{meal.amount}g • {meal.time}</p>
        </div>
        <div className="text-right">
          <p className={`font-black tracking-tight ${isPlanned ? 'text-gray-300' : 'text-indigo-600'}`}>
            {Math.round(meal.kcal)} <span className="text-[9px] font-bold opacity-50 ml-0.5">kcal</span>
          </p>
          <div className="flex space-x-2 text-[10px] text-gray-400 justify-end font-bold">
            <span className={!isPlanned ? 'text-emerald-500/80' : ''}>P {Math.round(meal.protein || 0)}g</span>
            <span>C {Math.round(meal.carbs || 0)}g</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealSection;

import React, { useState, useMemo, useEffect } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => void;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  // 상태 선택 UI를 제거하고, 기본값은 ACTUAL로 설정 (수동 PLANNED 전환은 스와이프로 유도)
  const [status, setStatus] = useState<MealStatus>(editTarget?.status || MealStatus.ACTUAL);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    editTarget ? (ingredients.find(i => i.uuid === editTarget.ingredient_uuid) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newName, setNewName] = useState('');
  const [newBase, setNewBase] = useState('1');
  const [newKcal, setNewKcal] = useState('');
  const [newCarbs, setNewCarbs] = useState('');
  const [newProtein, setNewProtein] = useState('');
  const [newFat, setNewFat] = useState('');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  useEffect(() => {
    if (isAddingNew) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated > 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew]);

  useEffect(() => {
    if (!prefilledType && !editTarget) {
      const h = parseInt(time.split(':')[0]);
      const m = parseInt(time.split(':')[1]);
      const totalMin = h * 60 + m;
      if (totalMin >= 360 && totalMin < 720) setType(MealType.BREAKFAST);
      else if (totalMin >= 720 && totalMin < 840) setType(MealType.LUNCH);
      else if (totalMin >= 840 && totalMin < 1080) setType(MealType.SNACK);
      else setType(MealType.DINNER);
    }
  }, [time, prefilledType, editTarget]);

  const bookmarkedIngredients = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 8);
  }, [ingredients]);

  const filteredIngredients = useMemo(() => {
    if (!searchTerm) return [];
    return ingredients
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => (b.is_bookmarked ? 1 : 0) - (a.is_bookmarked ? 1 : 0))
      .slice(0, 8);
  }, [searchTerm, ingredients]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const factor = parseFloat(amount) / (parseFloat(newBase) || 1);
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
        sugar: 0,
        fiber: 0,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
      sugar: (ing.sugar || 0) * factor,
      fiber: (ing.fiber || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (keepOpen: boolean) => {
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = selectedIngredient?.name || newName || '직접 입력 식단';
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    const newMeal: MealRecord = {
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status,
      date,
      time,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      ...preview
    };

    onSave(newMeal, newIngData);

    if (keepOpen) {
      setSearchTerm('');
      setSelectedIngredient(null);
      setAmount('1');
      setIsAddingNew(false);
      setNewName('');
      setNewKcal('');
      setNewCarbs('');
      setNewProtein('');
      setNewFat('');
      setShouldSaveToIngredients(false);
    } else {
      onClose();
    }
  };

  const handleDelete = () => {
    if (editTarget && onDelete) {
      onDelete(editTarget.uuid);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4">
      <div className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 duration-500">
        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-6 overflow-y-auto">
          {/* 실제/예정 스위치 제거됨: 입력 시 기본은 ACTUAL이며 상세 변경은 메인 리스트 스와이프로 유도 */}

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">날짜</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">시간</label>
              <input type="time" value={time} onChange={e => setTime(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식사 분류</label>
            <div className="flex bg-gray-100 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(t => (
                <button
                  key={t}
                  onClick={() => setType(t)}
                  className={`flex-1 py-2 text-xs rounded-xl transition-all ${type === t ? 'bg-white shadow-md font-black text-indigo-600' : 'text-gray-400'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-4">
              <div className="space-y-2">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">식재료 검색</label>
                  <button onClick={() => setIsAddingNew(true)} className="text-[10px] font-black text-indigo-600 underline">직접 입력하기</button>
                </div>
                <div className="relative">
                  <input autoFocus type="text" placeholder="식재료 검색..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white shadow-sm font-medium" />
                </div>
              </div>
              <div className="space-y-2">
                {filteredIngredients.map(i => (
                  <button key={i.uuid} onClick={() => { setSelectedIngredient(i); setSearchTerm(''); }} className="w-full text-left p-4 bg-white border border-gray-100 hover:border-indigo-500 rounded-2xl flex justify-between items-center transition-all shadow-sm group">
                    <div className="flex items-center space-x-3">
                      {i.is_bookmarked && <span className="text-amber-400">★</span>}
                      <span className="font-bold text-gray-800">{i.name}</span>
                    </div>
                    <span className="text-[10px] text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">{i.kcal} kcal / {i.base_amount}g</span>
                  </button>
                ))}
              </div>
            </div>
          ) : isAddingNew ? (
            <div className="space-y-5 bg-indigo-50/30 p-5 rounded-[32px] border border-indigo-100 animate-in zoom-in duration-300">
               <div className="flex justify-between items-center">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-widest">직접 입력</h3>
                <button onClick={() => setIsAddingNew(false)} className="text-[10px] text-gray-400 underline font-bold">돌아가기</button>
              </div>
              <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름 (예: 엄마표 볶음밥)" className="w-full p-4 rounded-2xl border bg-white shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none" />
              <div className="grid grid-cols-3 gap-3">
                  <input type="number" placeholder="탄(g)" value={newCarbs} onChange={e => setNewCarbs(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                  <input type="number" placeholder="단(g)" value={newProtein} onChange={e => setNewProtein(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                  <input type="number" placeholder="지(g)" value={newFat} onChange={e => setNewFat(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
              </div>
              <div className="pt-4 border-t border-indigo-100">
                <label className="block text-[10px] font-black text-indigo-600 mb-2 uppercase">양 (g)</label>
                <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-6 rounded-3xl border-2 border-indigo-500 text-4xl font-black text-center bg-white" />
              </div>
            </div>
          ) : (
            <div className="bg-indigo-50/50 p-6 rounded-[40px] flex flex-col space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-black text-indigo-600 text-2xl">{selectedIngredient?.name}</h3>
                  <p className="text-xs text-gray-400">{selectedIngredient?.base_amount}g 당 {selectedIngredient?.kcal}kcal</p>
                </div>
                {!editTarget && <button onClick={() => setSelectedIngredient(null)} className="text-xs text-indigo-400 font-bold underline bg-white px-3 py-1 rounded-full">변경</button>}
              </div>
              <div className="space-y-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase">양 (g)</label>
                <input autoFocus type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-6 bg-white rounded-3xl border-none ring-2 ring-indigo-500 text-4xl font-black focus:ring-4 outline-none text-center" />
              </div>
              {preview && (
                <div className="grid grid-cols-4 gap-2 bg-indigo-600 p-4 rounded-3xl text-white text-center">
                  <div><p className="text-[8px] opacity-70 uppercase font-black">kcal</p><p className="font-black text-lg">{Math.round(preview.kcal)}</p></div>
                  <div><p className="text-[8px] opacity-70 uppercase font-black">탄</p><p className="font-bold">{Math.round(preview.carbs)}g</p></div>
                  <div><p className="text-[8px] opacity-70 uppercase font-black">단</p><p className="font-bold">{Math.round(preview.protein)}g</p></div>
                  <div><p className="text-[8px] opacity-70 uppercase font-black">지</p><p className="font-bold">{Math.round(preview.fat)}g</p></div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="p-6 border-t bg-gray-50 flex space-x-3 sticky bottom-0">
          {editTarget && (
            <button onClick={handleDelete} className="px-6 py-4 bg-red-50 text-red-500 font-black rounded-2xl border border-red-100 transition-all text-sm">삭제</button>
          )}
          {!editTarget && (
            <button disabled={!preview} onClick={() => handleSave(true)} className="flex-1 py-4 px-2 border-2 border-indigo-600 text-indigo-600 font-black rounded-2xl disabled:opacity-30 transition-all text-sm">+ 계속 추가</button>
          )}
          <button disabled={!preview} onClick={() => handleSave(false)} className="flex-1 py-4 px-2 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 active:scale-95 disabled:opacity-30 transition-all text-sm">
            {editTarget ? '기록 업데이트' : '저장 후 닫기'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default MealInputForm;

import React, { useState, useMemo } from 'react';
import { Ingredient } from '../types';

interface Props {
  ingredients: Ingredient[];
  onToggleBookmark: (uuid: string) => void;
  onAddIngredient: (ing: Ingredient) => void;
  onUpdateIngredient: (ing: Ingredient) => void;
  onDeleteIngredient: (uuid: string) => void;
}

const IngredientManagement: React.FC<Props> = ({ ingredients, onToggleBookmark, onAddIngredient, onUpdateIngredient, onDeleteIngredient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [editTarget, setEditTarget] = useState<Ingredient | null>(null);
  const [isAdding, setIsAdding] = useState(false);

  const sortedIngredients = useMemo(() => {
    return [...ingredients]
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => {
        // 북마크 여부 우선순위 (Boolean 강제 변환 후 비교)
        const aBooked = !!a.is_bookmarked;
        const bBooked = !!b.is_bookmarked;

        if (aBooked && !bBooked) return -1;
        if (!aBooked && bBooked) return 1;

        // 북마크 여부가 같으면 이름순 정렬
        return a.name.localeCompare(b.name);
      });
  }, [ingredients, searchTerm]);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-black text-gray-800">식재료 관리</h2>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-lg shadow-indigo-100 flex items-center space-x-2 active:scale-95 transition-transform"
        >
          <span>+ 등록</span>
        </button>
      </div>

      <div className="relative">
        <input 
          type="text" 
          placeholder="식재료 이름 검색..." 
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white p-4 pr-12 rounded-2xl shadow-sm border border-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
        />
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 absolute right-4 top-1/2 -translate-y-1/2 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
        </svg>
      </div>

      <div className="grid grid-cols-1 gap-3 pb-24">
        {sortedIngredients.length === 0 ? (
          <div className="py-20 text-center text-gray-400 italic">
            검색 결과가 없습니다.
          </div>
        ) : (
          sortedIngredients.map(ing => (
            <button 
              key={ing.uuid} 
              onClick={() => setEditTarget(ing)}
              className={`w-full text-left bg-white p-4 rounded-2xl shadow-sm border flex justify-between items-center group relative overflow-hidden active:scale-[0.98] transition-all ${ing.is_bookmarked ? 'border-amber-200 ring-1 ring-amber-100' : 'border-gray-50'}`}
            >
              {ing.is_bookmarked && (
                <div className="absolute top-0 left-0 w-1 h-full bg-amber-400"></div>
              )}
              <div className="flex items-center space-x-4">
                <div 
                  onClick={(e) => {
                    e.stopPropagation();
                    onToggleBookmark(ing.uuid);
                  }}
                  className={`p-2 rounded-full transition-all ${ing.is_bookmarked ? 'bg-amber-50 text-amber-500 scale-110 shadow-sm' : 'text-gray-300 hover:text-amber-400'}`}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                  </svg>
                </div>
                <div>
                  <h4 className="font-bold text-gray-800 flex items-center">
                    {ing.name}
                  </h4>
                  <p className="text-xs text-gray-400">기준: {ing.base_amount}g / {ing.kcal}kcal</p>
                </div>
              </div>
              <div className="text-right flex flex-col items-end">
                <div className="flex space-x-2 text-[10px] font-bold text-gray-400 uppercase">
                  <span className="text-indigo-600">P {ing.protein}g</span>
                  <span>C {ing.carbs}g</span>
                </div>
              </div>
            </button>
          ))
        )}
      </div>

      {(isAdding || editTarget) && (
        <IngredientFormModal 
          target={editTarget} 
          onClose={() => { setIsAdding(false); setEditTarget(null); }} 
          onDelete={onDeleteIngredient}
          onSave={(data) => {
            if (editTarget) onUpdateIngredient(data);
            else onAddIngredient(data);
            setIsAdding(false);
            setEditTarget(null);
          }} 
        />
      )}
    </div>
  );
};

const IngredientFormModal: React.FC<{ target: Ingredient | null, onClose: () => void, onSave: (ing: Ingredient) => void, onDelete: (uuid: string) => void }> = ({ target, onClose, onSave, onDelete }) => {
  const [formData, setFormData] = useState({
    name: target?.name || '', 
    base: target?.base_amount?.toString() || '1', 
    kcal: target?.kcal?.toString() || '', 
    carbs: target?.carbs?.toString() || '', 
    protein: target?.protein?.toString() || '', 
    fat: target?.fat?.toString() || ''
  });

  const handleSave = () => {
    if (!formData.name || !formData.kcal) return;
    onSave({
      uuid: target?.uuid || crypto.randomUUID(),
      name: formData.name,
      base_amount: parseFloat(formData.base),
      kcal: parseFloat(formData.kcal),
      carbs: parseFloat(formData.carbs || '0'),
      protein: parseFloat(formData.protein || '0'),
      fat: parseFloat(formData.fat || '0'),
      sugar: target?.sugar || 0,
      fiber: target?.fiber || 0,
      is_bookmarked: target?.is_bookmarked || false
    });
  };

  const handleDelete = () => {
    if (target && confirm('이 식재료를 삭제할까요?')) {
      onDelete(target.uuid);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-sm rounded-3xl overflow-hidden shadow-2xl">
        <div className="p-6 bg-indigo-600 text-white">
          <h3 className="text-xl font-bold">{target ? '식재료 수정' : '신규 식재료 등록'}</h3>
        </div>
        <div className="p-6 space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">식재료 이름</label>
            <input 
              placeholder="식재료 이름" 
              value={formData.name} 
              onChange={e => setFormData({...formData, name: e.target.value})}
              className="w-full p-3 bg-gray-50 rounded-xl border focus:ring-2 focus:ring-indigo-500 outline-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">기준(g)</label>
              <input value={formData.base} onChange={e => setFormData({...formData, base: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">칼로리(kcal)</label>
              <input value={formData.kcal} onChange={e => setFormData({...formData, kcal: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">탄수화물(g)</label>
              <input placeholder="탄수화물" value={formData.carbs} onChange={e => setFormData({...formData, carbs: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">단백질(g)</label>
              <input placeholder="단백질" value={formData.protein} onChange={e => setFormData({...formData, protein: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
          </div>
          <div className="flex space-x-3 pt-4">
            {target && (
              <button onClick={handleDelete} className="px-4 py-3 bg-red-50 text-red-500 font-bold border border-red-100 rounded-xl active:scale-95 transition-transform">삭제</button>
            )}
            <button onClick={onClose} className="flex-1 py-3 text-gray-400 font-bold border rounded-xl">취소</button>
            <button onClick={handleSave} className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg active:scale-95 transition-transform">저장</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default IngredientManagement;

import React, { useState, useMemo, useEffect } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => void;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  // 상태 선택 UI를 제거하고, 기본값은 ACTUAL로 설정 (수동 PLANNED 전환은 스와이프로 유도)
  const [status, setStatus] = useState<MealStatus>(editTarget?.status || MealStatus.ACTUAL);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    editTarget ? (ingredients.find(i => i.uuid === editTarget.ingredient_uuid) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newName, setNewName] = useState('');
  const [newBase, setNewBase] = useState('1');
  const [newKcal, setNewKcal] = useState('');
  const [newCarbs, setNewCarbs] = useState('');
  const [newProtein, setNewProtein] = useState('');
  const [newFat, setNewFat] = useState('');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  useEffect(() => {
    if (isAddingNew) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated > 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew]);

  useEffect(() => {
    if (!prefilledType && !editTarget) {
      const h = parseInt(time.split(':')[0]);
      const m = parseInt(time.split(':')[1]);
      const totalMin = h * 60 + m;
      if (totalMin >= 360 && totalMin < 720) setType(MealType.BREAKFAST);
      else if (totalMin >= 720 && totalMin < 840) setType(MealType.LUNCH);
      else if (totalMin >= 840 && totalMin < 1080) setType(MealType.SNACK);
      else setType(MealType.DINNER);
    }
  }, [time, prefilledType, editTarget]);

  const bookmarkedIngredients = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 12);
  }, [ingredients]);

  const filteredIngredients = useMemo(() => {
    if (!searchTerm) return [];
    return ingredients
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => (b.is_bookmarked ? 1 : 0) - (a.is_bookmarked ? 1 : 0))
      .slice(0, 8);
  }, [searchTerm, ingredients]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const factor = parseFloat(amount) / (parseFloat(newBase) || 1);
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
        sugar: 0,
        fiber: 0,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
      sugar: (ing.sugar || 0) * factor,
      fiber: (ing.fiber || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (keepOpen: boolean) => {
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = selectedIngredient?.name || newName || '직접 입력 식단';
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    const newMeal: MealRecord = {
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status,
      date,
      time,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      ...preview
    };

    onSave(newMeal, newIngData);

    if (keepOpen) {
      setSearchTerm('');
      setSelectedIngredient(null);
      setAmount('1');
      setIsAddingNew(false);
      setNewName('');
      setNewKcal('');
      setNewCarbs('');
      setNewProtein('');
      setNewFat('');
      setShouldSaveToIngredients(false);
    } else {
      onClose();
    }
  };

  const handleDelete = () => {
    if (editTarget && onDelete) {
      onDelete(editTarget.uuid);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4">
      <div className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 duration-500">
        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-6 overflow-y-auto">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">날짜</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">시간</label>
              <input type="time" value={time} onChange={e => setTime(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식사 분류</label>
            <div className="flex bg-gray-100 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(t => (
                <button
                  key={t}
                  onClick={() => setType(t)}
                  className={`flex-1 py-2 text-xs rounded-xl transition-all ${type === t ? 'bg-white shadow-md font-black text-indigo-600' : 'text-gray-400'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-6">
              <div className="space-y-2">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">식재료 검색</label>
                  <button onClick={() => setIsAddingNew(true)} className="text-[10px] font-black text-indigo-600 underline">직접 입력하기</button>
                </div>
                <div className="relative">
                  <input autoFocus type="text" placeholder="식재료 검색..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white shadow-sm font-medium" />
                </div>
              </div>

              {/* 검색어 없을 때 즐겨찾기 목록 표시 */}
              {!searchTerm && bookmarkedIngredients.length > 0 && (
                <div className="space-y-3 animate-in fade-in duration-500">
                  <div className="flex items-center space-x-2 px-1">
                    <span className="text-amber-400 text-xs">★</span>
                    <label className="text-[10px] font-black text-gray-400 uppercase">자주 먹는 식재료</label>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    {bookmarkedIngredients.map(i => (
                      <button 
                        key={i.uuid} 
                        onClick={() => setSelectedIngredient(i)}
                        className="p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-left hover:bg-indigo-100 transition-colors group"
                      >
                        <p className="text-xs font-bold text-indigo-900 line-clamp-1">{i.name}</p>
                        <p className="text-[9px] text-indigo-400 font-medium">{i.kcal}kcal / {i.base_amount}g</p>
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {searchTerm && (
                <div className="space-y-2 animate-in slide-in-from-top-2 duration-300">
                  {filteredIngredients.map(i => (
                    <button key={i.uuid} onClick={() => { setSelectedIngredient(i); setSearchTerm(''); }} className="w-full text-left p-4 bg-white border border-gray-100 hover:border-indigo-500 rounded-2xl flex justify-between items-center transition-all shadow-sm group">
                      <div className="flex items-center space-x-3">
                        {i.is_bookmarked && <span className="text-amber-400">★</span>}
                        <span className="font-bold text-gray-800">{i.name}</span>
                      </div>
                      <span className="text-[10px] text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">{i.kcal} kcal / {i.base_amount}g</span>
                    </button>
                  ))}
                  {filteredIngredients.length === 0 && (
                    <div className="text-center py-6 text-xs text-gray-400">
                      검색 결과가 없습니다.
                    </div>
                  )}
                </div>
              )}
            </div>
          ) : isAddingNew ? (
            <div className="space-y-5 bg-indigo-50/30 p-5 rounded-[32px] border border-indigo-100 animate-in zoom-in duration-300">
               <div className="flex justify-between items-center">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-widest">직접 입력</h3>
                <button onClick={() => setIsAddingNew(false)} className="text-[10px] text-gray-400 underline font-bold">돌아가기</button>
              </div>
              <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름 (예: 엄마표 볶음밥)" className="w-full p-4 rounded-2xl border bg-white shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none" />
              <div className="grid grid-cols-3 gap-3">
                  <input type="number" placeholder="탄(g)" value={newCarbs} onChange={e => setNewCarbs(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                  <input type="number" placeholder="단(g)" value={newProtein} onChange={e => setNewProtein(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                  <input type="number" placeholder="지(g)" value={newFat} onChange={e => setNewFat(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
              </div>
              <div className="pt-4 border-t border-indigo-100">
                <label className="block text-[10px] font-black text-indigo-600 mb-2 uppercase">양 (g)</label>
                <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-6 rounded-3xl border-2 border-indigo-500 text-4xl font-black text-center bg-white" />
              </div>
            </div>
          ) : (
            <div className="bg-indigo-50/50 p-6 rounded-[40px] flex flex-col space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-black text-indigo-600 text-2xl">{selectedIngredient?.name}</h3>
                  <p className="text-xs text-gray-400">{selectedIngredient?.base_amount}g 당 {selectedIngredient?.kcal}kcal</p>
                </div>
                {!editTarget && <button onClick={() => setSelectedIngredient(null)} className="text-xs text-indigo-400 font-bold underline bg-white px-3 py-1 rounded-full">변경</button>}
              </div>
              <div className="space-y-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase">양 (g)</label>
                <input autoFocus type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-6 bg-white rounded-3xl border-none ring-2 ring-indigo-500 text-4xl font-black focus:ring-4 outline-none text-center" />
              </div>
              {preview && (
                <div className="grid grid-cols-4 gap-2 bg-indigo-600 p-4 rounded-3xl text-white text-center">
                  <div><p className="text-[8px] opacity-70 uppercase font-black">kcal</p><p className="font-black text-lg">{Math.round(preview.kcal)}</p></div>
                  <div><p className="text-[8px] opacity-70 uppercase font-black">탄</p><p className="font-bold">{Math.round(preview.carbs)}g</p></div>
                  <div><p className="text-[8px] opacity-70 uppercase font-black">단</p><p className="font-bold">{Math.round(preview.protein)}g</p></div>
                  <div><p className="text-[8px] opacity-70 uppercase font-black">지</p><p className="font-bold">{Math.round(preview.fat)}g</p></div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="p-6 border-t bg-gray-50 flex space-x-3 sticky bottom-0">
          {editTarget && (
            <button onClick={handleDelete} className="px-6 py-4 bg-red-50 text-red-500 font-black rounded-2xl border border-red-100 transition-all text-sm">삭제</button>
          )}
          {!editTarget && (
            <button disabled={!preview} onClick={() => handleSave(true)} className="flex-1 py-4 px-2 border-2 border-indigo-600 text-indigo-600 font-black rounded-2xl disabled:opacity-30 transition-all text-sm">+ 계속 추가</button>
          )}
          <button disabled={!preview} onClick={() => handleSave(false)} className="flex-1 py-4 px-2 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 active:scale-95 disabled:opacity-30 transition-all text-sm">
            {editTarget ? '기록 업데이트' : '저장 후 닫기'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default MealInputForm;

import React, { useMemo, useState } from 'react';
import { MealRecord, MealStatus } from '../types';

interface StatisticsProps {
  meals: MealRecord[];
  onDateSelect?: (date: string) => void;
}

type DisplayFilter = 'all' | 'protein' | 'kcal';

const Statistics: React.FC<StatisticsProps> = ({ meals, onDateSelect }) => {
  const [filter, setFilter] = useState<DisplayFilter>('all');

  const TARGET_KCAL = 1500;
  const TARGET_PROTEIN = 100;
  const KCAL_THRESHOLD = 0.2; // 20%

  // 요일 헤더 (월~일)
  const weekDays = ['월', '화', '수', '목', '금', '토', '일'];

  // 실제 섭취 데이터만 필터링
  const actualMeals = useMemo(() => {
    return meals.filter(m => m.status === MealStatus.ACTUAL);
  }, [meals]);

  // 일별 데이터 집계 (실제 섭취 기준)
  const dailyAggregates = useMemo(() => {
    const agg: Record<string, { kcal: number; protein: number; count: number }> = {};
    actualMeals.forEach(m => {
      const date = m.date.split('T')[0];
      if (!agg[date]) agg[date] = { kcal: 0, protein: 0, count: 0 };
      agg[date].kcal += Number(m.kcal) || 0;
      agg[date].protein += Number(m.protein) || 0;
      agg[date].count += 1;
    });
    return agg;
  }, [actualMeals]);

  // 최근 3개월 월별 데이터 생성
  const monthGrids = useMemo(() => {
    const months = [];
    const now = new Date();
    for (let i = 0; i < 3; i++) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const year = d.getFullYear();
      const month = d.getMonth();

      const firstDay = new Date(year, month, 1);
      const firstDayIdx = (firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1);

      const lastDay = new Date(year, month + 1, 0).getDate();

      const dates = [];
      for (let p = 0; p < firstDayIdx; p++) {
        dates.push(null);
      }
      for (let day = 1; day <= lastDay; day++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        dates.push(dateStr);
      }
      months.push({ year, month: month + 1, dates });
    }
    return months;
  }, []);

  const getStats = (date: string) => {
    const data = dailyAggregates[date];
    if (!data) return null;

    const isProteinSuccess = data.protein >= TARGET_PROTEIN;
    const isKcalSuccess = 
      data.kcal >= TARGET_KCAL * (1 - KCAL_THRESHOLD) && 
      data.kcal <= TARGET_KCAL * (1 + KCAL_THRESHOLD);

    return { isProteinSuccess, isKcalSuccess, ...data };
  };

  const perfectDaysCount = useMemo(() => {
    return Object.values(dailyAggregates).filter((d: { kcal: number; protein: number; count: number }) => {
      const isProteinSuccess = d.protein >= TARGET_PROTEIN;
      const isKcalSuccess = 
        d.kcal >= TARGET_KCAL * (1 - KCAL_THRESHOLD) && 
        d.kcal <= TARGET_KCAL * (1 + KCAL_THRESHOLD);
      return isProteinSuccess && isKcalSuccess;
    }).length;
  }, [dailyAggregates]);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8 pb-10">
      {/* 요약 카드 */}
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 p-6 rounded-[32px] text-white shadow-xl shadow-indigo-100">
        <h3 className="text-sm font-bold opacity-80 mb-1">나의 실제 달성 기록</h3>
        <p className="text-4xl font-black mb-4">{perfectDaysCount} <span className="text-xl font-normal opacity-60 italic">Perfect Days</span></p>
        <div className="flex space-x-4 pt-4 border-t border-white/10">
          <div>
            <p className="text-[10px] opacity-60 font-bold uppercase">총 섭취 횟수</p>
            <p className="text-lg font-bold">{actualMeals.length}회</p>
          </div>
          <div>
            <p className="text-[10px] opacity-60 font-bold uppercase">기록된 일수</p>
            <p className="text-lg font-bold">{Object.keys(dailyAggregates).length}일</p>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        {/* 필터 탭 */}
        <div className="flex bg-gray-100 p-1 rounded-2xl">
          <button 
            onClick={() => setFilter('all')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'all' ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'}`}
          >
            모두 보기
          </button>
          <button 
            onClick={() => setFilter('protein')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'protein' ? 'bg-white shadow-sm text-emerald-600' : 'text-gray-400'}`}
          >
            단백질만
          </button>
          <button 
            onClick={() => setFilter('kcal')}
            className={`flex-1 py-2 text-xs rounded-xl transition-all font-bold ${filter === 'kcal' ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'}`}
          >
            칼로리만
          </button>
        </div>

        <div className="space-y-8">
          {monthGrids.map(m => (
            <div key={`${m.year}-${m.month}`} className="bg-white p-5 rounded-[24px] shadow-sm border border-gray-100">
              <div className="flex justify-between items-center mb-4">
                <h5 className="text-sm font-black text-gray-800">{m.year}년 {m.month}월</h5>
                <div className="flex space-x-1">
                  {(filter === 'all' || filter === 'protein') && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>}
                  {(filter === 'all' || filter === 'kcal') && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>}
                </div>
              </div>

              {/* 요일 헤더 */}
              <div className="grid grid-cols-7 gap-1 mb-2">
                {weekDays.map(wd => (
                  <span key={wd} className="text-center text-[10px] font-bold text-gray-300 uppercase">{wd}</span>
                ))}
              </div>

              {/* 날짜 그리드 */}
              <div className="grid grid-cols-7 gap-1">
                {m.dates.map((date, idx) => {
                  if (!date) return <div key={`pad-${idx}`} className="aspect-square" />;

