          </div>
          <div className="space-y-2">
            <h3 className="text-xl font-black text-gray-800">앱을 종료할까요?</h3>
            <p className="text-sm text-gray-400 font-medium">오늘의 기록은 모두 안전하게 저장되었습니다.</p>
          </div>
        </div>

        <div className="flex border-t border-gray-50">
          <button 
            onClick={onClose}
            className="flex-1 py-4 text-gray-500 font-bold hover:bg-gray-50 transition-colors"
          >
            취소
          </button>
          <button 
            onClick={handleExit}
            className="flex-1 py-4 text-red-500 font-black hover:bg-red-50 transition-colors border-l border-gray-50"
          >
            종료
          </button>
        </div>
      </div>
    </div>
  );
};

export default ExitModal;

import React, { useMemo, useRef } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  type: MealType;
  meals: MealRecord[];
  ingredients: Ingredient[];
  onAdd: () => void;
  onEdit: (meal: MealRecord) => void;
  onDelete: (uuid: string) => void;
  onSetStatus: (uuid: string, status: MealStatus) => void;
}

const MealSection: React.FC<Props> = ({ type, meals, ingredients, onAdd, onEdit, onDelete, onSetStatus }) => {
  const getIngredientDisplayName = (meal: MealRecord) => {
    if (meal.ingredient_name) return meal.ingredient_name;
    if (!meal.ingredient_uuid) return '식재료 정보 없음';
    const targetUuid = String(meal.ingredient_uuid).trim();
    const found = ingredients.find(i => String(i.uuid).trim() === targetUuid);
    return found ? found.name : '알 수 없는 식재료';
  };

  const totalProteinActual = useMemo(() => {
    return meals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((sum, meal) => sum + (Number(meal.protein) || 0), 0);
  }, [meals]);

  const totalProteinPlanned = useMemo(() => {
    return meals.reduce((sum, meal) => sum + (Number(meal.protein) || 0), 0);
  }, [meals]);

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center px-1">
        <div className="flex items-center space-x-2">
          <h4 className="font-bold text-gray-700 flex items-center">
            <span className={`w-2 h-2 rounded-full mr-2 ${
              type === MealType.BREAKFAST ? 'bg-amber-400' :
              type === MealType.LUNCH ? 'bg-green-400' :
              type === MealType.SNACK ? 'bg-pink-400' : 'bg-indigo-400'
            }`} />
            {type}
          </h4>
          {meals.length > 0 && (
            <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-medium">
              단백질 {Math.round(totalProteinActual)}g <span className="opacity-60">({Math.round(totalProteinPlanned)}g)</span>
            </span>
          )}
        </div>
        <button 
          onClick={onAdd}
          className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded-full text-gray-500 hover:bg-gray-200 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
          </svg>
        </button>
      </div>

      <div className="space-y-2">
        {meals.length === 0 ? (
          <div className="bg-white/50 border border-dashed border-gray-200 p-4 rounded-xl text-center text-xs text-gray-400 italic">
            기록된 {type}이 없습니다.
          </div>
        ) : (
          meals.map(meal => (
            <SwipeableMealCard 
              key={meal.uuid} 
              meal={meal} 
              displayName={getIngredientDisplayName(meal)}
              onEdit={onEdit}
              onSetStatus={onSetStatus}
            />
          ))
        )}
      </div>
    </div>
  );
};

const SwipeableMealCard: React.FC<{ 
  meal: MealRecord; 
  displayName: string;
  onEdit: (meal: MealRecord) => void;
  onSetStatus: (uuid: string, status: MealStatus) => void;
}> = ({ meal, displayName, onEdit, onSetStatus }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const bgActualRef = useRef<HTMLDivElement>(null);
  const bgPlannedRef = useRef<HTMLDivElement>(null);

  const startX = useRef(0);
  const currentDiff = useRef(0);
  const isDragging = useRef(false);
  const threshold = 80; // 스와이프 발동 기준

  const updateStyles = (diff: number) => {
    if (!cardRef.current) return;
    const dragX = diff * 0.6; // 저항 계수

    // 카드 위치 직접 이동 (translate3d로 하드웨어 가속)
    cardRef.current.style.transform = `translate3d(${dragX}px, 0, 0)`;

    // 실제 섭취(Actual) 피드백 (오른쪽 드래그)
    if (bgActualRef.current) {
      const opacity = Math.min(Math.max(dragX / 60, 0), 1);
      bgActualRef.current.style.opacity = opacity.toString();
      bgActualRef.current.style.transform = `scale(${0.9 + opacity * 0.1})`;
    }

    // 예정 식단(Planned) 피드백 (왼쪽 드래그)
    if (bgPlannedRef.current) {
      const opacity = Math.min(Math.max(-dragX / 60, 0), 1);
      bgPlannedRef.current.style.opacity = opacity.toString();
      bgPlannedRef.current.style.transform = `scale(${0.9 + opacity * 0.1})`;
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    if (meal.pending) return;
    startX.current = e.touches[0].clientX;
    isDragging.current = true;
    if (cardRef.current) {
      cardRef.current.style.transition = 'none'; // 드래그 중에는 애니메이션 끔
    }
  };

  const onTouchMove = (e: React.TouchEvent) => {
    if (!isDragging.current) return;
    currentDiff.current = e.touches[0].clientX - startX.current;

    // 성능을 위해 rAF(requestAnimationFrame) 사용
    requestAnimationFrame(() => {
      updateStyles(currentDiff.current);
    });
  };

  const onTouchEnd = () => {
    if (!isDragging.current) return;
    isDragging.current = false;

    const dragX = currentDiff.current * 0.6;

    // 원복 애니메이션 설정
    if (cardRef.current) {
      cardRef.current.style.transition = 'transform 0.4s cubic-bezier(0.25, 1, 0.5, 1)';
      cardRef.current.style.transform = `translate3d(0, 0, 0)`;
    }

    // 배경 피드백 페이드 아웃
    if (bgActualRef.current) bgActualRef.current.style.opacity = '0';
    if (bgPlannedRef.current) bgPlannedRef.current.style.opacity = '0';

    // 임계값 확인 후 상태 변경 실행
    if (dragX > threshold) {
      onSetStatus(meal.uuid, MealStatus.ACTUAL);
    } else if (dragX < -threshold) {
      onSetStatus(meal.uuid, MealStatus.PLANNED);
    }

    currentDiff.current = 0;
  };

  const isPlanned = meal.status === MealStatus.PLANNED;
  const isDirectEntry = String(meal.ingredient_uuid).trim() === 'direct-entry';

  return (
    <div className="relative overflow-hidden rounded-xl bg-gray-100 touch-pan-y">
      {/* Background Actions Layer */}
      <div className="absolute inset-0 flex items-center justify-between px-6 z-0 pointer-events-none">
        <div ref={bgActualRef} className="opacity-0 flex items-center space-x-2 transition-opacity duration-200">
          <div className="w-9 h-9 rounded-full bg-green-500 flex items-center justify-center shadow-lg text-white">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
             </svg>
          </div>
          <span className="text-[10px] font-black text-green-600 uppercase tracking-tighter">Actual</span>
        </div>
        <div ref={bgPlannedRef} className="opacity-0 flex items-center space-x-2 transition-opacity duration-200">
          <span className="text-[10px] font-black text-gray-500 uppercase tracking-tighter">Planned</span>
          <div className="w-9 h-9 rounded-full bg-gray-400 flex items-center justify-center shadow-lg text-white">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <rect x="3" y="3" width="18" height="18" rx="4" strokeWidth="2" />
             </svg>
          </div>
        </div>
      </div>

      {/* Main Content Card Layer */}
      <div 
        ref={cardRef}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        onClick={() => onEdit(meal)}
        className={`relative z-10 flex-1 text-left p-4 rounded-xl shadow-sm flex justify-between items-center border-l-4 will-change-transform cursor-pointer select-none ${
          meal.pending ? 'opacity-50 grayscale border-gray-300 cursor-wait' : 
          isPlanned ? 'bg-gray-50 border-gray-300 border-dashed' : 'bg-white border-indigo-500 hover:border-indigo-600'
        }`}
      >
        <div className="flex-1">
          <div className="flex items-center space-x-2">
            <p className={`font-bold text-sm ${isPlanned ? 'text-gray-400 italic' : 'text-gray-800'}`}>
              {displayName}
              {isDirectEntry && <span className="ml-1.5 text-[8px] bg-orange-100 text-orange-600 px-1 py-0.5 rounded font-black uppercase tracking-tighter">임의등록</span>}
              {isPlanned && <span className="ml-1.5 text-[8px] bg-gray-200 text-gray-500 px-1 py-0.5 rounded font-black not-italic uppercase tracking-tighter">Planned</span>}
            </p>
          </div>
          <p className="text-xs text-gray-400 font-medium">{meal.amount}g • {meal.time}</p>
        </div>
        <div className="text-right">
          <p className={`font-black tracking-tight ${isPlanned ? 'text-gray-300' : 'text-indigo-600'}`}>
            {Math.round(meal.kcal)} <span className="text-[9px] font-bold opacity-50 ml-0.5">kcal</span>
          </p>
          <div className="flex space-x-2 text-[10px] text-gray-400 justify-end font-bold">
            <span className={!isPlanned ? 'text-emerald-500/80' : ''}>P {Math.round(meal.protein || 0)}g</span>
            <span>C {Math.round(meal.carbs || 0)}g</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealSection;

import React, { useState, useMemo, useEffect } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => void;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const isEditingDirect = editTarget?.ingredient_uuid === 'direct-entry';

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  const [status, setStatus] = useState<MealStatus>(editTarget?.status || MealStatus.ACTUAL);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    (editTarget && !isEditingDirect) ? (ingredients.find(i => i.uuid === editTarget.ingredient_uuid) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(isEditingDirect);
  const [newName, setNewName] = useState(isEditingDirect ? editTarget?.ingredient_name || '' : '');
  const [newBase, setNewBase] = useState(isEditingDirect ? editTarget?.amount.toString() || '1' : '1');
  const [newKcal, setNewKcal] = useState(isEditingDirect ? editTarget?.kcal.toString() || '' : '');
  const [newCarbs, setNewCarbs] = useState(isEditingDirect ? editTarget?.carbs.toString() || '' : '');
  const [newProtein, setNewProtein] = useState(isEditingDirect ? editTarget?.protein.toString() || '' : '');
  const [newFat, setNewFat] = useState(isEditingDirect ? editTarget?.fat.toString() || '' : '');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  useEffect(() => {
    // 직접 입력 모드에서 영양성분 입력 시 칼로리 자동 계산 (사용자가 수동 수정도 가능)
    if (isAddingNew && !isEditingDirect) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated > 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew, isEditingDirect]);

  useEffect(() => {
    if (!prefilledType && !editTarget) {
      const h = parseInt(time.split(':')[0]);
      const m = parseInt(time.split(':')[1]);
      const totalMin = h * 60 + m;
      if (totalMin >= 360 && totalMin < 720) setType(MealType.BREAKFAST);
      else if (totalMin >= 720 && totalMin < 840) setType(MealType.LUNCH);
      else if (totalMin >= 840 && totalMin < 1080) setType(MealType.SNACK);
      else setType(MealType.DINNER);
    }
  }, [time, prefilledType, editTarget]);

  const bookmarkedIngredients = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 12);
  }, [ingredients]);

  const filteredIngredients = useMemo(() => {
    if (!searchTerm) return [];
    return ingredients
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => (b.is_bookmarked ? 1 : 0) - (a.is_bookmarked ? 1 : 0))
      .slice(0, 8);
  }, [searchTerm, ingredients]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const factor = parseFloat(amount) / (parseFloat(newBase) || 1);
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
        sugar: 0,
        fiber: 0,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
      sugar: (ing.sugar || 0) * factor,
      fiber: (ing.fiber || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (keepOpen: boolean) => {
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = selectedIngredient?.name || newName || '직접 입력 식단';
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    const newMeal: MealRecord = {
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status,
      date,
      time,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      ...preview
    };

    onSave(newMeal, newIngData);

    if (keepOpen) {
      setSearchTerm('');
      setSelectedIngredient(null);
      setAmount('1');
      setIsAddingNew(false);
      setNewName('');
      setNewKcal('');
      setNewCarbs('');
      setNewProtein('');
      setNewFat('');
      setShouldSaveToIngredients(false);
    } else {
      onClose();
    }
  };

  const handleDelete = () => {
    if (editTarget && onDelete) {
      onDelete(editTarget.uuid);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4">
      <div className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 duration-500">
        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-6 overflow-y-auto">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">날짜</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">시간</label>
              <input type="time" value={time} onChange={e => setTime(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식사 분류</label>
            <div className="flex bg-gray-100 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(t => (
                <button
                  key={t}
                  onClick={() => setType(t)}
                  className={`flex-1 py-2 text-xs rounded-xl transition-all ${type === t ? 'bg-white shadow-md font-black text-indigo-600' : 'text-gray-400'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-6">
              <div className="space-y-2">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">식재료 검색</label>
                  <button onClick={() => setIsAddingNew(true)} className="text-[10px] font-black text-indigo-600 underline">직접 입력하기</button>
                </div>
                <div className="relative">
                  <input autoFocus type="text" placeholder="식재료 검색..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white shadow-sm font-medium" />
                </div>
              </div>

              {!searchTerm && bookmarkedIngredients.length > 0 && (
                <div className="space-y-3 animate-in fade-in duration-500">
                  <div className="flex items-center space-x-2 px-1">
                    <span className="text-amber-400 text-xs">★</span>
                    <label className="text-[10px] font-black text-gray-400 uppercase">자주 먹는 식재료</label>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    {bookmarkedIngredients.map(i => (
                      <button 
                        key={i.uuid} 
                        onClick={() => setSelectedIngredient(i)}
                        className="p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-left hover:bg-indigo-100 transition-colors group"
                      >
                        <p className="text-xs font-bold text-indigo-900 line-clamp-1">{i.name}</p>
                        <p className="text-[9px] text-indigo-400 font-medium">{i.kcal}kcal / {i.base_amount}g</p>
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {searchTerm && (
                <div className="space-y-2 animate-in slide-in-from-top-2 duration-300">
                  {filteredIngredients.map(i => (
                    <button key={i.uuid} onClick={() => { setSelectedIngredient(i); setSearchTerm(''); }} className="w-full text-left p-4 bg-white border border-gray-100 hover:border-indigo-500 rounded-2xl flex justify-between items-center transition-all shadow-sm group">
                      <div className="flex items-center space-x-3">
                        {i.is_bookmarked && <span className="text-amber-400">★</span>}
                        <span className="font-bold text-gray-800">{i.name}</span>
                      </div>
                      <span className="text-[10px] text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">{i.kcal} kcal / {i.base_amount}g</span>
                    </button>
                  ))}
                  {filteredIngredients.length === 0 && (
                    <div className="text-center py-6 text-xs text-gray-400">
                      검색 결과가 없습니다.
                    </div>
                  )}
                </div>
              )}
            </div>
          ) : isAddingNew ? (
            <div className="space-y-5 bg-indigo-50/30 p-5 rounded-[32px] border border-indigo-100 animate-in zoom-in duration-300">
               <div className="flex justify-between items-center">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-widest">{isEditingDirect ? '임의등록 수정' : '직접 입력'}</h3>
                {!isEditingDirect && <button onClick={() => setIsAddingNew(false)} className="text-[10px] text-gray-400 underline font-bold">돌아가기</button>}
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-indigo-600 uppercase ml-1">식단 이름</label>
