import { MealRecord, Ingredient, MealStatus } from '../types';

const GAS_WEB_APP_URL = 'https://script.google.com/macros/s/AKfycbwTWuRqdWN-ioZf9q2D7XDm_SWGgtozpkzFNfbBaErwH6MO072K_SakXGLfJB0vKDZe/exec';

export async function fetchInitialData(): Promise<{ meals: MealRecord[], ingredients: Ingredient[] }> {
  try {
    const response = await fetch(`${GAS_WEB_APP_URL}?action=getData`, {
      method: 'GET',
      redirect: 'follow'
    });

    if (!response.ok) {
      throw new Error(`GAS HTTP error! status: ${response.status}`);
    }

    const data = await response.json();

    const sanitizedIngredients = (data.ingredients || []).map((ing: any) => ({
      ...ing,
      is_bookmarked: String(ing.is_bookmarked).toLowerCase() === 'true',
      base_amount: Number(ing.base_amount) || 100,
      kcal: Number(ing.kcal) || 0,
      carbs: Number(ing.carbs) || 0,
      protein: Number(ing.protein) || 0,
      fat: Number(ing.fat) || 0,
      sugar: Number(ing.sugar) || 0,
      fiber: Number(ing.fiber) || 0
    }));

    const sanitizedMeals = (data.meals || []).map((meal: any) => ({
      ...meal,
      status: (meal.status as MealStatus) || MealStatus.ACTUAL,
      amount: Number(meal.amount) || 0,
      kcal: Number(meal.kcal) || 0,
      carbs: Number(meal.carbs) || 0,
      protein: Number(meal.protein) || 0,
      fat: Number(meal.fat) || 0,
      sugar: Number(meal.sugar) || 0,
      fiber: Number(meal.fiber) || 0
    }));

    return { meals: sanitizedMeals, ingredients: sanitizedIngredients };
  } catch (error) {
    console.error("Failed to fetch from GAS", error);
    return { meals: [], ingredients: [] };
  }
}

export async function saveMealToGAS(meal: MealRecord): Promise<boolean> {
  return callGAS('saveMeal', meal);
}

export async function updateMealInGAS(meal: MealRecord): Promise<boolean> {
  return callGAS('updateMeal', meal);
}

export async function deleteMealFromGAS(uuid: string): Promise<boolean> {
  console.log(`[GAS Service] Requesting deleteMeal for UUID: ${uuid}`);
  return callGAS('deleteMeal', { uuid });
}

export async function saveIngredientToGAS(ingredient: Ingredient): Promise<boolean> {
  return callGAS('saveIngredient', ingredient);
}

export async function updateIngredientInGAS(ingredient: Ingredient): Promise<boolean> {
  return callGAS('updateIngredient', ingredient);
}

export async function deleteIngredientFromGAS(uuid: string): Promise<boolean> {
  return callGAS('deleteIngredient', { uuid });
}

export async function updateIngredientBookmark(uuid: string, isBookmarked: boolean): Promise<boolean> {
  return callGAS('updateBookmark', { uuid, is_bookmarked: isBookmarked });
}

async function callGAS(action: string, data: any): Promise<boolean> {
  const payload = JSON.stringify({ action, data });
  try {
    const response = await fetch(GAS_WEB_APP_URL, {
      method: 'POST',
      redirect: 'follow',
      body: payload,
    });

    if (response.ok) {
      return true;
    }

    // response.ok가 아닐 때 (예: 500 에러 등)
    const errorText = await response.text();
    console.error(`[GAS Service] Action ${action} failed with status ${response.status}: ${errorText}`);
    return false;
  } catch (e) {
    // GAS POST 요청은 리다이렉트 시 브라우저에서 CORS 에러(TypeError)를 낼 수 있음.
    // 하지만 이 단계까지 왔다면 GAS는 요청을 수신했을 확률이 99%입니다.
    if (e instanceof TypeError && e.message.includes('fetch')) {
      console.warn(`[GAS Service] ${action} triggered a redirect/CORS warning, but likely succeeded.`);
      return true; 
    }
    console.error(`[GAS Service] Critical fetch error for action ${action}:`, e);
    return false;
  }
}

import React, { useState, useMemo, useEffect } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => Promise<boolean>;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const isEditingDirect = editTarget?.ingredient_uuid === 'direct-entry';

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  const [status, setStatus] = useState<MealStatus>(editTarget?.status || MealStatus.ACTUAL);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    (editTarget && !isEditingDirect) ? (ingredients.find(i => i.uuid === editTarget.ingredient_uuid) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(isEditingDirect);
  const [newName, setNewName] = useState(isEditingDirect ? editTarget?.ingredient_name || '' : '');
  const [newBase, setNewBase] = useState(isEditingDirect ? editTarget?.amount.toString() || '1' : '1');
  const [newKcal, setNewKcal] = useState(isEditingDirect ? editTarget?.kcal.toString() || '' : '');
  const [newCarbs, setNewCarbs] = useState(isEditingDirect ? editTarget?.carbs.toString() || '' : '');
  const [newProtein, setNewProtein] = useState(isEditingDirect ? editTarget?.protein.toString() || '' : '');
  const [newFat, setNewFat] = useState(isEditingDirect ? editTarget?.fat.toString() || '' : '');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  useEffect(() => {
    if (isAddingNew && !isEditingDirect) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated > 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew, isEditingDirect]);

  useEffect(() => {
    if (!prefilledType && !editTarget) {
      const h = parseInt(time.split(':')[0]);
      const m = parseInt(time.split(':')[1]);
      const totalMin = h * 60 + m;
      if (totalMin >= 360 && totalMin < 720) setType(MealType.BREAKFAST);
      else if (totalMin >= 720 && totalMin < 840) setType(MealType.LUNCH);
      else if (totalMin >= 840 && totalMin < 1080) setType(MealType.SNACK);
      else setType(MealType.DINNER);
    }
  }, [time, prefilledType, editTarget]);

  const bookmarkedIngredients = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 12);
  }, [ingredients]);

  const filteredIngredients = useMemo(() => {
    if (!searchTerm) return [];
    return ingredients
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => (b.is_bookmarked ? 1 : 0) - (a.is_bookmarked ? 1 : 0))
      .slice(0, 8);
  }, [searchTerm, ingredients]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const factor = parseFloat(amount) / (parseFloat(newBase) || 1);
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
        sugar: 0,
        fiber: 0,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
      sugar: (ing.sugar || 0) * factor,
      fiber: (ing.fiber || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (keepOpen: boolean) => {
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = selectedIngredient?.name || newName || '직접 입력 식단';
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    const newMeal: MealRecord = {
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status,
      date,
      time,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      ...preview
    };

    onSave(newMeal, newIngData);

    if (keepOpen) {
      setSearchTerm('');
      setSelectedIngredient(null);
      setAmount('1');
      setIsAddingNew(false);
      setNewName('');
      setNewKcal('');
      setNewCarbs('');
      setNewProtein('');
      setNewFat('');
      setShouldSaveToIngredients(false);
    } else {
      onClose();
    }
  };

  const handleDelete = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (editTarget && onDelete) {
      if (!window.confirm('이 식단 기록을 정말 삭제할까요?')) {
        return;
      }

      try {
        const success = await onDelete(editTarget.uuid);
        if (success) {
          onClose();
        } else {
          alert('식단 삭제 중 문제가 발생했습니다. 네트워크 상태를 확인하시고 잠시 후 다시 시도해 주세요.');
        }
      } catch (err) {
        console.error("[Form Error] Deletion failed:", err);
        alert('삭제 요청 중 오류가 발생했습니다.');
      }
    }
  };

  return (
    <div 
      className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4"
      onClick={onClose}
    >
      <div 
        className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 duration-500"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-6 overflow-y-auto">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">날짜</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">시간</label>
              <input type="time" value={time} onChange={e => setTime(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식사 분류</label>
            <div className="flex bg-gray-100 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(t => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setType(t)}
                  className={`flex-1 py-2 text-xs rounded-xl transition-all ${type === t ? 'bg-white shadow-md font-black text-indigo-600' : 'text-gray-400'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-6">
              <div className="space-y-2">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">식재료 검색</label>
                  <button type="button" onClick={() => setIsAddingNew(true)} className="text-[10px] font-black text-indigo-600 underline">직접 입력하기</button>
                </div>
                <div className="relative">
                  <input autoFocus type="text" placeholder="식재료 검색..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white shadow-sm font-medium" />
                </div>
              </div>

              {!searchTerm && bookmarkedIngredients.length > 0 && (
                <div className="space-y-3 animate-in fade-in duration-500">
                  <div className="flex items-center space-x-2 px-1">
                    <span className="text-amber-400 text-xs">★</span>
                    <label className="text-[10px] font-black text-gray-400 uppercase">자주 먹는 식재료</label>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    {bookmarkedIngredients.map(i => (
                      <button 
                        key={i.uuid} 
                        type="button"
                        onClick={() => setSelectedIngredient(i)}
                        className="p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-left hover:bg-indigo-100 transition-colors group"
                      >
                        <p className="text-xs font-bold text-indigo-900 line-clamp-1">{i.name}</p>
                        <p className="text-[9px] text-indigo-400 font-medium">{i.kcal}kcal / {i.base_amount}g</p>
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {searchTerm && (
                <div className="space-y-2 animate-in slide-in-from-top-2 duration-300">
                  {filteredIngredients.map(i => (
                    <button key={i.uuid} type="button" onClick={() => { setSelectedIngredient(i); setSearchTerm(''); }} className="w-full text-left p-4 bg-white border border-gray-100 hover:border-indigo-500 rounded-2xl flex justify-between items-center transition-all shadow-sm group">
                      <div className="flex items-center space-x-3">
                        {i.is_bookmarked && <span className="text-amber-400">★</span>}
                        <span className="font-bold text-gray-800">{i.name}</span>
                      </div>
                      <span className="text-[10px] text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">{i.kcal} kcal / {i.base_amount}g</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          ) : isAddingNew ? (
            <div className="space-y-5 bg-indigo-50/30 p-5 rounded-[32px] border border-indigo-100 animate-in zoom-in duration-300">
               <div className="flex justify-between items-center">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-widest">{isEditingDirect ? '임의등록 수정' : '직접 입력'}</h3>
                {!isEditingDirect && <button type="button" onClick={() => setIsAddingNew(false)} className="text-[10px] text-gray-400 underline font-bold">돌아가기</button>}
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-indigo-600 uppercase ml-1">식단 이름</label>
                <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름 (예: 엄마표 볶음밥)" className="w-full p-4 rounded-2xl border bg-white shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-indigo-600 uppercase ml-1">영양 성분 (전체량 기준)</label>
                <div className="grid grid-cols-3 gap-3">
                    <div className="space-y-1">
                      <span className="text-[9px] text-gray-400 font-bold ml-1">탄(g)</span>
                      <input type="number" placeholder="0" value={newCarbs} onChange={e => setNewCarbs(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                    </div>
                    <div className="space-y-1">
                      <span className="text-[9px] text-gray-400 font-bold ml-1">단(g)</span>
                      <input type="number" placeholder="0" value={newProtein} onChange={e => setNewProtein(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                    </div>
                    <div className="space-y-1">
                      <span className="text-[9px] text-gray-400 font-bold ml-1">지(g)</span>
                      <input type="number" placeholder="0" value={newFat} onChange={e => setNewFat(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                    </div>
                </div>
              </div>
              <div className="pt-4 border-t border-indigo-100">
                <label className="block text-[10px] font-black text-indigo-600 mb-2 uppercase">총 섭취량 (g)</label>
                <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-6 rounded-3xl border-2 border-indigo-500 text-4xl font-black text-center bg-white" />
              </div>
            </div>
          ) : (
            <div className="bg-indigo-50/50 p-6 rounded-[40px] flex flex-col space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-black text-indigo-600 text-2xl">{selectedIngredient?.name}</h3>
                  <p className="text-xs text-gray-400">{selectedIngredient?.base_amount}g 당 {selectedIngredient?.kcal}kcal</p>
                </div>
                {!editTarget && <button type="button" onClick={() => setSelectedIngredient(null)} className="text-xs text-indigo-400 font-bold underline bg-white px-3 py-1 rounded-full">변경</button>}
              </div>
              <div className="space-y-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase">양 (g)</label>
                <input autoFocus type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-6 bg-white rounded-3xl border-none ring-2 ring-indigo-500 text-4xl font-black focus:ring-4 outline-none text-center" />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 border-t bg-gray-50 flex space-x-3 sticky bottom-0">
          {editTarget && (
            <button 
              type="button"
              onClick={handleDelete} 
              className="px-6 py-4 bg-red-50 text-red-500 font-black rounded-2xl border border-red-100 transition-all text-sm active:scale-95"
            >
              삭제
            </button>
          )}
          {!editTarget && (
            <button type="button" disabled={!preview} onClick={() => handleSave(true)} className="flex-1 py-4 px-2 border-2 border-indigo-600 text-indigo-600 font-black rounded-2xl disabled:opacity-30 transition-all text-sm">+ 계속 추가</button>
          )}
          <button type="button" disabled={!preview} onClick={() => handleSave(false)} className="flex-1 py-4 px-2 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 active:scale-95 disabled:opacity-30 transition-all text-sm">
            {editTarget ? '기록 업데이트' : '저장 후 닫기'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default MealInputForm;

export enum MealType {
  BREAKFAST = '아침',
  LUNCH = '점심',
  SNACK = '간식',
  DINNER = '저녁'
}

export enum MealStatus {
  PLANNED = 'PLANNED',
  ACTUAL = 'ACTUAL',
  CANCELED = 'CANCELED'
}

export interface Ingredient {
  uuid: string;
  name: string;
  base_amount: number;
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  sugar: number;
  fiber: number;
  is_bookmarked?: boolean; // 즐겨찾기 여부
}

export interface MealRecord {
  uuid: string;
  type: MealType;
  status: MealStatus; // 예정(PLANNED), 실제(ACTUAL), 취소(CANCELED)
  date: string; // YYYY-MM-DD
  time: string; // HH:mm
  ingredient_uuid: string;
  ingredient_name?: string; // 저장된 이름 (일회성 식단 대응)
  amount: number;
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  sugar: number;
  fiber: number;
  pending?: boolean; // For optimistic UI
}

export interface DailySummary {
  actual: {
    kcal: number;
    carbs: number;
    protein: number;
    fat: number;
  };
  planned: {
    kcal: number;
    carbs: number;
    protein: number;
    fat: number;
  };
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) {
        setIsSidebarOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (isInputOpen) {
        setIsInputOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (adviceModalOpen) {
        setAdviceModalOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, adviceModalOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  // UI에 보여줄 식단 필터링: 선택된 날짜 AND 상태가 CANCELED가 아닌 것
  const filteredMeals = useMemo(() => {
    return meals.filter(m => 
      String(m.date).startsWith(selectedDate) && 
      m.status !== MealStatus.CANCELED
    );
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    // filteredMeals는 이미 CANCELED를 제외한 상태임
    const actual = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((acc, cur) => ({
        kcal: acc.kcal + (Number(cur.kcal) || 0),
        carbs: acc.carbs + (Number(cur.carbs) || 0),
        protein: acc.protein + (Number(cur.protein) || 0),
        fat: acc.fat + (Number(cur.fat) || 0),
      }), { ...initial });

    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });

    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    if (isUpdate) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }
    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }
    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { 
      ...target, 
      status,
      time: status === MealStatus.ACTUAL ? getKSTTime() : target.time,
      pending: true 
    };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
      }
    } catch (err) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m));
    }
  }, [meals]);

  // 삭제 함수 수정: 물리 삭제 대신 status를 CANCELED로 변경
  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;

    const previousMeals = [...meals];
    console.log(`[Soft Delete] Target UUID: ${uuid}`);

    // UI에서 즉시 제외 (CANCELED 상태로 변경)
    const optimisticMeals = meals.map(m => 
      String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m
    );
    setMeals(optimisticMeals);

    try {
      // 서버에는 updateMeal 액션으로 CANCELED 상태를 보냄
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success === false) {
        console.error("[Soft Delete Failed] Server rejected. Rolling back...");
        setMeals(previousMeals);
        return false;
      }
      // 성공 시 pending 해제
      setMeals(prev => prev.map(m => 
        String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: false } : m
      ));
      console.log("[Soft Delete Success] Status changed to CANCELED.");
      return true;
    } catch (err) {
      console.error("[Soft Delete Error] Exception:", err);
      setMeals(previousMeals);
      return false;
    }
  }, [meals]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, []);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    setIngredients(prev => prev.map(i => String(i.uuid) === String(ing.uuid) ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, []);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    if (!confirm('이 식재료를 삭제할까요?')) return;
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => String(i.uuid) !== String(uuid)));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients]);

  const handleOpenQuickInput = () => {
    setEditMealTarget(null);
    setPrefilledType(null);
    setSelectedDate(getKSTDate());
    setIsInputOpen(true);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl">
      <header className="bg-indigo-600 text-white p-4 sticky top-0 z-50 shadow-lg flex items-center">
        <button 
          onClick={() => setIsSidebarOpen(true)}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
        <h1 className="ml-2 text-xl font-bold">
          {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
        </h1>
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />
            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  onAdd={() => {
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                  onSetStatus={handleSetMealStatus}
                />
              ))}
            </div>
            <button 
              onClick={() => setAdviceModalOpen(true)}
              className="w-full mt-8 py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"
            >
              <span className="text-xl">✨</span>
              <span>AI 영양 추천 받기</span>
            </button>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement 
            ingredients={ingredients}
            onToggleBookmark={handleToggleBookmark}
            onAddIngredient={handleAddIngredient}
            onUpdateIngredient={handleUpdateIngredient}
            onDeleteIngredient={handleDeleteIngredient}
          />
        ) : (
          <Statistics 
            meals={meals} 
            onDateSelect={(date) => {
              setSelectedDate(date);
              setCurrentView('main');
            }} 
          />
        )}
      </main>

      {currentView === 'main' && (
        <button 
          onClick={handleOpenQuickInput}
          className="fixed bottom-6 right-6 w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 hover:scale-105 transition-all animate-in zoom-in slide-in-from-bottom-10 duration-500"
          aria-label="식단 추가"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
          </svg>
        </button>
      )}

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => {
            setIsInputOpen(false);
            setEditMealTarget(null);
          }}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          editTarget={editMealTarget}
          ingredients={ingredients}
          onSave={onSaveMeal}
          onDelete={onDeleteMeal}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.actual.kcal}
          currentProtein={summary.actual.protein}
        />
      )}

      {isExitModalOpen && (
        <ExitModal 
          isOpen={isExitModalOpen}
          onClose={() => {
            setIsExitModalOpen(false);
            window.history.pushState({ noBackExitsApp: true }, '');
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => Promise<boolean>;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const isEditingDirect = editTarget?.ingredient_uuid === 'direct-entry';

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  const [status, setStatus] = useState<MealStatus>(editTarget?.status || MealStatus.ACTUAL);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    (editTarget && !isEditingDirect) ? (ingredients.find(i => String(i.uuid) === String(editTarget.ingredient_uuid)) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(isEditingDirect);
  const [newName, setNewName] = useState(isEditingDirect ? editTarget?.ingredient_name || '' : '');
  const [newBase, setNewBase] = useState(isEditingDirect ? editTarget?.amount.toString() || '1' : '1');
  const [newKcal, setNewKcal] = useState(isEditingDirect ? editTarget?.kcal.toString() || '' : '');
  const [newCarbs, setNewCarbs] = useState(isEditingDirect ? editTarget?.carbs.toString() || '' : '');
  const [newProtein, setNewProtein] = useState(isEditingDirect ? editTarget?.protein.toString() || '' : '');
  const [newFat, setNewFat] = useState(isEditingDirect ? editTarget?.fat.toString() || '' : '');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  useEffect(() => {
    if (isAddingNew && !isEditingDirect) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated > 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew, isEditingDirect]);

  useEffect(() => {
    if (!prefilledType && !editTarget) {
      const h = parseInt(time.split(':')[0]);
      const m = parseInt(time.split(':')[1]);
      const totalMin = h * 60 + m;
      if (totalMin >= 360 && totalMin < 720) setType(MealType.BREAKFAST);
      else if (totalMin >= 720 && totalMin < 840) setType(MealType.LUNCH);
      else if (totalMin >= 840 && totalMin < 1080) setType(MealType.SNACK);
      else setType(MealType.DINNER);
    }
  }, [time, prefilledType, editTarget]);

  const bookmarkedIngredients = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 12);
  }, [ingredients]);

  const filteredIngredients = useMemo(() => {
    if (!searchTerm) return [];
    return ingredients
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => (b.is_bookmarked ? 1 : 0) - (a.is_bookmarked ? 1 : 0))
      .slice(0, 8);
  }, [searchTerm, ingredients]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const factor = parseFloat(amount) / (parseFloat(newBase) || 1);
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
        sugar: 0,
        fiber: 0,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
      sugar: (ing.sugar || 0) * factor,
      fiber: (ing.fiber || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (keepOpen: boolean) => {
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = selectedIngredient?.name || newName || '직접 입력 식단';
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    const newMeal: MealRecord = {
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status,
      date,
      time,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      ...preview
    };

    onSave(newMeal, newIngData);

    if (keepOpen) {
      setSearchTerm('');
      setSelectedIngredient(null);
      setAmount('1');
      setIsAddingNew(false);
      setNewName('');
      setNewKcal('');
      setNewCarbs('');
      setNewProtein('');
      setNewFat('');
      setShouldSaveToIngredients(false);
    } else {
      onClose();
    }
  };

  const handleDelete = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (editTarget && onDelete) {
      if (!window.confirm('이 식단 기록을 정말 삭제할까요?')) {
        return;
      }

      try {
        // App.tsx의 onDeleteMeal을 호출하여 CANCELED 상태로 변경 시도
        const success = await onDelete(editTarget.uuid);
        if (success) {
          onClose();
        } else {
          alert('식단 삭제 처리 중 문제가 발생했습니다. 네트워크 상태를 확인해 주세요.');
        }
      } catch (err) {
        console.error("[Form Error] Deletion failed:", err);
        alert('삭제 요청 중 오류가 발생했습니다.');
      }
    }
  };

  return (
    <div 
      className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4"
      onClick={onClose}
    >
      <div 
        className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 duration-500"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-6 overflow-y-auto">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">날짜</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">시간</label>
              <input type="time" value={time} onChange={e => setTime(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식사 분류</label>
            <div className="flex bg-gray-100 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(t => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setType(t)}
                  className={`flex-1 py-2 text-xs rounded-xl transition-all ${type === t ? 'bg-white shadow-md font-black text-indigo-600' : 'text-gray-400'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-6">
              <div className="space-y-2">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">식재료 검색</label>
                  <button type="button" onClick={() => setIsAddingNew(true)} className="text-[10px] font-black text-indigo-600 underline">직접 입력하기</button>
                </div>
                <div className="relative">
                  <input autoFocus type="text" placeholder="식재료 검색..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white shadow-sm font-medium" />
                </div>
              </div>

              {!searchTerm && bookmarkedIngredients.length > 0 && (
                <div className="space-y-3 animate-in fade-in duration-500">
                  <div className="flex items-center space-x-2 px-1">
                    <span className="text-amber-400 text-xs">★</span>
                    <label className="text-[10px] font-black text-gray-400 uppercase">자주 먹는 식재료</label>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    {bookmarkedIngredients.map(i => (
                      <button 
                        key={i.uuid} 
                        type="button"
                        onClick={() => setSelectedIngredient(i)}
                        className="p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-left hover:bg-indigo-100 transition-colors group"
                      >
                        <p className="text-xs font-bold text-indigo-900 line-clamp-1">{i.name}</p>
                        <p className="text-[9px] text-indigo-400 font-medium">{i.kcal}kcal / {i.base_amount}g</p>
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {searchTerm && (
                <div className="space-y-2 animate-in slide-in-from-top-2 duration-300">
                  {filteredIngredients.map(i => (
                    <button key={i.uuid} type="button" onClick={() => { setSelectedIngredient(i); setSearchTerm(''); }} className="w-full text-left p-4 bg-white border border-gray-100 hover:border-indigo-500 rounded-2xl flex justify-between items-center transition-all shadow-sm group">
                      <div className="flex items-center space-x-3">
                        {i.is_bookmarked && <span className="text-amber-400">★</span>}
                        <span className="font-bold text-gray-800">{i.name}</span>
                      </div>
                      <span className="text-[10px] text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">{i.kcal} kcal / {i.base_amount}g</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          ) : isAddingNew ? (
            <div className="space-y-5 bg-indigo-50/30 p-5 rounded-[32px] border border-indigo-100 animate-in zoom-in duration-300">
               <div className="flex justify-between items-center">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-widest">{isEditingDirect ? '임의등록 수정' : '직접 입력'}</h3>
                {!isEditingDirect && <button type="button" onClick={() => setIsAddingNew(false)} className="text-[10px] text-gray-400 underline font-bold">돌아가기</button>}
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-indigo-600 uppercase ml-1">식단 이름</label>
                <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름 (예: 엄마표 볶음밥)" className="w-full p-4 rounded-2xl border bg-white shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-indigo-600 uppercase ml-1">영양 성분 (전체량 기준)</label>
                <div className="grid grid-cols-3 gap-3">
                    <div className="space-y-1">
                      <span className="text-[9px] text-gray-400 font-bold ml-1">탄(g)</span>
                      <input type="number" placeholder="0" value={newCarbs} onChange={e => setNewCarbs(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                    </div>
                    <div className="space-y-1">
                      <span className="text-[9px] text-gray-400 font-bold ml-1">단(g)</span>
                      <input type="number" placeholder="0" value={newProtein} onChange={e => setNewProtein(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                    </div>
                    <div className="space-y-1">
                      <span className="text-[9px] text-gray-400 font-bold ml-1">지(g)</span>
                      <input type="number" placeholder="0" value={newFat} onChange={e => setNewFat(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold" />
                    </div>
                </div>
              </div>
              <div className="pt-4 border-t border-indigo-100">
                <label className="block text-[10px] font-black text-indigo-600 mb-2 uppercase">총 섭취량 (g)</label>
                <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-6 rounded-3xl border-2 border-indigo-500 text-4xl font-black text-center bg-white" />
              </div>
            </div>
          ) : (
            <div className="bg-indigo-50/50 p-6 rounded-[40px] flex flex-col space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-black text-indigo-600 text-2xl">{selectedIngredient?.name}</h3>
                  <p className="text-xs text-gray-400">{selectedIngredient?.base_amount}g 당 {selectedIngredient?.kcal}kcal</p>
                </div>
                {!editTarget && <button type="button" onClick={() => setSelectedIngredient(null)} className="text-xs text-indigo-400 font-bold underline bg-white px-3 py-1 rounded-full">변경</button>}
              </div>
              <div className="space-y-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase">양 (g)</label>
                <input autoFocus type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-6 bg-white rounded-3xl border-none ring-2 ring-indigo-500 text-4xl font-black focus:ring-4 outline-none text-center" />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 border-t bg-gray-50 flex space-x-3 sticky bottom-0">
          {editTarget && (
            <button 
              type="button"
              onClick={handleDelete} 
              className="px-6 py-4 bg-red-50 text-red-500 font-black rounded-2xl border border-red-100 transition-all text-sm active:scale-95"
            >
              삭제
            </button>
          )}
          {!editTarget && (
            <button type="button" disabled={!preview} onClick={() => handleSave(true)} className="flex-1 py-4 px-2 border-2 border-indigo-600 text-indigo-600 font-black rounded-2xl disabled:opacity-30 transition-all text-sm">+ 계속 추가</button>
          )}
          <button type="button" disabled={!preview} onClick={() => handleSave(false)} className="flex-1 py-4 px-2 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 active:scale-95 disabled:opacity-30 transition-all text-sm">
            {editTarget ? '기록 업데이트' : '저장 후 닫기'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default MealInputForm;

export enum MealType {
  BREAKFAST = '아침',
  LUNCH = '점심',
  SNACK = '간식',
  DINNER = '저녁'
}

export enum MealStatus {
  PLANNED = 'PLANNED',
  ACTUAL = 'ACTUAL',
  CANCELED = 'CANCELED'
}

export interface Ingredient {
  uuid: string;
  name: string;
  base_amount: number;
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  sugar: number;
  fiber: number;
  is_bookmarked?: boolean; // 즐겨찾기 여부
}

export interface MealRecord {
  uuid: string;
  type: MealType;
  status: MealStatus; // 예정(PLANNED), 실제(ACTUAL), 취소(CANCELED)
  date: string; // YYYY-MM-DD
  time: string; // HH:mm
  ingredient_uuid: string;
  ingredient_name?: string; // 저장된 이름 (일회성 식단 대응)
  amount: number;
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  sugar: number;
  fiber: number;
  pending?: boolean; // For optimistic UI
}

export interface DailySummary {
  actual: {
    kcal: number;
    carbs: number;
    protein: number;
    fat: number;
  };
  planned: {
    kcal: number;
    carbs: number;
    protein: number;
    fat: number;
  };
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) {
        setIsSidebarOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (isInputOpen) {
        setIsInputOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (adviceModalOpen) {
        setAdviceModalOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, adviceModalOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  // 취소된 데이터(CANCELED)는 필터링하여 UI 및 요약 집계에서 제외
  const filteredMeals = useMemo(() => {
    return meals.filter(m => 
      String(m.date).startsWith(selectedDate) && 
      m.status !== MealStatus.CANCELED
    );
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    // actual은 필터링된 식단 중 ACTUAL만 계산
    const actual = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((acc, cur) => ({
        kcal: acc.kcal + (Number(cur.kcal) || 0),
        carbs: acc.carbs + (Number(cur.carbs) || 0),
        protein: acc.protein + (Number(cur.protein) || 0),
        fat: acc.fat + (Number(cur.fat) || 0),
      }), { ...initial });

    // planned 합계도 필터링된 식단(CANCELED 제외)을 기준으로 계산
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });

    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    if (isUpdate) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }
    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }
    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { 
      ...target, 
      status,
      time: status === MealStatus.ACTUAL ? getKSTTime() : target.time,
      pending: true 
    };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
      }
    } catch (err) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m));
    }
  }, [meals]);

  // 논리적 삭제 구현: status를 CANCELED로 업데이트
  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;

    const previousMeals = [...meals];
    console.log(`[Soft Delete] Target UUID: ${uuid}`);

    // UI 낙관적 업데이트: 상태를 CANCELED로 변경 (filteredMeals에 의해 즉시 사라짐)
    setMeals(prev => prev.map(m => 
      String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m
    ));

    try {
      // 서버에도 업데이트 명령을 보내 상태를 CANCELED로 기록
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success === false) {
        console.error("[Soft Delete Failed] Server rejected. Rolling back UI.");
        setMeals(previousMeals);
        return false;
      }
      console.log("[Soft Delete Success] Record status set to CANCELED on server.");
      return true;
    } catch (err) {
      console.error("[Soft Delete Error] Exception:", err);
      setMeals(previousMeals);
      return false;
    }
  }, [meals]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, []);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    setIngredients(prev => prev.map(i => String(i.uuid) === String(ing.uuid) ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, []);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    // 식재료 삭제는 물리 삭제 유지 (식재료 관리 화면)
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => String(i.uuid) !== String(uuid)));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients]);

  const handleOpenQuickInput = () => {
    setEditMealTarget(null);
    setPrefilledType(null);
    setSelectedDate(getKSTDate());
    setIsInputOpen(true);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl">
      <header className="bg-indigo-600 text-white p-4 sticky top-0 z-50 shadow-lg flex items-center">
        <button 
          onClick={() => setIsSidebarOpen(true)}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
        <h1 className="ml-2 text-xl font-bold">
          {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
        </h1>
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />
            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  onAdd={() => {
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                  onSetStatus={handleSetMealStatus}
                />
              ))}
            </div>
            <button 
              onClick={() => setAdviceModalOpen(true)}
              className="w-full mt-8 py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"
            >
              <span className="text-xl">✨</span>
              <span>AI 영양 추천 받기</span>
            </button>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement 
            ingredients={ingredients}
            onToggleBookmark={handleToggleBookmark}
            onAddIngredient={handleAddIngredient}
            onUpdateIngredient={handleUpdateIngredient}
            onDeleteIngredient={handleDeleteIngredient}
          />
        ) : (
          <Statistics 
            meals={meals} 
            onDateSelect={(date) => {
              setSelectedDate(date);
              setCurrentView('main');
            }} 
          />
        )}
      </main>

      {currentView === 'main' && (
        <button 
          onClick={handleOpenQuickInput}
          className="fixed bottom-6 right-6 w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 hover:scale-105 transition-all animate-in zoom-in slide-in-from-bottom-10 duration-500"
          aria-label="식단 추가"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
          </svg>
        </button>
      )}

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => {
            setIsInputOpen(false);
            setEditMealTarget(null);
          }}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          editTarget={editMealTarget}
          ingredients={ingredients}
          onSave={onSaveMeal}
          onDelete={onDeleteMeal}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.actual.kcal}
          currentProtein={summary.actual.protein}
        />
      )}

      {isExitModalOpen && (
        <ExitModal 
          isOpen={isExitModalOpen}
          onClose={() => {
            setIsExitModalOpen(false);
            window.history.pushState({ noBackExitsApp: true }, '');
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => Promise<boolean>;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const isEditingDirect = editTarget?.ingredient_uuid === 'direct-entry';

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  const [status, setStatus] = useState<MealStatus>(editTarget?.status || MealStatus.ACTUAL);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    (editTarget && !isEditingDirect) ? (ingredients.find(i => String(i.uuid) === String(editTarget.ingredient_uuid)) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(isEditingDirect);
  const [newName, setNewName] = useState(isEditingDirect ? editTarget?.ingredient_name || '' : '');
  const [newBase, setNewBase] = useState(isEditingDirect ? editTarget?.amount.toString() || '1' : '1');
  const [newKcal, setNewKcal] = useState(isEditingDirect ? editTarget?.kcal.toString() || '' : '');
  const [newCarbs, setNewCarbs] = useState(isEditingDirect ? editTarget?.carbs.toString() || '' : '');
  const [newProtein, setNewProtein] = useState(isEditingDirect ? editTarget?.protein.toString() || '' : '');
  const [newFat, setNewFat] = useState(isEditingDirect ? editTarget?.fat.toString() || '' : '');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  useEffect(() => {
    if (isAddingNew && !isEditingDirect) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated > 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew, isEditingDirect]);

  useEffect(() => {
    if (!prefilledType && !editTarget) {
      const h = parseInt(time.split(':')[0]);
      const m = parseInt(time.split(':')[1]);
      const totalMin = h * 60 + m;
      if (totalMin >= 360 && totalMin < 720) setType(MealType.BREAKFAST);
      else if (totalMin >= 720 && totalMin < 840) setType(MealType.LUNCH);
      else if (totalMin >= 840 && totalMin < 1080) setType(MealType.SNACK);
      else setType(MealType.DINNER);
    }
  }, [time, prefilledType, editTarget]);

  const bookmarkedIngredients = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 12);
  }, [ingredients]);

  const filteredIngredients = useMemo(() => {
    if (!searchTerm) return [];
    return ingredients
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => (b.is_bookmarked ? 1 : 0) - (a.is_bookmarked ? 1 : 0))
      .slice(0, 8);
  }, [searchTerm, ingredients]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const factor = parseFloat(amount) / (parseFloat(newBase) || 1);
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
        sugar: 0,
        fiber: 0,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
      sugar: (ing.sugar || 0) * factor,
      fiber: (ing.fiber || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (keepOpen: boolean) => {
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = selectedIngredient?.name || newName || '직접 입력 식단';
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    const newMeal: MealRecord = {
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status,
      date,
      time,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      ...preview
    };

    onSave(newMeal, newIngData);

    if (keepOpen) {
      setSearchTerm('');
      setSelectedIngredient(null);
      setAmount('1');
      setIsAddingNew(false);
      setNewName('');
      setNewKcal('');
      setNewCarbs('');
      setNewProtein('');
      setNewFat('');
      setShouldSaveToIngredients(false);
    } else {
      onClose();
    }
  };

  const handleDelete = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (editTarget && onDelete) {
      // 샌드박스 보안 정책 때문에 window.confirm이 차단되므로 바로 실행
      try {
        const success = await onDelete(editTarget.uuid);
        if (success) {
          onClose();
        } else {
          // alert도 차단될 수 있으므로 콘솔에 상세 기록
          console.error("Deletion failed on server/App level.");
        }
      } catch (err) {
        console.error("[Form Error] Deletion exception:", err);
      }
    }
  };

  return (
    <div 
      className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4"
      onClick={onClose}
    >
      <div 
        className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 duration-500"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-6 overflow-y-auto">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">날짜</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-1">시간</label>
              <input type="time" value={time} onChange={e => setTime(e.target.value)} className="w-full bg-gray-50 p-3 rounded-2xl border-none ring-1 ring-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식사 분류</label>
            <div className="flex bg-gray-100 p-1 rounded-2xl">
