import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) {
        setIsSidebarOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (isInputOpen) {
        setIsInputOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (adviceModalOpen) {
        setAdviceModalOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, adviceModalOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => {
    return meals.filter(m => 
      String(m.date).startsWith(selectedDate) && 
      m.status !== MealStatus.CANCELED
    );
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };

    const actual = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((acc, cur) => ({
        kcal: acc.kcal + (Number(cur.kcal) || 0),
        carbs: acc.carbs + (Number(cur.carbs) || 0),
        protein: acc.protein + (Number(cur.protein) || 0),
        fat: acc.fat + (Number(cur.fat) || 0),
      }), { ...initial });

    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });

    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    if (isUpdate) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }
    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }
    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { 
      ...target, 
      status,
      time: status === MealStatus.ACTUAL ? getKSTTime() : target.time,
      pending: true 
    };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
      }
    } catch (err) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m));
    }
  }, [meals]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const previousMeals = [...meals];

    // UI 낙관적 업데이트: 상태를 CANCELED로 변경 (filteredMeals에서 즉시 사라짐)
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));

    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else {
        setMeals(previousMeals);
        return false;
      }
    } catch (err) {
      setMeals(previousMeals);
      return false;
    }
  }, [meals]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, []);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    setIngredients(prev => prev.map(i => String(i.uuid) === String(ing.uuid) ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, []);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => String(i.uuid) !== String(uuid)));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients]);

  const handleOpenQuickInput = () => {
    setEditMealTarget(null);
    setPrefilledType(null);
    setSelectedDate(getKSTDate());
    setIsInputOpen(true);
  };

  const handleCopyDiet = useCallback(() => {
    const actualMeals = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .sort((a, b) => {
        // 시간 정렬 시 HH:mm 형식을 보장하기 위해 한 자리 수 시간(예: 8:00) 앞에 '0'을 패딩함
        const padTime = (t: string) => {
          if (!t.includes(':')) return t;
          const [h, m] = t.split(':');
          return `${h.padStart(2, '0')}:${m}`;
        };
        return padTime(a.time).localeCompare(padTime(b.time));
      });

    if (actualMeals.length === 0) {
      alert("오늘 완료된 식단 기록이 없습니다.");
      return;
    }

    let text = `[${selectedDate} 식단 기록]\n\n`;
    actualMeals.forEach((meal, idx) => {
      text += `${idx + 1}. ${meal.type} (${meal.time})\n`;
      text += `- 메뉴: ${meal.ingredient_name || '식재료 정보 없음'}\n`;
      text += `- 열량: ${Math.round(meal.kcal)} kcal\n`;
      text += `- 탄수화물: ${Math.round(meal.carbs)}g\n`;
      text += `- 단백질: ${Math.round(meal.protein)}g\n`;
      text += `- 지방: ${Math.round(meal.fat)}g\n\n`;
    });

    text += `총 섭취: ${Math.round(summary.actual.kcal)} kcal\n`;
    text += `(탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g)`;

    navigator.clipboard.writeText(text).then(() => {
      alert("식단 기록이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Copy failed", err);
      alert("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl">
      <header className="bg-indigo-600 text-white p-4 sticky top-0 z-50 shadow-lg flex items-center">
        <button 
          onClick={() => setIsSidebarOpen(true)}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
        <h1 className="ml-2 text-xl font-bold">
          {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
        </h1>
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar 
              selectedDate={selectedDate} 
              onSelectDate={setSelectedDate} 
              meals={meals}
            />

            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  onAdd={() => {
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                  onSetStatus={handleSetMealStatus}
                />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={() => setAdviceModalOpen(true)}
                className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">✨</span>
                <span>AI 영양 추천 받기</span>
              </button>

              <button 
                onClick={handleCopyDiet}
                className="w-full py-4 bg-white text-indigo-600 border-2 border-indigo-50 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 복사하기</span>
              </button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement 
            ingredients={ingredients}
            onToggleBookmark={handleToggleBookmark}
            onAddIngredient={handleAddIngredient}
            onUpdateIngredient={handleUpdateIngredient}
            onDeleteIngredient={handleDeleteIngredient}
          />
        ) : (
          <Statistics 
            meals={meals} 
            onDateSelect={(date) => {
              setSelectedDate(date);
              setCurrentView('main');
            }} 
          />
        )}
      </main>

      {currentView === 'main' && (
        <button 
          onClick={handleOpenQuickInput}
          className="fixed bottom-6 right-6 w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 hover:scale-105 transition-all animate-in zoom-in slide-in-from-bottom-10 duration-500"
          aria-label="식단 추가"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
          </svg>
        </button>
      )}

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => {
            setIsInputOpen(false);
            setEditMealTarget(null);
          }}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          editTarget={editMealTarget}
          ingredients={ingredients}
          meals={meals}
          onSave={onSaveMeal}
          onDelete={onDeleteMeal}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.actual.kcal}
          currentProtein={summary.actual.protein}
        />
      )}

      {isExitModalOpen && (
        <ExitModal 
          isOpen={isExitModalOpen}
          onClose={() => {
            setIsExitModalOpen(false);
            window.history.pushState({ noBackExitsApp: true }, '');
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  meals: MealRecord[]; // 어제 기록 조회를 위해 추가
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => Promise<boolean>;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, meals, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const isDirectEntryEdit = editTarget?.ingredient_uuid === 'direct-entry';

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    (editTarget && !isDirectEntryEdit) ? (ingredients.find(i => String(i.uuid) === String(editTarget.ingredient_uuid)) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  // 임의입력(직접 입력) 관련 상태
  const [isAddingNew, setIsAddingNew] = useState(isDirectEntryEdit);
  const [newName, setNewName] = useState(editTarget?.ingredient_name || '');
  const [newBase, setNewBase] = useState(editTarget?.amount.toString() || '1');
  const [newKcal, setNewKcal] = useState(editTarget?.kcal.toString() || '');
  const [newCarbs, setNewCarbs] = useState(editTarget?.carbs.toString() || '');
  const [newProtein, setNewProtein] = useState(editTarget?.protein.toString() || '');
  const [newFat, setNewFat] = useState(editTarget?.fat.toString() || '');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  // 어제 먹은 동일 타입 식단 찾기
  const yesterdayMeal = useMemo(() => {
    if (editTarget) return null; // 수정 모드일 때는 추천하지 않음

    // 선택된 날짜의 하루 전날 구하기
    const current = new Date(date);
    current.setDate(current.getDate() - 1);
    const yesterdayStr = current.toISOString().split('T')[0];

    // 어제 날짜 + 현재 선택된 식사 타입과 일치하는 실제 기록(ACTUAL) 찾기
    const found = meals.find(m => 
      m.date === yesterdayStr && 
      m.type === type && 
      m.status === MealStatus.ACTUAL
    );

    return found || null;
  }, [meals, date, type, editTarget]);

  // 어제 식단 클릭 핸들러
  const handleSelectYesterdayMeal = useCallback(() => {
    if (!yesterdayMeal) return;

    const isDirect = yesterdayMeal.ingredient_uuid === 'direct-entry';
    const mealAmount = yesterdayMeal.amount.toString();

    if (isDirect) {
      setIsAddingNew(true);
      setNewName(yesterdayMeal.ingredient_name || '');
      setAmount(mealAmount);
      setNewBase(mealAmount); // 임의입력은 먹은 양이 곧 기준량이 됨
      setNewKcal(yesterdayMeal.kcal.toString());
      setNewCarbs(yesterdayMeal.carbs.toString());
      setNewProtein(yesterdayMeal.protein.toString());
      setNewFat(yesterdayMeal.fat.toString());
    } else {
      const ing = ingredients.find(i => String(i.uuid) === String(yesterdayMeal.ingredient_uuid));
      if (ing) {
        setIsAddingNew(false);
        setSelectedIngredient(ing);
        setAmount(mealAmount);
      } else {
        // 식재료가 목록에서 사라진 경우 임의입력으로 전환하여 데이터 보존
        setIsAddingNew(true);
        setNewName(yesterdayMeal.ingredient_name || '복구된 메뉴');
        setAmount(mealAmount);
        setNewBase(mealAmount);
        setNewKcal(yesterdayMeal.kcal.toString());
        setNewCarbs(yesterdayMeal.carbs.toString());
        setNewProtein(yesterdayMeal.protein.toString());
        setNewFat(yesterdayMeal.fat.toString());
      }
    }
  }, [yesterdayMeal, ingredients]);

  // 검색 필터링 로직
  const searchResults = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return ingredients.filter(i => 
      i.name.toLowerCase().includes(searchTerm.toLowerCase())
    ).slice(0, 20); // 성능을 위해 상위 20개만 표시
  }, [ingredients, searchTerm]);

  const bookmarks = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 10);
  }, [ingredients]);

  // 커스텀 삭제 확인 UI 상태
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    // 수동 입력(신규/수정 모두) 시 탄단지 변경에 따른 칼로리 자동 계산
    if (isAddingNew) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated >= 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const currentAmount = parseFloat(amount) || 0;
      const currentBase = parseFloat(newBase) || 1;
      const factor = currentBase === 0 ? 0 : currentAmount / currentBase;
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = ing.base_amount === 0 ? 0 : parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (finalStatus: MealStatus) => {
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = isAddingNew ? (newName || '직접 입력 식단') : (selectedIngredient?.name || '식재료 정보 없음');
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    onSave({
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status: finalStatus,
      date,
      time,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      kcal: preview.kcal,
      carbs: preview.carbs,
      protein: preview.protein,
      fat: preview.fat,
      sugar: 0,
      fiber: 0
    }, newIngData);
    onClose();
  };

  const confirmDelete = async () => {
    if (editTarget && onDelete) {
      setIsDeleting(true);
      setShowDeleteConfirm(false); 
      try {
        const success = await onDelete(editTarget.uuid);
        if (success) onClose();
        else setIsDeleting(false);
      } catch (err) {
        setIsDeleting(false);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4" onClick={onClose}>
      <div className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 relative" onClick={e => e.stopPropagation()}>

        {/* 커스텀 삭제 확인 레이어 */}
        {showDeleteConfirm && (
          <div className="absolute inset-0 z-[130] bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in duration-200">
            <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center text-red-500 mb-6">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </div>
            <h3 className="text-2xl font-black text-gray-900 mb-2">정말 삭제할까요?</h3>
            <p className="text-gray-500 font-medium mb-8">기록된 영양 데이터가 통계에서 제외됩니다.</p>
            <div className="flex flex-col w-full space-y-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-500 text-white font-black rounded-2xl shadow-lg active:scale-95 transition-all">네, 삭제할게요</button>
              <button onClick={() => setShowDeleteConfirm(false)} className="w-full py-4 bg-gray-100 text-gray-500 font-bold rounded-2xl active:scale-95 transition-all">아니오, 유지할게요</button>
            </div>
          </div>
        )}

        {/* 삭제 로딩 레이어 */}
        {isDeleting && (
          <div className="absolute inset-0 z-[140] bg-white/60 backdrop-blur-[1px] flex flex-col items-center justify-center animate-in fade-in">
            <div className="w-10 h-10 border-4 border-red-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="mt-4 text-xs font-bold text-red-500">삭제하는 중...</p>
          </div>
        )}

        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-6 pb-3 space-y-4 overflow-y-auto min-h-[300px]">
          {/* 식사 종류 및 시간 설정 섹션 */}
          <div className="space-y-4 p-4 bg-gray-50 rounded-3xl">
            <div className="flex bg-gray-200/50 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map((mType) => (
                <button
                  key={mType}
                  onClick={() => setType(mType)}
                  className={`flex-1 py-2.5 text-xs rounded-xl transition-all font-black ${
                    type === mType ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'
                  }`}
                >
                  {mType}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="relative">
                <label className="absolute left-3 top-1 text-[8px] font-black text-gray-400 uppercase">날짜</label>
                <input 
                  type="date" 
                  value={date} 
                  onChange={e => setDate(e.target.value)} 
                  className="w-full pt-4 pb-2 px-3 rounded-xl border-none ring-1 ring-gray-200 bg-white text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                />
              </div>
              <div className="relative">
                <label className="absolute left-3 top-1 text-[8px] font-black text-gray-400 uppercase">시간</label>
                <input 
                  type="time" 
                  value={time} 
                  onChange={e => setTime(e.target.value)} 
                  className="w-full pt-4 pb-2 px-3 rounded-xl border-none ring-1 ring-gray-200 bg-white text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                />
              </div>
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-6 animate-in fade-in">
              <div className="relative">
                <input 
                  autoFocus 
                  type="text" 
                  placeholder="식재료 검색..." 
                  value={searchTerm} 
                  onChange={e => setSearchTerm(e.target.value)} 
                  className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white font-medium" 
                />
                <button onClick={() => setIsAddingNew(true)} className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-indigo-600 underline">직접 입력</button>
              </div>

              {searchTerm.trim() === '' ? (
                <div className="space-y-4">
                  {/* 어제 먹은 메뉴 추천 섹션 */}
                  {yesterdayMeal && (
                    <div className="space-y-3 animate-in slide-in-from-top-2">
                      <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-1 flex items-center">
                        <span className="mr-1">🕒</span> 어제 먹은 {type} 메뉴
                      </h3>
                      <button 
                        onClick={handleSelectYesterdayMeal}
                        className="w-full p-4 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-100 flex justify-between items-center active:scale-[0.98] transition-all group"
                      >
                        <div className="text-left flex-1 truncate mr-2">
                          <p className="text-xs font-black opacity-70 mb-0.5">그대로 복사하기</p>
                          <p className="text-sm font-bold truncate">{yesterdayMeal.ingredient_name || '식재료'} / {yesterdayMeal.amount}g</p>
                        </div>
                        <div className="bg-white/20 p-2 rounded-full group-hover:bg-white/30 transition-colors">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                            <path d="M7 9a2 2 0 012-2h6a2 2 0 012 2v6a2 2 0 01-2 2H9a2 2 0 01-2-2V9z" />
                            <path d="M5 5a2 2 0 012-2h6a2 2 0 012 2v2H7a2 2 0 00-2 2v6H5a2 2 0 01-2-2V7a2 2 0 012-2z" />
                          </svg>
                        </div>
                      </button>
                    </div>
                  )}

                  <div className="space-y-3">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">자주 찾는 식재료</h3>
                    <div className="grid grid-cols-2 gap-2">
                      {bookmarks.length > 0 ? bookmarks.map(i => (
                        <button key={i.uuid} onClick={() => setSelectedIngredient(i)} className="p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-left hover:bg-indigo-100 transition-colors flex items-center space-x-2">
                          <span className="text-amber-500 text-xs">⭐</span>
                          <p className="text-xs font-bold text-indigo-900 truncate">{i.name}</p>
                        </button>
                      )) : (
                        <p className="col-span-2 text-center py-4 text-xs text-gray-300 italic">즐겨찾기한 식재료가 없습니다.</p>
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="space-y-3">
                  <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-1">검색 결과</h3>
                  <div className="space-y-2 max-h-[250px] overflow-y-auto pr-1 custom-scrollbar">
                    {searchResults.length > 0 ? searchResults.map(i => (
                      <button key={i.uuid} onClick={() => setSelectedIngredient(i)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl flex justify-between items-center shadow-sm hover:border-indigo-300 transition-colors">
                        <div>
                          <p className="text-sm font-bold text-gray-800">{i.name}</p>
                          <p className="text-[10px] text-gray-400">{i.base_amount}g 기준 {i.kcal}kcal</p>
                        </div>
                        <div className="text-right">
                          <p className="text-[10px] font-bold text-indigo-600">P {i.protein}g</p>
                        </div>
                      </button>
                    )) : (
                      <div className="text-center py-10 bg-gray-50 rounded-2xl">
                        <p className="text-xs text-gray-400 mb-3">검색 결과가 없습니다.</p>
                        <button onClick={() => { setIsAddingNew(true); setNewName(searchTerm); }} className="text-xs font-black text-indigo-600 underline">'{searchTerm}' 직접 등록하기</button>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          ) : isAddingNew ? (
            <div className="space-y-4 animate-in fade-in duration-300">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식단 이름</label>
                <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름 (예: 엄마표 볶음밥)" className="w-full p-4 rounded-2xl border bg-white focus:ring-2 focus:ring-indigo-500 outline-none font-bold" />
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">탄(g)</label>
                  <input type="number" placeholder="0" value={newCarbs} onChange={e => setNewCarbs(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">단(g)</label>
                  <input type="number" placeholder="0" value={newProtein} onChange={e => setNewProtein(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">지(g)</label>
                  <input type="number" placeholder="0" value={newFat} onChange={e => setNewFat(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
              </div>
              <div className="pt-2 border-t border-indigo-100">
                <div className="flex justify-between items-end mb-1 px-1">
                  <label className="text-[10px] font-black text-indigo-600 uppercase">현재 섭취량 (g)</label>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-[10px] font-bold text-gray-400">
                      C {Math.round(preview?.carbs || 0)}g · P {Math.round(preview?.protein || 0)}g · F {Math.round(preview?.fat || 0)}g
                    </span>
                    <span className="text-sm font-black text-indigo-600">{Math.round(preview?.kcal || 0)} kcal</span>
                  </div>
                </div>
                <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-4 rounded-2xl border-2 border-indigo-500 text-3xl font-black text-center bg-white outline-none" />
              </div>
              {!editTarget && (
                <div className="flex items-center space-x-2 pt-2">
                  <input type="checkbox" id="saveToIng" checked={shouldSaveToIngredients} onChange={e => setShouldSaveToIngredients(e.target.checked)} className="w-4 h-4 text-indigo-600 rounded" />
                  <label htmlFor="saveToIng" className="text-xs font-bold text-gray-500">이 식단 정보를 식재료 목록에도 저장할게요</label>
                </div>
              )}
              {isAddingNew && !isDirectEntryEdit && (
                <button onClick={() => { setIsAddingNew(false); setSelectedIngredient(null); setSearchTerm(''); }} className="w-full py-2 text-xs font-bold text-gray-400 hover:text-indigo-500 underline transition-colors">식재료 검색으로 돌아가기</button>
              )}
            </div>
          ) : (
            <div className="bg-indigo-50/50 p-5 pb-4 rounded-[40px] space-y-4 animate-in slide-in-from-right-4">
              <div className="flex justify-between items-start">
                <h3 className="font-black text-indigo-600 text-2xl truncate mr-4">{selectedIngredient?.name}</h3>
                {!editTarget && <button onClick={() => setSelectedIngredient(null)} className="text-xs text-indigo-400 font-bold underline shrink-0">변경</button>}
              </div>
              <div className="space-y-2">
                <div className="flex justify-between items-end px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">양 (g)</label>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-[9px] font-bold text-indigo-400">
                      C {Math.round(preview?.carbs || 0)}g · P {Math.round(preview?.protein || 0)}g · F {Math.round(preview?.fat || 0)}g
                    </span>
                    <span className="text-sm font-black text-indigo-600">{Math.round(preview?.kcal || 0)} kcal</span>
                  </div>
                </div>
                <input autoFocus type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-4 bg-white rounded-3xl ring-2 ring-indigo-500 text-3xl font-black text-center outline-none" />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 pt-3 border-t bg-gray-50 flex flex-col space-y-3">
          <div className="flex space-x-2">
            {editTarget && (
              <button 
                onClick={() => setShowDeleteConfirm(true)} 
                disabled={isDeleting} 
                className="px-4 py-4 bg-red-50 text-red-500 font-black rounded-2xl border border-red-100 transition-all text-xs hover:bg-red-100 active:scale-95 disabled:opacity-30"
              >
                삭제
              </button>
            )}
            <button 
              disabled={!preview || isDeleting} 
              onClick={() => handleSave(MealStatus.PLANNED)} 
              className="flex-1 py-4 bg-white text-gray-500 border border-gray-200 font-black rounded-2xl active:scale-95 disabled:opacity-30 transition-all text-sm"
            >
              예정으로 저장
            </button>
            <button 
              disabled={!preview || isDeleting} 
              onClick={() => handleSave(MealStatus.ACTUAL)} 
              className="flex-[1.5] py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl active:scale-95 disabled:opacity-30 transition-all text-sm"
            >
              {editTarget ? '수정 완료' : '식단 저장'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealInputForm;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  meals: MealRecord[];
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => Promise<boolean>;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, meals, onSave, onDelete }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const isDirectEntryEdit = editTarget?.ingredient_uuid === 'direct-entry';

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    (editTarget && !isDirectEntryEdit) ? (ingredients.find(i => String(i.uuid) === String(editTarget.ingredient_uuid)) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(isDirectEntryEdit);
  const [newName, setNewName] = useState(editTarget?.ingredient_name || '');
  const [newBase, setNewBase] = useState(editTarget?.amount.toString() || '1');
  const [newKcal, setNewKcal] = useState(editTarget?.kcal.toString() || '');
  const [newCarbs, setNewCarbs] = useState(editTarget?.carbs.toString() || '');
  const [newProtein, setNewProtein] = useState(editTarget?.protein.toString() || '');
  const [newFat, setNewFat] = useState(editTarget?.fat.toString() || '');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  // 어제 먹은 동일 타입의 '모든' 식단 찾기 (복수 노출 대응)
  const yesterdayMeals = useMemo(() => {
    if (editTarget) return []; 

    const current = new Date(date);
    current.setDate(current.getDate() - 1);
    const yesterdayStr = current.toISOString().split('T')[0];

    return meals.filter(m => 
      m.date === yesterdayStr && 
      m.type === type && 
      m.status === MealStatus.ACTUAL
    );
  }, [meals, date, type, editTarget]);

  // 특정 어제 식단 선택 핸들러
  const handleSelectYesterdayMeal = useCallback((meal: MealRecord) => {
    const isDirect = meal.ingredient_uuid === 'direct-entry';
    const mealAmount = meal.amount.toString();

    if (isDirect) {
      setIsAddingNew(true);
      setNewName(meal.ingredient_name || '');
      setAmount(mealAmount);
      setNewBase(mealAmount); 
      setNewKcal(meal.kcal.toString());
      setNewCarbs(meal.carbs.toString());
      setNewProtein(meal.protein.toString());
      setNewFat(meal.fat.toString());
    } else {
      const ing = ingredients.find(i => String(i.uuid) === String(meal.ingredient_uuid));
      if (ing) {
        setIsAddingNew(false);
        setSelectedIngredient(ing);
        setAmount(mealAmount);
      } else {
        setIsAddingNew(true);
        setNewName(meal.ingredient_name || '복구된 메뉴');
        setAmount(mealAmount);
        setNewBase(mealAmount);
        setNewKcal(meal.kcal.toString());
        setNewCarbs(meal.carbs.toString());
        setNewProtein(meal.protein.toString());
        setNewFat(meal.fat.toString());
      }
    }
  }, [ingredients]);

  const searchResults = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return ingredients.filter(i => 
      i.name.toLowerCase().includes(searchTerm.toLowerCase())
    ).slice(0, 20);
  }, [ingredients, searchTerm]);

  const bookmarks = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 10);
  }, [ingredients]);

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    if (isAddingNew) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated >= 0) {
        setNewKcal(calculated.toFixed(1));
      }
    }
  }, [newCarbs, newProtein, newFat, isAddingNew]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const currentAmount = parseFloat(amount) || 0;
      const currentBase = parseFloat(newBase) || 1;
      const factor = currentBase === 0 ? 0 : currentAmount / currentBase;
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = ing.base_amount === 0 ? 0 : parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (finalStatus: MealStatus) => {
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = isAddingNew ? (newName || '직접 입력 식단') : (selectedIngredient?.name || '식재료 정보 없음');
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    onSave({
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status: finalStatus,
      date,
      time,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      kcal: preview.kcal,
      carbs: preview.carbs,
      protein: preview.protein,
      fat: preview.fat,
      sugar: 0,
      fiber: 0
    }, newIngData);
    onClose();
  };

  const confirmDelete = async () => {
    if (editTarget && onDelete) {
      setIsDeleting(true);
      setShowDeleteConfirm(false); 
      try {
        const success = await onDelete(editTarget.uuid);
        if (success) onClose();
        else setIsDeleting(false);
      } catch (err) {
        setIsDeleting(false);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4" onClick={onClose}>
      <div className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 relative" onClick={e => e.stopPropagation()}>

        {showDeleteConfirm && (
          <div className="absolute inset-0 z-[130] bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in duration-200">
            <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center text-red-500 mb-6">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </div>
            <h3 className="text-2xl font-black text-gray-900 mb-2">정말 삭제할까요?</h3>
            <p className="text-gray-500 font-medium mb-8">기록된 영양 데이터가 통계에서 제외됩니다.</p>
            <div className="flex flex-col w-full space-y-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-500 text-white font-black rounded-2xl shadow-lg active:scale-95 transition-all">네, 삭제할게요</button>
              <button onClick={() => setShowDeleteConfirm(false)} className="w-full py-4 bg-gray-100 text-gray-500 font-bold rounded-2xl active:scale-95 transition-all">아니오, 유지할게요</button>
            </div>
          </div>
        )}

        {isDeleting && (
          <div className="absolute inset-0 z-[140] bg-white/60 backdrop-blur-[1px] flex flex-col items-center justify-center animate-in fade-in">
            <div className="w-10 h-10 border-4 border-red-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="mt-4 text-xs font-bold text-red-500">삭제하는 중...</p>
          </div>
        )}

        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-6 pb-3 space-y-4 overflow-y-auto min-h-[300px]">
          <div className="space-y-4 p-4 bg-gray-50 rounded-3xl">
            <div className="flex bg-gray-200/50 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map((mType) => (
                <button
                  key={mType}
                  onClick={() => setType(mType)}
                  className={`flex-1 py-2.5 text-xs rounded-xl transition-all font-black ${
                    type === mType ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'
                  }`}
                >
                  {mType}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="relative">
                <label className="absolute left-3 top-1 text-[8px] font-black text-gray-400 uppercase">날짜</label>
                <input 
                  type="date" 
                  value={date} 
                  onChange={e => setDate(e.target.value)} 
                  className="w-full pt-4 pb-2 px-3 rounded-xl border-none ring-1 ring-gray-200 bg-white text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                />
              </div>
              <div className="relative">
                <label className="absolute left-3 top-1 text-[8px] font-black text-gray-400 uppercase">시간</label>
                <input 
                  type="time" 
                  value={time} 
                  onChange={e => setTime(e.target.value)} 
                  className="w-full pt-4 pb-2 px-3 rounded-xl border-none ring-1 ring-gray-200 bg-white text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                />
              </div>
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-6 animate-in fade-in">
              <div className="relative">
                <input 
                  autoFocus 
                  type="text" 
                  placeholder="식재료 검색..." 
                  value={searchTerm} 
                  onChange={e => setSearchTerm(e.target.value)} 
                  className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white font-medium" 
                />
                <button onClick={() => setIsAddingNew(true)} className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-indigo-600 underline">직접 입력</button>
              </div>

              {searchTerm.trim() === '' ? (
                <div className="space-y-5">
                  {yesterdayMeals.length > 0 && (
                    <div className="space-y-3 animate-in slide-in-from-top-2">
                      <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-1 flex items-center">
                        <span className="mr-1">🕒</span> 어제 먹은 {type} 메뉴 ({yesterdayMeals.length})
                      </h3>
                      <div className="space-y-2">
                        {yesterdayMeals.map((meal) => (
                          <button 
                            key={meal.uuid}
                            onClick={() => handleSelectYesterdayMeal(meal)}
                            className="w-full p-4 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-50 flex justify-between items-center active:scale-[0.98] transition-all group border-b-2 border-indigo-700"
                          >
                            <div className="text-left flex-1 truncate mr-2">
                              <p className="text-[10px] font-black opacity-70 mb-0.5">그대로 가져오기</p>
                              <p className="text-sm font-bold truncate">{meal.ingredient_name || '식재료'} / {meal.amount}g</p>
                            </div>
                            <div className="bg-white/20 p-2 rounded-full group-hover:bg-white/30 transition-colors">
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                                <path d="M7 9a2 2 0 012-2h6a2 2 0 012 2v6a2 2 0 01-2 2H9a2 2 0 01-2-2V9z" />
                                <path d="M5 5a2 2 0 012-2h6a2 2 0 012 2v2H7a2 2 0 00-2 2v6H5a2 2 0 01-2-2V7a2 2 0 012-2z" />
                              </svg>
                            </div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}

                  <div className="space-y-3">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">자주 찾는 식재료</h3>
                    <div className="grid grid-cols-2 gap-2">
                      {bookmarks.length > 0 ? bookmarks.map(i => (
                        <button key={i.uuid} onClick={() => setSelectedIngredient(i)} className="p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-left hover:bg-indigo-100 transition-colors flex items-center space-x-2">
                          <span className="text-amber-500 text-xs">⭐</span>
                          <p className="text-xs font-bold text-indigo-900 truncate">{i.name}</p>
                        </button>
                      )) : (
                        <p className="col-span-2 text-center py-4 text-xs text-gray-300 italic">즐겨찾기한 식재료가 없습니다.</p>
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="space-y-3">
                  <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-1">검색 결과</h3>
                  <div className="space-y-2 max-h-[250px] overflow-y-auto pr-1 custom-scrollbar">
                    {searchResults.length > 0 ? searchResults.map(i => (
                      <button key={i.uuid} onClick={() => setSelectedIngredient(i)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl flex justify-between items-center shadow-sm hover:border-indigo-300 transition-colors">
                        <div>
                          <p className="text-sm font-bold text-gray-800">{i.name}</p>
                          <p className="text-[10px] text-gray-400">{i.base_amount}g 기준 {i.kcal}kcal</p>
                        </div>
                        <div className="text-right">
                          <p className="text-[10px] font-bold text-indigo-600">P {i.protein}g</p>
                        </div>
                      </button>
                    )) : (
                      <div className="text-center py-10 bg-gray-50 rounded-2xl">
                        <p className="text-xs text-gray-400 mb-3">검색 결과가 없습니다.</p>
                        <button onClick={() => { setIsAddingNew(true); setNewName(searchTerm); }} className="text-xs font-black text-indigo-600 underline">'{searchTerm}' 직접 등록하기</button>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          ) : isAddingNew ? (
            <div className="space-y-4 animate-in fade-in duration-300">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식단 이름</label>
                <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름 (예: 엄마표 볶음밥)" className="w-full p-4 rounded-2xl border bg-white focus:ring-2 focus:ring-indigo-500 outline-none font-bold" />
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">탄(g)</label>
                  <input type="number" placeholder="0" value={newCarbs} onChange={e => setNewCarbs(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">단(g)</label>
                  <input type="number" placeholder="0" value={newProtein} onChange={e => setNewProtein(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">지(g)</label>
                  <input type="number" placeholder="0" value={newFat} onChange={e => setNewFat(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
              </div>
              <div className="pt-2 border-t border-indigo-100">
                <div className="flex justify-between items-end mb-1 px-1">
                  <label className="text-[10px] font-black text-indigo-600 uppercase">현재 섭취량 (g)</label>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-[10px] font-bold text-gray-400">
                      C {Math.round(preview?.carbs || 0)}g · P {Math.round(preview?.protein || 0)}g · F {Math.round(preview?.fat || 0)}g
                    </span>
                    <span className="text-sm font-black text-indigo-600">{Math.round(preview?.kcal || 0)} kcal</span>
                  </div>
                </div>
                <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-4 rounded-2xl border-2 border-indigo-500 text-3xl font-black text-center bg-white outline-none" />
              </div>
              {!editTarget && (
                <div className="flex items-center space-x-2 pt-2">
                  <input type="checkbox" id="saveToIng" checked={shouldSaveToIngredients} onChange={e => setShouldSaveToIngredients(e.target.checked)} className="w-4 h-4 text-indigo-600 rounded" />
                  <label htmlFor="saveToIng" className="text-xs font-bold text-gray-500">이 식단 정보를 식재료 목록에도 저장할게요</label>
                </div>
              )}
              {isAddingNew && !isDirectEntryEdit && (
                <button onClick={() => { setIsAddingNew(false); setSelectedIngredient(null); setSearchTerm(''); }} className="w-full py-2 text-xs font-bold text-gray-400 hover:text-indigo-500 underline transition-colors">식재료 검색으로 돌아가기</button>
              )}
            </div>
          ) : (
            <div className="bg-indigo-50/50 p-5 pb-4 rounded-[40px] space-y-4 animate-in slide-in-from-right-4">
              <div className="flex justify-between items-start">
                <h3 className="font-black text-indigo-600 text-2xl truncate mr-4">{selectedIngredient?.name}</h3>
                {!editTarget && <button onClick={() => setSelectedIngredient(null)} className="text-xs text-indigo-400 font-bold underline shrink-0">변경</button>}
              </div>
              <div className="space-y-2">
                <div className="flex justify-between items-end px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">양 (g)</label>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-[9px] font-bold text-indigo-400">
                      C {Math.round(preview?.carbs || 0)}g · P {Math.round(preview?.protein || 0)}g · F {Math.round(preview?.fat || 0)}g
                    </span>
                    <span className="text-sm font-black text-indigo-600">{Math.round(preview?.kcal || 0)} kcal</span>
                  </div>
                </div>
                <input autoFocus type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-4 bg-white rounded-3xl ring-2 ring-indigo-500 text-3xl font-black text-center outline-none" />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 pt-3 border-t bg-gray-50 flex flex-col space-y-3">
          <div className="flex space-x-2">
            {editTarget && (
              <button 
                onClick={() => setShowDeleteConfirm(true)} 
                disabled={isDeleting} 
                className="px-4 py-4 bg-red-50 text-red-500 font-black rounded-2xl border border-red-100 transition-all text-xs hover:bg-red-100 active:scale-95 disabled:opacity-30"
              >
                삭제
              </button>
            )}
            <button 
              disabled={!preview || isDeleting} 
              onClick={() => handleSave(MealStatus.PLANNED)} 
              className="flex-1 py-4 bg-white text-gray-500 border border-gray-200 font-black rounded-2xl active:scale-95 disabled:opacity-30 transition-all text-sm"
            >
              예정으로 저장
            </button>
            <button 
              disabled={!preview || isDeleting} 
              onClick={() => handleSave(MealStatus.ACTUAL)} 
              className="flex-[1.5] py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl active:scale-95 disabled:opacity-30 transition-all text-sm"
            >
              {editTarget ? '수정 완료' : '식단 저장'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealInputForm;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) {
        setIsSidebarOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (isInputOpen) {
        setIsInputOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (adviceModalOpen) {
        setAdviceModalOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, adviceModalOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => {
    return meals.filter(m => 
      String(m.date).startsWith(selectedDate) && 
      m.status !== MealStatus.CANCELED
    );
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };

    const actual = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((acc, cur) => ({
        kcal: acc.kcal + (Number(cur.kcal) || 0),
        carbs: acc.carbs + (Number(cur.carbs) || 0),
        protein: acc.protein + (Number(cur.protein) || 0),
        fat: acc.fat + (Number(cur.fat) || 0),
      }), { ...initial });

    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });

    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    if (isUpdate) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }
    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }
    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { 
      ...target, 
      status,
      time: status === MealStatus.ACTUAL ? getKSTTime() : target.time,
      pending: true 
    };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
      }
    } catch (err) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m));
    }
  }, [meals]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const previousMeals = [...meals];

    // UI 낙관적 업데이트: 상태를 CANCELED로 변경 (filteredMeals에서 즉시 사라짐)
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));

    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else {
        setMeals(previousMeals);
        return false;
      }
    } catch (err) {
      setMeals(previousMeals);
      return false;
    }
  }, [meals]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, []);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    setIngredients(prev => prev.map(i => String(i.uuid) === String(ing.uuid) ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, []);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => String(i.uuid) !== String(uuid)));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients]);

  const handleCopyDiet = useCallback(() => {
    const actualMeals = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .sort((a, b) => {
        const padTime = (t: string) => {
          if (!t.includes(':')) return t;
          const [h, m] = t.split(':');
          return `${h.padStart(2, '0')}:${m}`;
        };
        return padTime(a.time).localeCompare(padTime(b.time));
      });

    if (actualMeals.length === 0) {
      alert("오늘 완료된 식단 기록이 없습니다.");
      return;
    }

    let text = `[${selectedDate} 식단 기록]\n\n`;
    actualMeals.forEach((meal, idx) => {
      text += `${idx + 1}. ${meal.type} (${meal.time})\n`;
      text += `- 메뉴: ${meal.ingredient_name || '식재료 정보 없음'}\n`;
      text += `- 열량: ${Math.round(meal.kcal)} kcal\n`;
      text += `- 탄수화물: ${Math.round(meal.carbs)}g\n`;
      text += `- 단백질: ${Math.round(meal.protein)}g\n`;
      text += `- 지방: ${Math.round(meal.fat)}g\n\n`;
    });

    text += `총 섭취: ${Math.round(summary.actual.kcal)} kcal\n`;
    text += `(탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g)`;

    navigator.clipboard.writeText(text).then(() => {
      alert("식단 기록이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Copy failed", err);
      alert("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl">
      <header className="bg-indigo-600 text-white p-4 sticky top-0 z-50 shadow-lg flex items-center">
        <button 
          onClick={() => setIsSidebarOpen(true)}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
        <h1 className="ml-2 text-xl font-bold">
          {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
        </h1>
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar 
              selectedDate={selectedDate} 
              onSelectDate={setSelectedDate} 
              meals={meals}
            />

            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  onAdd={() => {
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                  onSetStatus={handleSetMealStatus}
                />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={() => setAdviceModalOpen(true)}
                className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">✨</span>
                <span>AI 영양 추천 받기</span>
              </button>

              <button 
                onClick={handleCopyDiet}
                className="w-full py-4 bg-white text-indigo-600 border-2 border-indigo-50 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 복사하기</span>
              </button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement 
            ingredients={ingredients}
            onToggleBookmark={handleToggleBookmark}
            onAddIngredient={handleAddIngredient}
            onUpdateIngredient={handleUpdateIngredient}
            onDeleteIngredient={handleDeleteIngredient}
          />
        ) : (
          <Statistics 
            meals={meals} 
            onDateSelect={(date) => {
              setSelectedDate(date);
              setCurrentView('main');
            }} 
          />
        )}
      </main>

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => {
            setIsInputOpen(false);
            setEditMealTarget(null);
          }}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          editTarget={editMealTarget}
          ingredients={ingredients}
          meals={meals}
          onSave={onSaveMeal}
          onDelete={onDeleteMeal}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.actual.kcal}
          currentProtein={summary.actual.protein}
        />
      )}

      {isExitModalOpen && (
        <ExitModal 
          isOpen={isExitModalOpen}
          onClose={() => {
            setIsExitModalOpen(false);
            window.history.pushState({ noBackExitsApp: true }, '');
          }}
        />
      )}
    </div>
  );
};

