            </button>
            <button
              type="submit"
              className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg active:scale-95 transition-all"
            >
              확인
            </button>
          </div>
        </form>
      </div>
    </div>
  );
