import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  // 관리자 상태 관리
  const [isAdmin, setIsAdmin] = useState<boolean>(() => {
    return localStorage.getItem('isAdmin') === 'true';
  });
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) {
        setIsSidebarOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (isInputOpen) {
        setIsInputOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (adviceModalOpen) {
        setAdviceModalOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (isAdminLoginOpen) {
        setIsAdminLoginOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => {
    return meals.filter(m => 
      String(m.date).startsWith(selectedDate) && 
      m.status !== MealStatus.CANCELED
    );
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };

    const actual = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((acc, cur) => ({
        kcal: acc.kcal + (Number(cur.kcal) || 0),
        carbs: acc.carbs + (Number(cur.carbs) || 0),
        protein: acc.protein + (Number(cur.protein) || 0),
        fat: acc.fat + (Number(cur.fat) || 0),
      }), { ...initial });

    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });

    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    if (isUpdate) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }
    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }
    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { 
      ...target, 
      status,
      time: status === MealStatus.ACTUAL ? getKSTTime() : target.time,
      pending: true 
    };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
      }
    } catch (err) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m));
    }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return false;
    }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const previousMeals = [...meals];

    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));

    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else {
        setMeals(previousMeals);
        return false;
      }
    } catch (err) {
      setMeals(previousMeals);
      return false;
    }
  }, [meals, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients, isAdmin]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, [isAdmin]);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    setIngredients(prev => prev.map(i => String(i.uuid) === String(ing.uuid) ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, [isAdmin]);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => String(i.uuid) !== String(uuid)));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients, isAdmin]);

  const handleLogin = (success: boolean) => {
    if (success) {
      setIsAdmin(true);
      localStorage.setItem('isAdmin', 'true');
    }
  };

  const handleLogout = () => {
    if (confirm('관리자 모드를 해제하고 로그아웃 하시겠습니까?')) {
      setIsAdmin(false);
      localStorage.removeItem('isAdmin');
    }
  };

  const handleCopyDiet = useCallback(() => {
    const actualMeals = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .sort((a, b) => {
        const padTime = (t: string) => {
          if (!t.includes(':')) return t;
          const [h, m] = t.split(':');
          return `${h.padStart(2, '0')}:${m}`;
        };
        return padTime(a.time).localeCompare(padTime(b.time));
      });

    if (actualMeals.length === 0) {
      alert("오늘 완료된 식단 기록이 없습니다.");
      return;
    }

    let text = `[${selectedDate} 식단 기록]\n\n`;
    actualMeals.forEach((meal, idx) => {
      text += `${idx + 1}. ${meal.type} (${meal.time})\n`;
      text += `- 메뉴: ${meal.ingredient_name || '식재료 정보 없음'}\n`;
      text += `- 열량: ${Math.round(meal.kcal)} kcal\n`;
      text += `- 탄수화물: ${Math.round(meal.carbs)}g\n`;
      text += `- 단백질: ${Math.round(meal.protein)}g\n`;
      text += `- 지방: ${Math.round(meal.fat)}g\n\n`;
    });

    text += `총 섭취: ${Math.round(summary.actual.kcal)} kcal\n`;
    text += `(탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g)`;

    navigator.clipboard.writeText(text).then(() => {
      alert("식단 기록이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Copy failed", err);
      alert("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {!isAdmin && (
        <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">
          체험 모드로 접속 중입니다
        </div>
      )}
      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <h1 className="ml-2 text-xl font-bold">
            {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
          </h1>
        </div>
        {isAdmin && (
          <button 
            onClick={handleLogout}
            className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"
            title="관리자 로그아웃"
          >
            <div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div>
            <span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span>
          </button>
        )}
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
        isAdmin={isAdmin}
        onLogout={handleLogout}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar 
              selectedDate={selectedDate} 
              onSelectDate={setSelectedDate} 
              meals={meals}
            />

            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  isAdmin={isAdmin}
                  onAdd={() => {
                    if (!isAdmin) {
                      alert(TRIAL_MESSAGE);
                      return;
                    }
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    if (!isAdmin) {
                      alert(TRIAL_MESSAGE);
                      return;
                    }
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                  onSetStatus={handleSetMealStatus}
                />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={() => setAdviceModalOpen(true)}
                className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">✨</span>
                <span>AI 영양 추천 받기</span>
              </button>

              <button 
                onClick={handleCopyDiet}
                className="w-full py-4 bg-white text-indigo-600 border-2 border-indigo-50 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 복사하기</span>
              </button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement 
            ingredients={ingredients}
            isAdmin={isAdmin}
            onToggleBookmark={handleToggleBookmark}
            onAddIngredient={handleAddIngredient}
            onUpdateIngredient={handleUpdateIngredient}
            onDeleteIngredient={handleDeleteIngredient}
            trialMessage={TRIAL_MESSAGE}
          />
        ) : (
          <Statistics 
            meals={meals} 
            onDateSelect={(date) => {
              setSelectedDate(date);
              setCurrentView('main');
            }} 
          />
        )}
      </main>

      {/* 관리자 로그인 버튼 (FAB) */}
      {!isAdmin && (
        <button 
          onClick={() => setIsAdminLoginOpen(true)}
          className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
          </svg>
        </button>
      )}

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => {
            setIsInputOpen(false);
            setEditMealTarget(null);
          }}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          editTarget={editMealTarget}
          ingredients={ingredients}
          meals={meals}
          isAdmin={isAdmin}
          onSave={onSaveMeal}
          onDelete={onDeleteMeal}
          trialMessage={TRIAL_MESSAGE}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.actual.kcal}
          currentProtein={summary.actual.protein}
        />
      )}

      {isAdminLoginOpen && (
        <AdminLoginModal 
          isOpen={isAdminLoginOpen}
          onClose={() => setIsAdminLoginOpen(false)}
          onLogin={handleLogin}
        />
      )}

      {isExitModalOpen && (
        <ExitModal 
          isOpen={isExitModalOpen}
          onClose={() => {
            setIsExitModalOpen(false);
            window.history.pushState({ noBackExitsApp: true }, '');
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Ingredient } from '../types';

interface Props {
  ingredients: Ingredient[];
  isAdmin: boolean;
  onToggleBookmark: (uuid: string) => void;
  onAddIngredient: (ing: Ingredient) => void;
  onUpdateIngredient: (ing: Ingredient) => void;
  onDeleteIngredient: (uuid: string) => void;
  trialMessage?: string;
}

const IngredientManagement: React.FC<Props> = ({ ingredients, isAdmin, onToggleBookmark, onAddIngredient, onUpdateIngredient, onDeleteIngredient, trialMessage }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [editTarget, setEditTarget] = useState<Ingredient | null>(null);
  const [isAdding, setIsAdding] = useState(false);

  const sortedIngredients = useMemo(() => {
    return [...ingredients]
      .filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => {
        const aBooked = !!a.is_bookmarked;
        const bBooked = !!b.is_bookmarked;
        if (aBooked && !bBooked) return -1;
        if (!aBooked && bBooked) return 1;
        return a.name.localeCompare(b.name);
      });
  }, [ingredients, searchTerm]);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-black text-gray-800">식재료 관리</h2>
        <button 
          onClick={() => isAdmin ? setIsAdding(true) : alert(trialMessage)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-lg shadow-indigo-100 flex items-center space-x-2 active:scale-95 transition-transform"
        >
          <span>+ 등록</span>
        </button>
      </div>

      <div className="relative">
        <input 
          type="text" 
          placeholder="식재료 이름 검색..." 
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white p-4 pr-12 rounded-2xl shadow-sm border border-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
        />
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 absolute right-4 top-1/2 -translate-y-1/2 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
        </svg>
      </div>

      <div className="grid grid-cols-1 gap-3 pb-24">
        {sortedIngredients.length === 0 ? (
          <div className="py-20 text-center text-gray-400 italic">
            검색 결과가 없습니다.
          </div>
        ) : (
          sortedIngredients.map(ing => (
            <button 
              key={ing.uuid} 
              onClick={() => isAdmin ? setEditTarget(ing) : alert(trialMessage)}
              className={`w-full text-left bg-white p-4 rounded-2xl shadow-sm border flex justify-between items-center group relative overflow-hidden active:scale-[0.98] transition-all ${ing.is_bookmarked ? 'border-amber-200 ring-1 ring-amber-100' : 'border-gray-50'}`}
            >
              {ing.is_bookmarked && (
                <div className="absolute top-0 left-0 w-1 h-full bg-amber-400"></div>
              )}
              <div className="flex items-center space-x-4">
                <div 
                  onClick={(e) => {
                    e.stopPropagation();
                    if (isAdmin) onToggleBookmark(ing.uuid);
                    else alert(trialMessage);
                  }}
                  className={`p-2 rounded-full transition-all ${ing.is_bookmarked ? 'bg-amber-50 text-amber-500 scale-110 shadow-sm' : 'text-gray-300 hover:text-amber-400'}`}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                  </svg>
                </div>
                <div>
                  <h4 className="font-bold text-gray-800 flex items-center">
                    {ing.name}
                  </h4>
                  <p className="text-xs text-gray-400">기준: {ing.base_amount}g / {ing.kcal}kcal</p>
                </div>
              </div>
              <div className="text-right flex flex-col items-end">
                <div className="flex space-x-2 text-[10px] font-bold text-gray-400">
                  <span className="text-orange-600">C {ing.carbs}g</span>
                  <span className="text-emerald-600">P {ing.protein}g</span>
                  <span className="text-blue-600">F {ing.fat}g</span>
                </div>
              </div>
            </button>
          ))
        )}
      </div>

      {(isAdding || editTarget) && (
        <IngredientFormModal 
          target={editTarget} 
          onClose={() => { setIsAdding(false); setEditTarget(null); }} 
          onDelete={onDeleteIngredient}
          onSave={(data) => {
            if (editTarget) onUpdateIngredient(data);
            else onAddIngredient(data);
            setIsAdding(false);
            setEditTarget(null);
          }} 
        />
      )}
    </div>
  );
};

const IngredientFormModal: React.FC<{ target: Ingredient | null, onClose: () => void, onSave: (ing: Ingredient) => void, onDelete: (uuid: string) => void }> = ({ target, onClose, onSave, onDelete }) => {
  const [formData, setFormData] = useState({
    name: target?.name || '', 
    base: target?.base_amount?.toString() || '1', 
    kcal: target?.kcal?.toString() || '', 
    carbs: target?.carbs?.toString() || '', 
    protein: target?.protein?.toString() || '', 
    fat: target?.fat?.toString() || ''
  });

  const handleSave = () => {
    if (!formData.name || !formData.kcal) return;
    onSave({
      uuid: target?.uuid || crypto.randomUUID(),
      name: formData.name,
      base_amount: parseFloat(formData.base),
      kcal: parseFloat(formData.kcal),
      carbs: parseFloat(formData.carbs || '0'),
      protein: parseFloat(formData.protein || '0'),
      fat: parseFloat(formData.fat || '0'),
      sugar: target?.sugar || 0,
      fiber: target?.fiber || 0,
      is_bookmarked: target?.is_bookmarked || false
    });
  };

  const handleDelete = () => {
    if (target && confirm('이 식재료를 삭제할까요?')) {
      onDelete(target.uuid);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-sm rounded-3xl overflow-hidden shadow-2xl">
        <div className="p-6 bg-indigo-600 text-white">
          <h3 className="text-xl font-bold">{target ? '식재료 수정' : '신규 식재료 등록'}</h3>
        </div>
        <div className="p-6 space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">식재료 이름</label>
            <input 
              placeholder="식재료 이름" 
              value={formData.name} 
              onChange={e => setFormData({...formData, name: e.target.value})}
              className="w-full p-3 bg-gray-50 rounded-xl border focus:ring-2 focus:ring-indigo-500 outline-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">기준(g)</label>
              <input value={formData.base} onChange={e => setFormData({...formData, base: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">칼로리(kcal)</label>
              <input value={formData.kcal} onChange={e => setFormData({...formData, kcal: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
          </div>
          <div className="grid grid-cols-3 gap-3">
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">탄수화물(g)</label>
              <input placeholder="탄" value={formData.carbs} onChange={e => setFormData({...formData, carbs: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">단백질(g)</label>
              <input placeholder="단" value={formData.protein} onChange={e => setFormData({...formData, protein: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] text-gray-400 font-bold ml-1 uppercase">지방(g)</label>
              <input placeholder="지" value={formData.fat} onChange={e => setFormData({...formData, fat: e.target.value})} className="w-full p-3 bg-gray-50 rounded-xl border text-sm" />
            </div>
          </div>
          <div className="flex space-x-3 pt-4">
            {target && (
              <button onClick={handleDelete} className="px-4 py-3 bg-red-50 text-red-500 font-bold border border-red-100 rounded-xl active:scale-95 transition-transform">삭제</button>
            )}
            <button onClick={onClose} className="flex-1 py-3 text-gray-400 font-bold border rounded-xl">취소</button>
            <button onClick={handleSave} className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg active:scale-95 transition-transform">저장</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default IngredientManagement;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark 
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  // 관리자 상태 관리
  const [isAdmin, setIsAdmin] = useState<boolean>(() => {
    return localStorage.getItem('isAdmin') === 'true';
  });
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);

  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());
  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) {
        setIsSidebarOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (isInputOpen) {
        setIsInputOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (adviceModalOpen) {
        setAdviceModalOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      if (isAdminLoginOpen) {
        setIsAdminLoginOpen(false);
        window.history.pushState({ noBackExitsApp: true }, '');
        return;
      }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => {
    return meals.filter(m => 
      String(m.date).startsWith(selectedDate) && 
      m.status !== MealStatus.CANCELED
    );
  }, [meals, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };

    const actual = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((acc, cur) => ({
        kcal: acc.kcal + (Number(cur.kcal) || 0),
        carbs: acc.carbs + (Number(cur.carbs) || 0),
        protein: acc.protein + (Number(cur.protein) || 0),
        fat: acc.fat + (Number(cur.fat) || 0),
      }), { ...initial });

    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });

    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    if (isUpdate) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m));
    } else {
      setMeals(prev => [...prev, { ...newMeal, pending: true }]);
    }
    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
      saveIngredientToGAS(newIngredient);
    }
    try {
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
      }
    } catch (error) {
      console.error("Meal save/update failed", error);
    }
  }, [meals, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { 
      ...target, 
      status,
      time: status === MealStatus.ACTUAL ? getKSTTime() : target.time,
      pending: true 
    };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
      }
    } catch (err) {
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m));
    }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return false;
    }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const previousMeals = [...meals];

    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));

    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else {
        setMeals(previousMeals);
        return false;
      }
    } catch (err) {
      setMeals(previousMeals);
      return false;
    }
  }, [meals, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const nextState = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: nextState } : i));
    try {
      await updateIngredientBookmark(uuid, nextState);
    } catch (err) {
      setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !nextState } : i));
    }
  }, [ingredients, isAdmin]);

  const handleAddIngredient = useCallback((ing: Ingredient) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    setIngredients(prev => [...prev, ing]);
    saveIngredientToGAS(ing);
  }, [isAdmin]);

  const handleUpdateIngredient = useCallback(async (ing: Ingredient) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    setIngredients(prev => prev.map(i => String(i.uuid) === String(ing.uuid) ? ing : i));
    try {
      await updateIngredientInGAS(ing);
    } catch (err) {
      console.error("Update ingredient failed", err);
    }
  }, [isAdmin]);

  const handleDeleteIngredient = useCallback(async (uuid: string) => {
    if (!isAdmin) {
      alert(TRIAL_MESSAGE);
      return;
    }
    const previous = [...ingredients];
    setIngredients(prev => prev.filter(i => String(i.uuid) !== String(uuid)));
    try {
      const success = await deleteIngredientFromGAS(uuid);
      if (!success) setIngredients(previous);
    } catch (err) {
      setIngredients(previous);
    }
  }, [ingredients, isAdmin]);

  const handleLogin = (success: boolean) => {
    if (success) {
      setIsAdmin(true);
      localStorage.setItem('isAdmin', 'true');
    }
  };

  const handleLogout = () => {
    if (confirm('관리자 모드를 해제하고 로그아웃 하시겠습니까?')) {
      setIsAdmin(false);
      localStorage.removeItem('isAdmin');
    }
  };

  const handleCopyDiet = useCallback(() => {
    const actualMeals = filteredMeals
      .filter(m => m.status === MealStatus.ACTUAL)
      .sort((a, b) => {
        const padTime = (t: string) => {
          if (!t.includes(':')) return t;
          const [h, m] = t.split(':');
          return `${h.padStart(2, '0')}:${m}`;
        };
        return padTime(a.time).localeCompare(padTime(b.time));
      });

    if (actualMeals.length === 0) {
      alert("오늘 완료된 식단 기록이 없습니다.");
      return;
    }

    let text = `[${selectedDate} 식단 기록]\n\n`;
    actualMeals.forEach((meal, idx) => {
      text += `${idx + 1}. ${meal.type} (${meal.time})\n`;
      text += `- 메뉴: ${meal.ingredient_name || '식재료 정보 없음'}\n`;
      text += `- 열량: ${Math.round(meal.kcal)} kcal\n`;
      text += `- 탄수화물: ${Math.round(meal.carbs)}g\n`;
      text += `- 단백질: ${Math.round(meal.protein)}g\n`;
      text += `- 지방: ${Math.round(meal.fat)}g\n\n`;
    });

    text += `총 섭취: ${Math.round(summary.actual.kcal)} kcal\n`;
    text += `(탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g)`;

    navigator.clipboard.writeText(text).then(() => {
      alert("식단 기록이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Copy failed", err);
      alert("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-white">
        <div className="flex flex-col items-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-gray-500 font-medium tracking-tight">당신의 기록을 불러오고 있어요</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {!isAdmin && (
        <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">
          체험 모드로 접속 중입니다
        </div>
      )}
      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <h1 className="ml-2 text-xl font-bold">
            {currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}
          </h1>
        </div>
        {isAdmin && (
          <button 
            onClick={handleLogout}
            className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"
            title="관리자 로그아웃"
          >
            <div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div>
            <span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span>
          </button>
        )}
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        currentView={currentView}
        onNavigate={setCurrentView}
        isAdmin={isAdmin}
        onLogout={handleLogout}
        onOpenAdminLogin={() => setIsAdminLoginOpen(true)}
      />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar 
              selectedDate={selectedDate} 
              onSelectDate={setSelectedDate} 
              meals={meals}
            />

            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection 
                  key={type} 
                  type={type} 
                  meals={filteredMeals.filter(m => m.type === type)} 
                  ingredients={ingredients}
                  isAdmin={isAdmin}
                  onAdd={() => {
                    if (!isAdmin) {
                      alert(TRIAL_MESSAGE);
                      return;
                    }
                    setEditMealTarget(null);
                    setPrefilledType(type);
                    setIsInputOpen(true);
                  }}
                  onEdit={(meal) => {
                    if (!isAdmin) {
                      alert(TRIAL_MESSAGE);
                      return;
                    }
                    setEditMealTarget(meal);
                    setIsInputOpen(true);
                  }}
                  onDelete={onDeleteMeal}
                  onSetStatus={handleSetMealStatus}
                />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={() => setAdviceModalOpen(true)}
                className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">✨</span>
                <span>AI 영양 추천 받기</span>
              </button>

              <button 
                onClick={handleCopyDiet}
                className="w-full py-4 bg-white text-indigo-600 border-2 border-indigo-50 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 복사하기</span>
              </button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement 
            ingredients={ingredients}
            isAdmin={isAdmin}
            onToggleBookmark={handleToggleBookmark}
            onAddIngredient={handleAddIngredient}
            onUpdateIngredient={handleUpdateIngredient}
            onDeleteIngredient={handleDeleteIngredient}
            trialMessage={TRIAL_MESSAGE}
          />
        ) : (
          <Statistics 
            meals={meals} 
            onDateSelect={(date) => {
              setSelectedDate(date);
              setCurrentView('main');
            }} 
          />
        )}
      </main>

      {/* 관리자 로그인 버튼 (FAB) */}
      {!isAdmin && (
        <button 
          onClick={() => setIsAdminLoginOpen(true)}
          className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
          </svg>
        </button>
      )}

      {isInputOpen && (
        <MealInputForm 
          isOpen={isInputOpen}
          onClose={() => {
            setIsInputOpen(false);
            setEditMealTarget(null);
          }}
          selectedDate={selectedDate}
          prefilledType={prefilledType}
          editTarget={editMealTarget}
          ingredients={ingredients}
          meals={meals}
          isAdmin={isAdmin}
          onSave={onSaveMeal}
          onDelete={onDeleteMeal}
          trialMessage={TRIAL_MESSAGE}
        />
      )}

      {adviceModalOpen && (
        <AIAdviceModal 
          isOpen={adviceModalOpen}
          onClose={() => setAdviceModalOpen(false)}
          currentKcal={summary.actual.kcal}
          currentProtein={summary.actual.protein}
        />
      )}

      {isAdminLoginOpen && (
        <AdminLoginModal 
          isOpen={isAdminLoginOpen}
          onClose={() => setIsAdminLoginOpen(false)}
          onLogin={handleLogin}
        />
      )}

      {isExitModalOpen && (
        <ExitModal 
          isOpen={isExitModalOpen}
          onClose={() => {
            setIsExitModalOpen(false);
            window.history.pushState({ noBackExitsApp: true }, '');
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  currentView: 'main' | 'ingredients' | 'stats';
  onNavigate: (view: 'main' | 'ingredients' | 'stats') => void;
  isAdmin?: boolean;
  onLogout?: () => void;
  onOpenAdminLogin?: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose, currentView, onNavigate, isAdmin, onLogout, onOpenAdminLogin }) => {
  const [taps, setTaps] = useState(0);
  const tapTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const handleEasterEgg = () => {
    if (isAdmin) return;

    setTaps(prev => {
      const next = prev + 1;
      if (next >= 10) {
        onOpenAdminLogin?.();
        onClose(); // 드로워 닫기
        return 0;
      }
      return next;
    });

    if (tapTimeoutRef.current) clearTimeout(tapTimeoutRef.current);
    tapTimeoutRef.current = setTimeout(() => {
      setTaps(0);
    }, 2000); // 2초 동안 입력이 없으면 카운트 리셋
  };

  return (
    <>
      <div 
        className={`fixed inset-0 bg-black/50 z-[100] transition-opacity duration-300 ${isOpen ? 'opacity-100 visible' : 'opacity-0 invisible'}`}
        onClick={onClose}
      />

      <div 
        className={`fixed top-0 left-0 bottom-0 w-[280px] bg-white z-[101] shadow-2xl transition-transform duration-300 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
      >
        <div className="p-6 bg-indigo-600 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-black">메뉴</h2>
            <p className="text-xs opacity-70">어떤 기록을 원하세요?</p>
          </div>
          <button onClick={onClose} className="p-2 bg-white/10 rounded-full">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <nav className="p-4 space-y-2">
          <MenuButton 
            active={currentView === 'main'} 
            onClick={() => { onNavigate('main'); onClose(); }}
            icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" />}
            label="메인 식단 기록" 
          />
          <MenuButton 
            active={currentView === 'ingredients'} 
            onClick={() => { onNavigate('ingredients'); onClose(); }}
            icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />}
            label="식재료 관리" 
          />
          <MenuButton 
            active={currentView === 'stats'} 
            onClick={() => { onNavigate('stats'); onClose(); }}
            icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />}
            label="나의 통계" 
          />

          <div className="pt-8 px-4 border-t mt-4">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4">Support</p>
            <div className="space-y-4">
               <div className="text-sm text-gray-400 flex items-center space-x-2">
                 <span>⚙️ 설정 (준비중)</span>
               </div>
               {isAdmin && onLogout && (
                 <button 
                  onClick={() => { onLogout(); onClose(); }}
                  className="w-full text-left text-sm text-red-400 flex items-center space-x-2 font-bold"
                 >
                   <span>🔓 관리자 로그아웃</span>
                 </button>
               )}
            </div>
          </div>
        </nav>

        <div 
          onClick={handleEasterEgg}
          className={`absolute bottom-6 left-6 right-6 p-4 rounded-2xl transition-all active:scale-[0.97] select-none ${taps > 0 ? 'bg-indigo-100' : 'bg-indigo-50'}`}
        >
          <p className="text-xs font-bold text-indigo-600 mb-1">식단 목표</p>
          <p className="text-[10px] text-gray-500 italic">매일 1500kcal • 단백질 100g</p>
          {taps > 0 && taps < 10 && (
            <div className="absolute top-1 right-2 text-[8px] font-black text-indigo-300 opacity-50">
              {taps}/10
            </div>
          )}
        </div>
      </div>
    </>
  );
};

const MenuButton: React.FC<{ active: boolean, onClick: () => void, icon: React.ReactNode, label: string }> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center space-x-4 p-4 rounded-2xl transition-all ${active ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-gray-500 hover:bg-gray-50'}`}
  >
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
      {icon}
    </svg>
    <span>{label}</span>
  </button>
);

export default Sidebar;

