import React, { useState, useRef } from 'react';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  currentView: 'main' | 'ingredients' | 'stats';
  onNavigate: (view: 'main' | 'ingredients' | 'stats') => void;
  isAdmin?: boolean;
  onLogout?: () => void;
  onOpenAdminLogin?: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose, currentView, onNavigate, isAdmin, onLogout, onOpenAdminLogin }) => {
  const [taps, setTaps] = useState(0);
  // Browser environment might not have NodeJS namespace, using ReturnType of setTimeout instead
  const tapTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleEasterEgg = () => {
    if (isAdmin) return;

    setTaps(prev => {
      const next = prev + 1;
      if (next >= 10) {
        onOpenAdminLogin?.();
        onClose(); // 드로워 닫기
        return 0;
      }
      return next;
    });

    if (tapTimeoutRef.current) clearTimeout(tapTimeoutRef.current);
    tapTimeoutRef.current = setTimeout(() => {
      setTaps(0);
    }, 2000); // 2초 동안 입력이 없으면 카운트 리셋
  };

  return (
    <>
      <div 
        className={`fixed inset-0 bg-black/50 z-[100] transition-opacity duration-300 ${isOpen ? 'opacity-100 visible' : 'opacity-0 invisible'}`}
        onClick={onClose}
      />

      <div 
        className={`fixed top-0 left-0 bottom-0 w-[280px] bg-white z-[101] shadow-2xl transition-transform duration-300 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
      >
        <div className="p-6 bg-indigo-600 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-black">메뉴</h2>
            <p className="text-xs opacity-70">어떤 기록을 원하세요?</p>
          </div>
          <button onClick={onClose} className="p-2 bg-white/10 rounded-full">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <nav className="p-4 space-y-2">
          <MenuButton 
            active={currentView === 'main'} 
            onClick={() => { onNavigate('main'); onClose(); }}
            icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" />}
            label="메인 식단 기록" 
          />
          <MenuButton 
            active={currentView === 'ingredients'} 
            onClick={() => { onNavigate('ingredients'); onClose(); }}
            icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />}
            label="식재료 관리" 
          />
          <MenuButton 
            active={currentView === 'stats'} 
            onClick={() => { onNavigate('stats'); onClose(); }}
            icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />}
            label="나의 통계" 
          />

          <div className="pt-8 px-4 border-t mt-4">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4">Support</p>
            <div className="space-y-4">
               <div className="text-sm text-gray-400 flex items-center space-x-2">
                 <span>⚙️ 설정 (준비중)</span>
               </div>
               {isAdmin && onLogout && (
                 <button 
                  onClick={() => { onLogout(); onClose(); }}
                  className="w-full text-left text-sm text-red-400 flex items-center space-x-2 font-bold"
                 >
                   <span>🔓 관리자 로그아웃</span>
                 </button>
               )}
            </div>
          </div>
        </nav>

        <div 
          onClick={handleEasterEgg}
          className={`absolute bottom-6 left-6 right-6 p-4 rounded-2xl transition-all active:scale-[0.97] select-none ${taps > 0 ? 'bg-indigo-100' : 'bg-indigo-50'}`}
        >
          <p className="text-xs font-bold text-indigo-600 mb-1">식단 목표</p>
          <p className="text-[10px] text-gray-500 italic">매일 1500kcal • 단백질 100g</p>
          {taps > 0 && taps < 10 && (
            <div className="absolute top-1 right-2 text-[8px] font-black text-indigo-300 opacity-50">
              {taps}/10
            </div>
          )}
        </div>
      </div>
    </>
  );
};

const MenuButton: React.FC<{ active: boolean, onClick: () => void, icon: React.ReactNode, label: string }> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center space-x-4 p-4 rounded-2xl transition-all ${active ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-gray-500 hover:bg-gray-50'}`}
  >
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
      {icon}
    </svg>
    <span>{label}</span>
  </button>
);

export default Sidebar;

import { GoogleGenAI } from "@google/genai";

/**
 * 쿠쿠님의 현재 영양 섭취 상태를 기반으로 Gemini AI 추천을 가져옵니다.
 */
export async function getAIRecommendation(currentKcal: number, currentProtein: number): Promise<string | undefined> {
  // Always obtain the API key exclusively from process.env.API_KEY.
  if (!process.env.API_KEY) {
    console.error("GeminiService: API Key is missing in process.env.");
    return "AI 분석을 위한 설정을 확인해 주세요.";
  }

  try {
    // Initializing the SDK with process.env.API_KEY directly as a named parameter.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `당신은 쿠쿠님의 다정한 전담 영양사입니다. 
쿠쿠님의 현재 상태: 오늘 ${currentKcal.toFixed(0)}kcal 섭취, 단백질 ${currentProtein.toFixed(1)}g 섭취. 
일일 목표: 1500kcal, 단백질 100g. 
남은 할당량 내에서 먹어야 하는 단백질의 양과 kcal를 먼저 숫자로 명시하고, 부족한 양이 없다면 부족함 없이 잘 챙겨 섭취했다는 내용의 칭찬 한마디를 해주세요.
부족한 양이 있다면 남은 할당량 내에서 부족한 단백질을 채울 수 있는 맛있는 메뉴 1가지를 추천하고 응원 한 마디를 해주세요. 
답변은 다양한 이모지를 사용해서 한국어로 3문장 이내로 작성하세요.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    // Access the extracted text output directly via the .text property.
    return response.text || "AI가 답변을 생성하지 못했습니다.";
  } catch (error: any) {
    console.error("Gemini API Error Detail:", error);
    return "AI 분석 중 오류가 발생했습니다. 잠시 후 다시 시도해 주세요.";
  }
}

import React, { useState } from 'react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onLogin: (success: boolean) => void;
}

const AdminLoginModal: React.FC<Props> = ({ isOpen, onClose, onLogin }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // 환경 변수에서 암호를 가져오거나, 프리뷰용 기본 암호 '1234'를 허용합니다.
    const envPassword = (import.meta as any).env?.VITE_ADMIN_PASSWORD || (process.env as any).VITE_ADMIN_PASSWORD;
    const isSuccess = password === envPassword || password === '1234';

    if (isSuccess) {
      onLogin(true);
      onClose();
    } else {
      setError(true);
      setTimeout(() => setError(false), 2000);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 p-6 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-xs rounded-3xl overflow-hidden shadow-2xl animate-in zoom-in duration-300">
        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          <div className="text-center space-y-2">
            <div className="w-12 h-12 bg-indigo-100 rounded-full flex items-center justify-center mx-auto text-indigo-600">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
            </div>
            <h3 className="text-xl font-black text-gray-800">관리자 로그인</h3>
            <p className="text-xs text-gray-400 font-medium">기능 활성화를 위해 암호를 입력하세요.</p>
          </div>

          <div className="space-y-2">
            <input
              autoFocus
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Password"
              className={`w-full p-4 bg-gray-50 rounded-2xl border-2 text-center font-bold outline-none transition-all ${
                error ? 'border-red-400 animate-shake' : 'border-transparent focus:border-indigo-500'
              }`}
            />
            {error && <p className="text-[10px] text-red-500 text-center font-bold">암호가 일치하지 않습니다.</p>}
          </div>

          <div className="flex space-x-2">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 py-4 text-gray-400 font-bold hover:bg-gray-50 rounded-2xl transition-colors"
            >
              취소
            </button>
            <button
              type="submit"
              className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg active:scale-95 transition-all"
            >
              확인
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

