  const handleCopyYesterdayMeals = useCallback(async () => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    // selectedDate 기준 전날 구하기
    const [y, m, d] = selectedDate.split('-').map(Number);
    const dateObj = new Date(y, m - 1, d);
    dateObj.setDate(dateObj.getDate() - 1);
    const yesterdayStr = `${dateObj.getFullYear()}-${String(dateObj.getMonth() + 1).padStart(2, '0')}-${String(dateObj.getDate()).padStart(2, '0')}`;

    const yesterdayMeals = meals.filter(m => m.date === yesterdayStr && m.status !== MealStatus.CANCELED);

    if (yesterdayMeals.length === 0) {
      alert("어제 기록된 식단이 없습니다.");
      return;
    }

    if (filteredMeals.length > 0 && !confirm("이미 오늘 기록된 식단이 있습니다. 어제 식단을 추가로 복사할까요?")) {
      return;
    }

    const newMeals: MealRecord[] = yesterdayMeals.map(m => ({
      ...m,
      uuid: crypto.randomUUID(),
      date: selectedDate,
      status: MealStatus.PLANNED,
      pending: true
    }));

    setMeals(prev => [...prev, ...newMeals]);

    try {
      // 순차적으로 저장 (GAS 안정성을 위해)
      for (const m of newMeals) {
        await saveMealToGAS(m);
      }
      setMeals(prev => prev.map(m => {
        const found = newMeals.find(nm => nm.uuid === m.uuid);
        return found ? { ...m, pending: false } : m;
      }));
    } catch (error) {
      console.error("Failed to copy meals", error);
      alert("식단 복사 중 오류가 발생했습니다.");
    }
  }, [selectedDate, meals, filteredMeals, isAdmin]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };

    // Optimistic Update
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });

    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
    } catch (error) { console.error("Diary save failed", error); }
  }, [selectedDate, currentDiary, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { ...target, status, time: status === MealStatus.ACTUAL ? getKSTTime() : target.time, pending: true };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) { setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m)); }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const prev = [...meals];
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));
    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) { setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m)); return true; }
      else { setMeals(prev); return false; }
    } catch (err) { setMeals(prev); return false; }
  }, [meals, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const next = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));
    try { await updateIngredientBookmark(uuid, next); } catch (err) { setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !next } : i)); }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}
      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="flex space-x-2">
              <button 
                onClick={handleCopyYesterdayMeals}
                className="flex-1 py-4 bg-white border-2 border-dashed border-indigo-100 text-indigo-500 rounded-2xl flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] transition-all"
              >
                <span className="text-lg">📋</span>
                <span>식단 복사</span>
              </button>
              <button 
                onClick={() => setIsDiaryOpen(true)}
                className={`flex-[1.5] py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${
                  currentDiary 
                    ? 'bg-emerald-50 border-emerald-100 text-emerald-600' 
                    : 'bg-white border-dashed border-gray-200 text-gray-400'
                }`}
              >
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '일기 작성'}</span>
              </button>
            </div>

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    setMeals(prev => isUpdate ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) : [...prev, { ...newMeal, pending: true }]);
    if (newIngredient) { setIngredients(prev => [...prev, newIngredient]); saveIngredientToGAS(newIngredient); }
    try {
      isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) { console.error("Meal save/update failed", error); }
  }, [meals, isAdmin]);

  const handleCopyYesterdayMeals = useCallback(async () => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    // selectedDate 기준 전날 구하기
    const [y, m, d] = selectedDate.split('-').map(Number);
    const dateObj = new Date(y, m - 1, d);
    dateObj.setDate(dateObj.getDate() - 1);
    const yesterdayStr = `${dateObj.getFullYear()}-${String(dateObj.getMonth() + 1).padStart(2, '0')}-${String(dateObj.getDate()).padStart(2, '0')}`;

    const yesterdayMeals = meals.filter(m => m.date === yesterdayStr && m.status !== MealStatus.CANCELED);

    if (yesterdayMeals.length === 0) {
      alert("어제 기록된 식단이 없습니다.");
      return;
    }

    if (filteredMeals.length > 0 && !confirm("이미 오늘 기록된 식단이 있습니다. 어제 식단을 추가로 복사할까요?")) {
      return;
    }

    const newMeals: MealRecord[] = yesterdayMeals.map(m => ({
      ...m,
      uuid: crypto.randomUUID(),
      date: selectedDate,
      status: MealStatus.PLANNED,
      pending: true
    }));

    setMeals(prev => [...prev, ...newMeals]);

    try {
      // 순차적으로 저장 (GAS 안정성을 위해)
      for (const m of newMeals) {
        await saveMealToGAS(m);
      }
      setMeals(prev => prev.map(m => {
        const found = newMeals.find(nm => nm.uuid === m.uuid);
        return found ? { ...m, pending: false } : m;
      }));
    } catch (error) {
      console.error("Failed to copy meals", error);
      alert("식단 복사 중 오류가 발생했습니다.");
    }
  }, [selectedDate, meals, filteredMeals, isAdmin]);

  const handleCopyTextToClipboard = useCallback(() => {
    if (filteredMeals.length === 0) {
      alert("기록된 식단이 없습니다.");
      return;
    }

    const typeOrder = {
      [MealType.BREAKFAST]: 1,
      [MealType.LUNCH]: 2,
      [MealType.SNACK]: 3,
      [MealType.DINNER]: 4
    };

    const sorted = [...filteredMeals].sort((a, b) => {
      const orderA = typeOrder[a.type] || 99;
      const orderB = typeOrder[b.type] || 99;
      if (orderA !== orderB) return orderA - orderB;
      return a.time.localeCompare(b.time);
    });

    let text = `[${selectedDate} 식단 기록]\n\n`;
    sorted.forEach(m => {
      const statusIcon = m.status === MealStatus.ACTUAL ? '✅' : '🕒';
      text += `${statusIcon} [${m.type}] ${m.time} | ${m.ingredient_name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
    });

    text += `\n총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;

    navigator.clipboard.writeText(text).then(() => {
      alert("식단 리스트가 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      alert("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };

    // Optimistic Update
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });

    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
    } catch (error) { console.error("Diary save failed", error); }
  }, [selectedDate, currentDiary, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { ...target, status, time: status === MealStatus.ACTUAL ? getKSTTime() : target.time, pending: true };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) { setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m)); }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const prev = [...meals];
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));
    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) { setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m)); return true; }
      else { setMeals(prev); return false; }
    } catch (err) { setMeals(prev); return false; }
  }, [meals, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const next = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));
    try { await updateIngredientBookmark(uuid, next); } catch (err) { setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !next } : i)); }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}
      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="flex space-x-2">
              <button 
                onClick={handleCopyYesterdayMeals}
                className="flex-1 py-4 bg-white border-2 border-dashed border-indigo-100 text-indigo-500 rounded-2xl flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] transition-all"
              >
                <span className="text-lg">📋</span>
                <span>식단 복사</span>
              </button>
              <button 
                onClick={() => setIsDiaryOpen(true)}
                className={`flex-[1.5] py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${
                  currentDiary 
                    ? 'bg-emerald-50 border-emerald-100 text-emerald-600' 
                    : 'bg-white border-dashed border-gray-200 text-gray-400'
                }`}
              >
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '일기 작성'}</span>
              </button>
            </div>

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={handleCopyTextToClipboard}
                className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    setMeals(prev => isUpdate ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) : [...prev, { ...newMeal, pending: true }]);
    if (newIngredient) { setIngredients(prev => [...prev, newIngredient]); saveIngredientToGAS(newIngredient); }
    try {
      isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) { console.error("Meal save/update failed", error); }
  }, [meals, isAdmin]);

  const handleCopyYesterdayMeals = useCallback(async () => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    // selectedDate 기준 전날 구하기
    const [y, m, d] = selectedDate.split('-').map(Number);
    const dateObj = new Date(y, m - 1, d);
    dateObj.setDate(dateObj.getDate() - 1);
    const yesterdayStr = `${dateObj.getFullYear()}-${String(dateObj.getMonth() + 1).padStart(2, '0')}-${String(dateObj.getDate()).padStart(2, '0')}`;

    const yesterdayMeals = meals.filter(m => m.date === yesterdayStr && m.status !== MealStatus.CANCELED);

    if (yesterdayMeals.length === 0) {
      alert("어제 기록된 식단이 없습니다.");
      return;
    }

    if (filteredMeals.length > 0 && !confirm("이미 오늘 기록된 식단이 있습니다. 어제 식단을 추가로 복사할까요?")) {
      return;
    }

    const newMeals: MealRecord[] = yesterdayMeals.map(m => ({
      ...m,
      uuid: crypto.randomUUID(),
      date: selectedDate,
      status: MealStatus.PLANNED,
      pending: true
    }));

    setMeals(prev => [...prev, ...newMeals]);

    try {
      // 순차적으로 저장 (GAS 안정성을 위해)
      for (const m of newMeals) {
        await saveMealToGAS(m);
      }
      setMeals(prev => prev.map(m => {
        const found = newMeals.find(nm => nm.uuid === m.uuid);
        return found ? { ...m, pending: false } : m;
      }));
    } catch (error) {
      console.error("Failed to copy meals", error);
      alert("식단 복사 중 오류가 발생했습니다.");
    }
  }, [selectedDate, meals, filteredMeals, isAdmin]);

  const handleCopyTextToClipboard = useCallback(() => {
    // 섭취 완료된(ACTUAL) 식단만 필터링
    const actualMealsToCopy = filteredMeals.filter(m => m.status === MealStatus.ACTUAL);

    if (actualMealsToCopy.length === 0) {
      alert("섭취 완료된(ACTUAL) 식단이 없습니다.");
      return;
    }

    const typeOrder = {
      [MealType.BREAKFAST]: 1,
      [MealType.LUNCH]: 2,
      [MealType.SNACK]: 3,
      [MealType.DINNER]: 4
    };

    const sorted = [...actualMealsToCopy].sort((a, b) => {
      const orderA = typeOrder[a.type] || 99;
      const orderB = typeOrder[b.type] || 99;
      if (orderA !== orderB) return orderA - orderB;
      return a.time.localeCompare(b.time);
    });

    let text = `[${selectedDate} 식단 기록]\n\n`;
    sorted.forEach(m => {
      text += `✅ [${m.type}] ${m.time} | ${m.ingredient_name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
    });

    text += `\n총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;

    navigator.clipboard.writeText(text).then(() => {
      alert("섭취 완료된 식단 리스트가 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      alert("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };

    // Optimistic Update
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });

    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
    } catch (error) { console.error("Diary save failed", error); }
  }, [selectedDate, currentDiary, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { ...target, status, time: status === MealStatus.ACTUAL ? getKSTTime() : target.time, pending: true };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) { setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m)); }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const prev = [...meals];
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));
    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) { setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m)); return true; }
      else { setMeals(prev); return false; }
    } catch (err) { setMeals(prev); return false; }
  }, [meals, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const next = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));
    try { await updateIngredientBookmark(uuid, next); } catch (err) { setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !next } : i)); }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}
      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="flex space-x-2">
              <button 
                onClick={handleCopyYesterdayMeals}
                className="flex-1 py-4 bg-white border-2 border-dashed border-indigo-100 text-indigo-500 rounded-2xl flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] transition-all"
              >
                <span className="text-lg">📋</span>
                <span>식단 복사</span>
              </button>
              <button 
                onClick={() => setIsDiaryOpen(true)}
                className={`flex-[1.5] py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${
                  currentDiary 
                    ? 'bg-emerald-50 border-emerald-100 text-emerald-600' 
                    : 'bg-white border-dashed border-gray-200 text-gray-400'
                }`}
              >
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '일기 작성'}</span>
              </button>
            </div>

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={handleCopyTextToClipboard}
                className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    setMeals(prev => isUpdate ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) : [...prev, { ...newMeal, pending: true }]);
    if (newIngredient) { setIngredients(prev => [...prev, newIngredient]); saveIngredientToGAS(newIngredient); }
    try {
      isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) { console.error("Meal save/update failed", error); }
  }, [meals, isAdmin]);

  const handleCopyYesterdayMeals = useCallback(async () => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const [y, m, d] = selectedDate.split('-').map(Number);
    const dateObj = new Date(y, m - 1, d);
    dateObj.setDate(dateObj.getDate() - 1);
    const yesterdayStr = `${dateObj.getFullYear()}-${String(dateObj.getMonth() + 1).padStart(2, '0')}-${String(dateObj.getDate()).padStart(2, '0')}`;
    const yesterdayMeals = meals.filter(m => m.date === yesterdayStr && m.status !== MealStatus.CANCELED);
    if (yesterdayMeals.length === 0) {
      alert("어제 기록된 식단이 없습니다.");
      return;
    }
    if (filteredMeals.length > 0 && !confirm("이미 오늘 기록된 식단이 있습니다. 어제 식단을 추가로 복사할까요?")) {
      return;
    }
    const newMeals: MealRecord[] = yesterdayMeals.map(m => ({
      ...m,
      uuid: crypto.randomUUID(),
      date: selectedDate,
      status: MealStatus.PLANNED,
      pending: true
    }));
    setMeals(prev => [...prev, ...newMeals]);
    try {
      for (const m of newMeals) { await saveMealToGAS(m); }
      setMeals(prev => prev.map(m => {
        const found = newMeals.find(nm => nm.uuid === m.uuid);
        return found ? { ...m, pending: false } : m;
      }));
    } catch (error) {
      console.error("Failed to copy meals", error);
      alert("식단 복사 중 오류가 발생했습니다.");
    }
  }, [selectedDate, meals, filteredMeals, isAdmin]);

  const handleCopyTextToClipboard = useCallback(() => {
    const actualMealsToCopy = filteredMeals.filter(m => m.status === MealStatus.ACTUAL);
    if (actualMealsToCopy.length === 0) {
      alert("섭취 완료된(ACTUAL) 식단이 없습니다.");
      return;
    }
    const typeOrder = { [MealType.BREAKFAST]: 1, [MealType.LUNCH]: 2, [MealType.SNACK]: 3, [MealType.DINNER]: 4 };
    const sorted = [...actualMealsToCopy].sort((a, b) => {
      const orderA = typeOrder[a.type] || 99;
      const orderB = typeOrder[b.type] || 99;
      if (orderA !== orderB) return orderA - orderB;
      return a.time.localeCompare(b.time);
    });
    let text = `[${selectedDate} 식단 기록]\n\n`;
    sorted.forEach(m => {
      text += `✅ [${m.type}] ${m.time} | ${m.ingredient_name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
    });
    text += `\n총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;
    navigator.clipboard.writeText(text).then(() => {
      alert("섭취 완료된 식단 리스트가 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      alert("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });
    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
    } catch (error) { console.error("Diary save failed", error); }
  }, [selectedDate, currentDiary, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const updatedMeal: MealRecord = { ...target, status, time: status === MealStatus.ACTUAL ? getKSTTime() : target.time, pending: true };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (success) setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) { setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...target, pending: false } : m)); }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const prev = [...meals];
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));
    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) { setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m)); return true; }
      else { setMeals(prev); return false; }
    } catch (err) { setMeals(prev); return false; }
  }, [meals, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const next = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));
    try { await updateIngredientBookmark(uuid, next); } catch (err) { setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: !next } : i)); }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}
      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={() => setIsDiaryOpen(true)}
                className={`w-full py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${
                  currentDiary 
                    ? 'bg-emerald-50 border-emerald-100 text-emerald-600' 
                    : 'bg-white border-dashed border-gray-200 text-gray-400'
                }`}
              >
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '오늘의 건강 일기 작성'}</span>
              </button>
              <button 
                onClick={handleCopyTextToClipboard}
                className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const FOOD_EMOJIS = ['🥗', '🍎', '🥑', '🍗', '🍳', '🥛', '🍣', '🍱', '🥣', '🥦', '🍌', '🥪'];

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [loadingEmoji, setLoadingEmoji] = useState('🥗');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  // Toast handler
  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setLoadingEmoji(FOOD_EMOJIS[Math.floor(Math.random() * FOOD_EMOJIS.length)]);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
        showToast("데이터를 불러오지 못했습니다.");
      } finally {
        // 최소 로딩 시간 보장 (부드러운 전환을 위해)
        setTimeout(() => setIsLoading(false), 800);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    // Backup for rollback
    const prevMeals = [...meals];
    const prevIngredients = [...ingredients];

    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));

    // Optimistic Update
    setMeals(prev => isUpdate 
      ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) 
      : [...prev, { ...newMeal, pending: true }]
    );
    if (newIngredient) setIngredients(prev => [...prev, newIngredient]);

    try {
      if (newIngredient) await saveIngredientToGAS(newIngredient);
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);

      if (!success) throw new Error("Server response was not ok");

      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) {
      console.error("Meal save/update failed", error);
      // Rollback
      setMeals(prevMeals);
      setIngredients(prevIngredients);
      showToast("저장에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, ingredients, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;

    const prevMeals = [...meals];
    const updatedMeal: MealRecord = { ...target, status, time: status === MealStatus.ACTUAL ? getKSTTime() : target.time, pending: true };

    // Optimistic Update
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));

    try {
      const success = await updateMealInGAS(updatedMeal);
      if (!success) throw new Error("Fail");
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) {
      setMeals(prevMeals);
      showToast("상태 변경에 실패했습니다.");
    }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;

    const prevMeals = [...meals];
    // Optimistic Update (상태를 CANCELED로 변경하여 즉시 UI에서 제거)
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));

    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) { 
        setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m)); 
        return true; 
      } else { 
        throw new Error("Fail");
      }
    } catch (err) {
      setMeals(prevMeals);
      showToast("삭제에 실패했습니다.");
      return false;
    }
  }, [meals, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;

    const prevIngredients = [...ingredients];
    const next = !target.is_bookmarked;

    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));

    try { 
      const success = await updateIngredientBookmark(uuid, next); 
      if (!success) throw new Error("Fail");
    } catch (err) { 
      setIngredients(prevIngredients); 
      showToast("즐겨찾기 변경에 실패했습니다.");
    }
  }, [ingredients, isAdmin]);

  const handleCopyTextToClipboard = useCallback(() => {
    const actualMealsToCopy = filteredMeals.filter(m => m.status === MealStatus.ACTUAL);
    if (actualMealsToCopy.length === 0) {
      alert("섭취 완료된(ACTUAL) 식단이 없습니다.");
      return;
    }
    const typeOrder = { [MealType.BREAKFAST]: 1, [MealType.LUNCH]: 2, [MealType.SNACK]: 3, [MealType.DINNER]: 4 };
    const sorted = [...actualMealsToCopy].sort((a, b) => {
      const orderA = typeOrder[a.type] || 99;
      const orderB = typeOrder[b.type] || 99;
      if (orderA !== orderB) return orderA - orderB;
      return a.time.localeCompare(b.time);
    });
    let text = `[${selectedDate} 식단 기록]\n\n`;
    sorted.forEach(m => {
      text += `✅ [${m.type}] ${m.time} | ${m.ingredient_name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
    });
    text += `\n총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;
    navigator.clipboard.writeText(text).then(() => {
      showToast("식단이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      showToast("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    const prevDiaries = [...diaries];
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };

    // Optimistic Update
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });

    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) {
        setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
      } else {
        throw new Error("Fail");
      }
    } catch (error) { 
      console.error("Diary save failed", error);
      setDiaries(prevDiaries);
      showToast("일기 저장에 실패했습니다.");
    }
  }, [selectedDate, currentDiary, diaries, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {/* 전역 로딩 오버레이 */}
      {isLoading && (
        <div className="fixed inset-0 z-[1000] bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
          <div className="relative mb-8">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center animate-pulse">
              <span className="text-6xl animate-bounce" style={{ display: 'inline-block' }}>{loadingEmoji}</span>
            </div>
            <div className="absolute -inset-2 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          </div>
          <h2 className="text-xl font-black text-gray-800 mb-2">데이터를 불러오는 중입니다...</h2>
          <p className="text-sm text-gray-400 font-medium">잠시만 기다려 주세요 ✨</p>
        </div>
      )}

      {/* Toast Notification */}
      {toastMessage && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] px-6 py-3 bg-gray-800/90 backdrop-blur-sm text-white text-xs font-bold rounded-full shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          {toastMessage}
        </div>
      )}

      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}

      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            {filteredMeals.length === 0 && (
              <div className="py-12 bg-white/50 border-2 border-dashed border-gray-200 rounded-3xl flex flex-col items-center justify-center text-center px-6">
                <span className="text-4xl mb-4">🍽️</span>
                <p className="text-gray-500 font-bold mb-1">기록된 데이터가 없습니다.</p>
                <p className="text-xs text-gray-400">새로운 식단을 추가해 보세요!</p>
              </div>
            )}

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={() => setIsDiaryOpen(true)}
                className={`w-full py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${
                  currentDiary 
                    ? 'bg-emerald-50 border-emerald-100 text-emerald-600' 
                    : 'bg-white border-dashed border-gray-200 text-gray-400'
                }`}
              >
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '오늘의 건강 일기 작성'}</span>
              </button>
              <button 
                onClick={handleCopyTextToClipboard}
                className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const FOOD_EMOJIS = ['🥗', '🍎', '🥑', '🍗', '🍳', '🥛', '🍣', '🍱', '🥣', '🥦', '🍌', '🥪', '🥙', '🥗'];

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [loadingEmoji, setLoadingEmoji] = useState('🥗');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  // Toast handler
  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setLoadingEmoji(FOOD_EMOJIS[Math.floor(Math.random() * FOOD_EMOJIS.length)]);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
        showToast("데이터를 불러오는 중 오류가 발생했습니다.");
      } finally {
        // 부드러운 전환을 위해 약간의 지연 추가
        setTimeout(() => setIsLoading(false), 1200);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    // 롤백을 위한 이전 상태 저장
    const prevMeals = [...meals];
    const prevIngredients = [...ingredients];

    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));

    // 낙관적 업데이트
    setMeals(prev => isUpdate 
      ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) 
      : [...prev, { ...newMeal, pending: true }]
    );
    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
    }

    try {
      if (newIngredient) await saveIngredientToGAS(newIngredient);
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);

      if (!success) throw new Error("Server storage failed");

      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) {
      console.error("Meal save/update failed", error);
      // 롤백
      setMeals(prevMeals);
      setIngredients(prevIngredients);
      showToast("저장에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, ingredients, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;

    const prevMeals = [...meals];
    const updatedMeal: MealRecord = { ...target, status, time: status === MealStatus.ACTUAL ? getKSTTime() : target.time, pending: true };

    // 낙관적 업데이트
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));

    try {
      const success = await updateMealInGAS(updatedMeal);
      if (!success) throw new Error("Update failed");
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) {
      setMeals(prevMeals);
      showToast("상태 변경에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;

    const prevMeals = [...meals];
    // 낙관적 업데이트: UI에서 즉시 제거(또는 취소 상태로)
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));

    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else {
        throw new Error("Delete failed");
      }
    } catch (err) {
      setMeals(prevMeals);
      showToast("삭제에 실패했습니다. 다시 시도해 주세요.");
      return false;
    }
  }, [meals, isAdmin]);

  const handleCopyTextToClipboard = useCallback(() => {
    const actualMealsToCopy = filteredMeals.filter(m => m.status === MealStatus.ACTUAL);
    if (actualMealsToCopy.length === 0) {
      alert("섭취 완료된(ACTUAL) 식단이 없습니다.");
      return;
    }
    const typeOrder = { [MealType.BREAKFAST]: 1, [MealType.LUNCH]: 2, [MealType.SNACK]: 3, [MealType.DINNER]: 4 };
    const sorted = [...actualMealsToCopy].sort((a, b) => {
      const orderA = typeOrder[a.type] || 99;
      const orderB = typeOrder[b.type] || 99;
      if (orderA !== orderB) return orderA - orderB;
      return a.time.localeCompare(b.time);
    });
    let text = `[${selectedDate} 식단 기록]\n\n`;
    sorted.forEach(m => {
      text += `✅ [${m.type}] ${m.time} | ${m.ingredient_name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
    });
    text += `\n총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;

    navigator.clipboard.writeText(text).then(() => {
      showToast("식단이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      showToast("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    const prevDiaries = [...diaries];
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };

    // 낙관적 업데이트
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });

    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) {
        setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
      } else {
        throw new Error("Diary storage failed");
      }
    } catch (error) { 
      console.error("Diary save failed", error);
      setDiaries(prevDiaries);
      showToast("일기 저장에 실패했습니다.");
    }
  }, [selectedDate, currentDiary, diaries, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;

    const prevIngredients = [...ingredients];
    const next = !target.is_bookmarked;

    // 낙관적 업데이트
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));

    try { 
      const success = await updateIngredientBookmark(uuid, next); 
      if (!success) throw new Error("Bookmark failed");
    } catch (err) { 
      setIngredients(prevIngredients); 
      showToast("즐겨찾기 상태 변경에 실패했습니다.");
    }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {/* 전역 로딩 화면 */}
      {isLoading && (
        <div className="fixed inset-0 z-[1000] bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
          <div className="relative mb-8">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center animate-pulse">
              <span className="text-6xl animate-bounce" style={{ display: 'inline-block' }}>{loadingEmoji}</span>
            </div>
            <div className="absolute -inset-2 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          </div>
          <h2 className="text-xl font-black text-gray-800 mb-2">데이터를 불러오는 중입니다...</h2>
          <p className="text-sm text-gray-400 font-medium">잠시만 기다려 주세요 ✨</p>
        </div>
      )}

      {/* 알림 토스트 */}
      {toastMessage && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] px-6 py-3 bg-gray-900/90 backdrop-blur-sm text-white text-xs font-bold rounded-full shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          {toastMessage}
        </div>
      )}

      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}

      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            {/* 빈 날짜 가이드 문구 */}
            {filteredMeals.length === 0 && (
              <div className="py-12 bg-white/50 border-2 border-dashed border-gray-200 rounded-[32px] flex flex-col items-center justify-center text-center px-6 transition-all animate-in zoom-in duration-300">
                <span className="text-4xl mb-4">🍽️</span>
                <p className="text-gray-500 font-bold mb-1">기록된 데이터가 없습니다.</p>
                <p className="text-[10px] text-gray-400">새로운 식단을 추가해 보세요!</p>
              </div>
            )}

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={() => setIsDiaryOpen(true)}
                className={`w-full py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${
                  currentDiary 
                    ? 'bg-emerald-50 border-emerald-100 text-emerald-600' 
                    : 'bg-white border-dashed border-gray-200 text-gray-400'
                }`}
              >
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '오늘의 건강 일기 작성'}</span>
              </button>
              <button 
                onClick={handleCopyTextToClipboard}
                className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const FOOD_EMOJIS = ['🥗', '🍎', '🥑', '🍗', '🍳', '🥛', '🍣', '🍱', '🥣', '🥦', '🍌', '🥪', '🥙', '🥗'];

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [loadingEmoji, setLoadingEmoji] = useState('🥗');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  // Toast handler
  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setLoadingEmoji(FOOD_EMOJIS[Math.floor(Math.random() * FOOD_EMOJIS.length)]);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
        showToast("데이터를 불러오는 중 오류가 발생했습니다.");
      } finally {
        // 부드러운 전환을 위해 약간의 지연 추가
        setTimeout(() => setIsLoading(false), 1200);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    // 롤백을 위한 이전 상태 저장
    const prevMeals = [...meals];
    const prevIngredients = [...ingredients];

    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));

    // 낙관적 업데이트
    setMeals(prev => isUpdate 
      ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) 
      : [...prev, { ...newMeal, pending: true }]
    );
    if (newIngredient) {
      setIngredients(prev => [...prev, newIngredient]);
    }

    try {
      if (newIngredient) await saveIngredientToGAS(newIngredient);
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);

      if (!success) throw new Error("Server storage failed");

      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) {
      console.error("Meal save/update failed", error);
      // 롤백
      setMeals(prevMeals);
      setIngredients(prevIngredients);
      showToast("저장에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, ingredients, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;

    const prevMeals = [...meals];
    const updatedMeal: MealRecord = { ...target, status, time: status === MealStatus.ACTUAL ? getKSTTime() : target.time, pending: true };

    // 낙관적 업데이트
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));

    try {
      const success = await updateMealInGAS(updatedMeal);
      if (!success) throw new Error("Update failed");
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) {
      setMeals(prevMeals);
      showToast("상태 변경에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;

    const prevMeals = [...meals];
    // 낙관적 업데이트: UI에서 즉시 제거(또는 취소 상태로)
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));

    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else {
        throw new Error("Delete failed");
      }
    } catch (err) {
      setMeals(prevMeals);
      showToast("삭제에 실패했습니다. 다시 시도해 주세요.");
      return false;
    }
  }, [meals, isAdmin]);

  const handleCopyTextToClipboard = useCallback(() => {
    const actualMealsToCopy = filteredMeals.filter(m => m.status === MealStatus.ACTUAL);
    if (actualMealsToCopy.length === 0) {
      alert("섭취 완료된(ACTUAL) 식단이 없습니다.");
      return;
    }
    const typeOrder = { [MealType.BREAKFAST]: 1, [MealType.LUNCH]: 2, [MealType.SNACK]: 3, [MealType.DINNER]: 4 };
    const sorted = [...actualMealsToCopy].sort((a, b) => {
      const orderA = typeOrder[a.type] || 99;
      const orderB = typeOrder[b.type] || 99;
      if (orderA !== orderB) return orderA - orderB;
      return a.time.localeCompare(b.time);
    });
    let text = `[${selectedDate} 식단 기록]\n\n`;
    sorted.forEach(m => {
      text += `✅ [${m.type}] ${m.time} | ${m.ingredient_name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
    });
    text += `\n총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;

    navigator.clipboard.writeText(text).then(() => {
      showToast("식단이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      showToast("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }

    const prevDiaries = [...diaries];
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };

    // 낙관적 업데이트
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });

    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) {
        setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
      } else {
        throw new Error("Diary storage failed");
      }
    } catch (error) { 
      console.error("Diary save failed", error);
      setDiaries(prevDiaries);
      showToast("일기 저장에 실패했습니다.");
    }
  }, [selectedDate, currentDiary, diaries, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;

    const prevIngredients = [...ingredients];
    const next = !target.is_bookmarked;

    // 낙관적 업데이트
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));

    try { 
      const success = await updateIngredientBookmark(uuid, next); 
      if (!success) throw new Error("Bookmark failed");
    } catch (err) { 
      setIngredients(prevIngredients); 
      showToast("즐겨찾기 상태 변경에 실패했습니다.");
    }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {/* 전역 로딩 화면 */}
      {isLoading && (
        <div className="fixed inset-0 z-[1000] bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
          <div className="relative mb-8">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center animate-pulse">
              <span className="text-6xl animate-bounce" style={{ display: 'inline-block' }}>{loadingEmoji}</span>
            </div>
            <div className="absolute -inset-2 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          </div>
          <h2 className="text-xl font-black text-gray-800 mb-2">데이터를 불러오는 중입니다...</h2>
          <p className="text-sm text-gray-400 font-medium">잠시만 기다려 주세요 ✨</p>
        </div>
      )}

      {/* 알림 토스트 */}
      {toastMessage && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] px-6 py-3 bg-gray-900/90 backdrop-blur-sm text-white text-xs font-bold rounded-full shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          {toastMessage}
        </div>
      )}

      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}

      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button 
                onClick={() => setIsDiaryOpen(true)}
                className={`w-full py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${
                  currentDiary 
                    ? 'bg-emerald-50 border-emerald-100 text-emerald-600' 
                    : 'bg-white border-dashed border-gray-200 text-gray-400'
                }`}
              >
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '오늘의 건강 일기 작성'}</span>
              </button>
              <button 
                onClick={handleCopyTextToClipboard}
                className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2"
              >
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const FOOD_EMOJIS = ['🥗', '🍎', '🥑', '🍗', '🍳', '🥛', '🍣', '🍱', '🥣', '🥦', '🍌', '🥪', '🥙', '🥗'];

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [loadingEmoji, setLoadingEmoji] = useState('🥗');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  // Toast handler
  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setLoadingEmoji(FOOD_EMOJIS[Math.floor(Math.random() * FOOD_EMOJIS.length)]);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
        showToast("데이터를 불러오는 중 오류가 발생했습니다.");
      } finally {
        setTimeout(() => setIsLoading(false), 1200);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const prevMeals = [...meals];
    const prevIngredients = [...ingredients];
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    setMeals(prev => isUpdate ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) : [...prev, { ...newMeal, pending: true }]);
    if (newIngredient) setIngredients(prev => [...prev, newIngredient]);
    try {
      if (newIngredient) await saveIngredientToGAS(newIngredient);
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (!success) throw new Error("Server storage failed");
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) {
      setMeals(prevMeals);
      setIngredients(prevIngredients);
      showToast("저장에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, ingredients, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const prevMeals = [...meals];
    const updatedMeal: MealRecord = { ...target, status, time: status === MealStatus.ACTUAL ? getKSTTime() : target.time, pending: true };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (!success) throw new Error("Update failed");
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) {
      setMeals(prevMeals);
      showToast("상태 변경에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const prevMeals = [...meals];
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));
    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else throw new Error("Delete failed");
    } catch (err) {
      setMeals(prevMeals);
      showToast("삭제에 실패했습니다. 다시 시도해 주세요.");
      return false;
    }
  }, [meals, isAdmin]);

  const getIngredientDisplayName = useCallback((meal: MealRecord) => {
    if (meal.ingredient_name) return meal.ingredient_name;
    if (!meal.ingredient_uuid) return '식재료 정보 없음';
    const targetUuid = String(meal.ingredient_uuid).trim();
    const found = ingredients.find(i => String(i.uuid).trim() === targetUuid);
    return found ? found.name : '알 수 없는 식재료';
  }, [ingredients]);

  const handleCopyTextToClipboard = useCallback(() => {
    const actualMealsToCopy = filteredMeals.filter(m => m.status === MealStatus.ACTUAL);
    if (actualMealsToCopy.length === 0) {
      alert("섭취 완료된(ACTUAL) 식단이 없습니다.");
      return;
    }

    const typeOrder = [MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER];
    let text = `[${selectedDate} 식단 기록]\n\n`;

    typeOrder.forEach(type => {
      const typeMeals = actualMealsToCopy
        .filter(m => m.type === type)
        .sort((a, b) => a.time.localeCompare(b.time));

      if (typeMeals.length > 0) {
        text += `[${type}]\n`;
        typeMeals.forEach(m => {
          const name = getIngredientDisplayName(m);
          text += `${m.time} | ${name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
        });
        text += `\n`;
      }
    });

    text += `총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;

    navigator.clipboard.writeText(text).then(() => {
      showToast("식단이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      showToast("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary, getIngredientDisplayName]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const prevDiaries = [...diaries];
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });
    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
      else throw new Error("Diary storage failed");
    } catch (error) { 
      setDiaries(prevDiaries);
      showToast("일기 저장에 실패했습니다.");
    }
  }, [selectedDate, currentDiary, diaries, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const prevIngredients = [...ingredients];
    const next = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));
    try { 
      const success = await updateIngredientBookmark(uuid, next); 
      if (!success) throw new Error("Bookmark failed");
    } catch (err) { 
      setIngredients(prevIngredients); 
      showToast("즐겨찾기 상태 변경에 실패했습니다.");
    }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {isLoading && (
        <div className="fixed inset-0 z-[1000] bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
          <div className="relative mb-8">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center animate-pulse">
              <span className="text-6xl animate-bounce" style={{ display: 'inline-block' }}>{loadingEmoji}</span>
            </div>
            <div className="absolute -inset-2 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          </div>
          <h2 className="text-xl font-black text-gray-800 mb-2">데이터를 불러오는 중입니다...</h2>
          <p className="text-sm text-gray-400 font-medium">잠시만 기다려 주세요 ✨</p>
        </div>
      )}

      {toastMessage && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] px-6 py-3 bg-gray-900/90 backdrop-blur-sm text-white text-xs font-bold rounded-full shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          {toastMessage}
        </div>
      )}

      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}

      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button onClick={() => setIsDiaryOpen(true)} className={`w-full py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${currentDiary ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-white border-dashed border-gray-200 text-gray-400'}`}>
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '오늘의 건강 일기 작성'}</span>
              </button>
              <button onClick={handleCopyTextToClipboard} className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2">
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useMemo, useRef } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  type: MealType;
  meals: MealRecord[];
  ingredients: Ingredient[];
  isAdmin: boolean;
  onAdd: () => void;
  onEdit: (meal: MealRecord) => void;
  onDelete: (uuid: string) => Promise<boolean>;
  onSetStatus: (uuid: string, status: MealStatus) => void;
}

const MealSection: React.FC<Props> = ({ type, meals, ingredients, isAdmin, onAdd, onEdit, onDelete, onSetStatus }) => {
  const getIngredientDisplayName = (meal: MealRecord) => {
    if (meal.ingredient_name) return meal.ingredient_name;
    if (!meal.ingredient_uuid) return '식재료 정보 없음';
    const targetUuid = String(meal.ingredient_uuid).trim();
    const found = ingredients.find(i => String(i.uuid).trim() === targetUuid);
    return found ? found.name : '알 수 없는 식재료';
  };

  const totalProteinActual = useMemo(() => {
    return meals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((sum, meal) => sum + (Number(meal.protein) || 0), 0);
  }, [meals]);

  const totalProteinPlanned = useMemo(() => {
    return meals.reduce((sum, meal) => sum + (Number(meal.protein) || 0), 0);
  }, [meals]);

  // 시간을 기준으로 정렬된 식단 목록
  const sortedMeals = useMemo(() => {
    return [...meals].sort((a, b) => a.time.localeCompare(b.time));
  }, [meals]);

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center px-1">
        <div className="flex items-center space-x-2">
          <h4 className="font-bold text-gray-700 flex items-center">
            <span className={`w-2 h-2 rounded-full mr-2 ${
              type === MealType.BREAKFAST ? 'bg-amber-400' :
              type === MealType.LUNCH ? 'bg-green-400' :
              type === MealType.SNACK ? 'bg-pink-400' : 'bg-indigo-400'
            }`} />
            {type}
          </h4>
          {meals.length > 0 && (
            <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-medium">
              단백질 {Math.round(totalProteinActual)}g <span className="opacity-60">({Math.round(totalProteinPlanned)}g)</span>
            </span>
          )}
        </div>
        <button 
          onClick={onAdd}
          className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded-full text-gray-500 hover:bg-gray-200 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
          </svg>
        </button>
      </div>

      <div className="space-y-2">
        {sortedMeals.length === 0 ? (
          <div className="bg-white/50 border border-dashed border-gray-200 p-4 rounded-xl text-center text-xs text-gray-400 italic">
            기록된 {type}이 없습니다.
          </div>
        ) : (
          sortedMeals.map(meal => (
            <SwipeableMealCard 
              key={meal.uuid} 
              meal={meal} 
              displayName={getIngredientDisplayName(meal)}
              isAdmin={isAdmin}
              onEdit={onEdit}
              onSetStatus={onSetStatus}
            />
          ))
        )}
      </div>
    </div>
  );
};

const SwipeableMealCard: React.FC<{ 
  meal: MealRecord; 
  displayName: string;
  isAdmin: boolean;
  onEdit: (meal: MealRecord) => void;
  onSetStatus: (uuid: string, status: MealStatus) => void;
}> = ({ meal, displayName, isAdmin, onEdit, onSetStatus }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const bgActualRef = useRef<HTMLDivElement>(null);
  const bgPlannedRef = useRef<HTMLDivElement>(null);

  const startX = useRef(0);
  const currentDiff = useRef(0);
  const isDragging = useRef(false);
  const threshold = 80;

  const updateStyles = (diff: number) => {
    if (!cardRef.current) return;
    const dragX = diff * 0.6;
    cardRef.current.style.transform = `translate3d(${dragX}px, 0, 0)`;

    if (bgActualRef.current) {
      const opacity = Math.min(Math.max(dragX / 60, 0), 1);
      bgActualRef.current.style.opacity = opacity.toString();
    }
    if (bgPlannedRef.current) {
      const opacity = Math.min(Math.max(-dragX / 60, 0), 1);
      bgPlannedRef.current.style.opacity = opacity.toString();
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    if (!isAdmin) return;
    if (meal.pending) return;
    startX.current = e.touches[0].clientX;
    isDragging.current = true;
    if (cardRef.current) cardRef.current.style.transition = 'none';
  };

  const onTouchMove = (e: React.TouchEvent) => {
    if (!isAdmin || !isDragging.current) return;
    currentDiff.current = e.touches[0].clientX - startX.current;
    requestAnimationFrame(() => updateStyles(currentDiff.current));
  };

  const onTouchEnd = () => {
    if (!isAdmin || !isDragging.current) return;
    isDragging.current = false;
    const dragX = currentDiff.current * 0.6;

    if (cardRef.current) {
      cardRef.current.style.transition = 'transform 0.4s cubic-bezier(0.25, 1, 0.5, 1)';
      cardRef.current.style.transform = `translate3d(0, 0, 0)`;
    }
    if (bgActualRef.current) bgActualRef.current.style.opacity = '0';
    if (bgPlannedRef.current) bgPlannedRef.current.style.opacity = '0';

    if (dragX > threshold) onSetStatus(meal.uuid, MealStatus.ACTUAL);
    else if (dragX < -threshold) onSetStatus(meal.uuid, MealStatus.PLANNED);
    currentDiff.current = 0;
  };

  const isPlanned = meal.status === MealStatus.PLANNED;
  const isDirectEntry = meal.ingredient_uuid === 'direct-entry';

  return (
    <div className="relative overflow-hidden rounded-xl bg-gray-100 touch-pan-y">
      <div className="absolute inset-0 flex items-center justify-between px-6 z-0 pointer-events-none">
        <div ref={bgActualRef} className="opacity-0 flex items-center space-x-2">
          <div className="w-9 h-9 rounded-full bg-green-500 flex items-center justify-center text-white">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
          </div>
        </div>
        <div ref={bgPlannedRef} className="opacity-0 flex items-center space-x-2">
          <div className="w-9 h-9 rounded-full bg-gray-400 flex items-center justify-center text-white">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><rect x="3" y="3" width="18" height="18" rx="4" strokeWidth="2" /></svg>
          </div>
        </div>
      </div>

      <div 
        ref={cardRef}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        onClick={() => onEdit(meal)}
        className={`relative z-10 flex-1 p-4 rounded-xl shadow-sm flex justify-between items-center border-l-4 transition-all ${
          meal.pending ? 'opacity-50 grayscale border-gray-300 cursor-wait' : 
          isPlanned ? 'bg-gray-50 border-gray-300 border-dashed' : 'bg-white border-indigo-500 hover:border-indigo-600'
        }`}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center space-x-2 overflow-hidden">
            <p className={`font-bold text-sm truncate ${isPlanned ? 'text-gray-400 italic' : 'text-gray-800'}`}>
              {displayName}
            </p>
            {isDirectEntry && (
              <span className="shrink-0 text-[9px] bg-amber-100 text-amber-600 px-1.5 py-0.5 rounded-sm font-black uppercase tracking-tighter">임의입력</span>
            )}
            {isPlanned && (
              <span className="shrink-0 text-[9px] bg-gray-200 text-gray-500 px-1.5 py-0.5 rounded-sm font-black uppercase tracking-tighter">Planned</span>
            )}
          </div>
          <p className="text-xs text-gray-400 font-medium">{meal.amount}g • {meal.time}</p>
        </div>
        <div className="text-right shrink-0 ml-2">
          <p className={`font-black tracking-tight ${isPlanned ? 'text-gray-300' : 'text-indigo-600'}`}>
            {Math.round(meal.kcal)} <span className="text-[9px] font-bold ml-0.5">kcal</span>
          </p>
          <div className="flex items-center space-x-1 text-[9px] text-gray-400 justify-end font-bold">
            <span className={!isPlanned ? 'text-orange-500/80' : ''}>C {Math.round(meal.carbs || 0)}g</span>
            <span className="opacity-30 px-0.5">·</span>
            <span className={!isPlanned ? 'text-emerald-500/80' : ''}>P {Math.round(meal.protein || 0)}g</span>
            <span className="opacity-30 px-0.5">·</span>
            <span className={!isPlanned ? 'text-blue-500/80' : ''}>F {Math.round(meal.fat || 0)}g</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealSection;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const FOOD_EMOJIS = ['🥗', '🍎', '🥑', '🍗', '🍳', '🥛', '🍣', '🍱', '🥣', '🥦', '🍌', '🥪', '🥙', '🥗'];

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [loadingEmoji, setLoadingEmoji] = useState('🥗');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  // Toast handler
  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setLoadingEmoji(FOOD_EMOJIS[Math.floor(Math.random() * FOOD_EMOJIS.length)]);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
        showToast("데이터를 불러오는 중 오류가 발생했습니다.");
      } finally {
        setTimeout(() => setIsLoading(false), 1200);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const prevMeals = [...meals];
    const prevIngredients = [...ingredients];
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    setMeals(prev => isUpdate ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) : [...prev, { ...newMeal, pending: true }]);
    if (newIngredient) setIngredients(prev => [...prev, newIngredient]);
    try {
      if (newIngredient) await saveIngredientToGAS(newIngredient);
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (!success) throw new Error("Server storage failed");
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) {
      setMeals(prevMeals);
      setIngredients(prevIngredients);
      showToast("저장에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, ingredients, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const prevMeals = [...meals];

    // ACTUAL이면 현재 시각, PLANNED이면 23:59로 자동 설정
    const newTime = status === MealStatus.ACTUAL 
      ? getKSTTime() 
      : (status === MealStatus.PLANNED ? '23:59' : target.time);

    const updatedMeal: MealRecord = { ...target, status, time: newTime, pending: true };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (!success) throw new Error("Update failed");
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) {
      setMeals(prevMeals);
      showToast("상태 변경에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const prevMeals = [...meals];
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));
    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else throw new Error("Delete failed");
    } catch (err) {
      setMeals(prevMeals);
      showToast("삭제에 실패했습니다. 다시 시도해 주세요.");
      return false;
    }
  }, [meals, isAdmin]);

  const getIngredientDisplayName = useCallback((meal: MealRecord) => {
    if (meal.ingredient_name) return meal.ingredient_name;
    if (!meal.ingredient_uuid) return '식재료 정보 없음';
    const targetUuid = String(meal.ingredient_uuid).trim();
    const found = ingredients.find(i => String(i.uuid).trim() === targetUuid);
    return found ? found.name : '알 수 없는 식재료';
  }, [ingredients]);

  const handleCopyTextToClipboard = useCallback(() => {
    const actualMealsToCopy = filteredMeals.filter(m => m.status === MealStatus.ACTUAL);
    if (actualMealsToCopy.length === 0) {
      alert("섭취 완료된(ACTUAL) 식단이 없습니다.");
      return;
    }

    const typeOrder = [MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER];
    let text = `[${selectedDate} 식단 기록]\n\n`;

    typeOrder.forEach(type => {
      const typeMeals = actualMealsToCopy
        .filter(m => m.type === type)
        .sort((a, b) => a.time.localeCompare(b.time));

      if (typeMeals.length > 0) {
        text += `[${type}]\n`;
        typeMeals.forEach(m => {
          const name = getIngredientDisplayName(m);
          text += `${m.time} | ${name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
        });
        text += `\n`;
      }
    });

    text += `총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;

    navigator.clipboard.writeText(text).then(() => {
      showToast("식단이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      showToast("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary, getIngredientDisplayName]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const prevDiaries = [...diaries];
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });
    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
      else throw new Error("Diary storage failed");
    } catch (error) { 
      setDiaries(prevDiaries);
      showToast("일기 저장에 실패했습니다.");
    }
  }, [selectedDate, currentDiary, diaries, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const prevIngredients = [...ingredients];
    const next = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));
    try { 
      const success = await updateIngredientBookmark(uuid, next); 
      if (!success) throw new Error("Bookmark failed");
    } catch (err) { 
      setIngredients(prevIngredients); 
      showToast("즐겨찾기 상태 변경에 실패했습니다.");
    }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {isLoading && (
        <div className="fixed inset-0 z-[1000] bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
          <div className="relative mb-8">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center animate-pulse">
              <span className="text-6xl animate-bounce" style={{ display: 'inline-block' }}>{loadingEmoji}</span>
            </div>
            <div className="absolute -inset-2 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          </div>
          <h2 className="text-xl font-black text-gray-800 mb-2">데이터를 불러오는 중입니다...</h2>
          <p className="text-sm text-gray-400 font-medium">잠시만 기다려 주세요 ✨</p>
        </div>
      )}

      {toastMessage && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] px-6 py-3 bg-gray-900/90 backdrop-blur-sm text-white text-xs font-bold rounded-full shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          {toastMessage}
        </div>
      )}

      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}

      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button onClick={() => setIsDiaryOpen(true)} className={`w-full py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${currentDiary ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-white border-dashed border-gray-200 text-gray-400'}`}>
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '오늘의 건강 일기 작성'}</span>
              </button>
              <button onClick={handleCopyTextToClipboard} className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2">
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  meals: MealRecord[];
  isAdmin: boolean;
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => Promise<boolean>;
  trialMessage?: string;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, meals, isAdmin, onSave, onDelete, trialMessage }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const isDirectEntryEdit = editTarget?.ingredient_uuid === 'direct-entry';

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    (editTarget && !isDirectEntryEdit) ? (ingredients.find(i => String(i.uuid) === String(editTarget.ingredient_uuid)) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(isDirectEntryEdit);
  const [newName, setNewName] = useState(editTarget?.ingredient_name || '');
  const [newBase, setNewBase] = useState(editTarget?.amount.toString() || '1');
  const [newKcal, setNewKcal] = useState(editTarget?.kcal.toString() || '');
  const [newCarbs, setNewCarbs] = useState(editTarget?.carbs.toString() || '');
  const [newProtein, setNewProtein] = useState(editTarget?.protein.toString() || '');
  const [newFat, setNewFat] = useState(editTarget?.fat.toString() || '');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  const yesterdayMeals = useMemo(() => {
    if (editTarget) return []; 
    const current = new Date(date);
    current.setDate(current.getDate() - 1);
    const yesterdayStr = current.toISOString().split('T')[0];
    return meals.filter(m => m.date === yesterdayStr && m.type === type && m.status === MealStatus.ACTUAL);
  }, [meals, date, type, editTarget]);

  const handleSelectYesterdayMeal = useCallback((meal: MealRecord) => {
    const isDirect = meal.ingredient_uuid === 'direct-entry';
    const mealAmount = meal.amount.toString();
    if (isDirect) {
      setIsAddingNew(true);
      setNewName(meal.ingredient_name || '');
      setAmount(mealAmount);
      setNewBase(mealAmount); 
      setNewKcal(meal.kcal.toString());
      setNewCarbs(meal.carbs.toString());
      setNewProtein(meal.protein.toString());
      setNewFat(meal.fat.toString());
    } else {
      const ing = ingredients.find(i => String(i.uuid) === String(meal.ingredient_uuid));
      if (ing) {
        setIsAddingNew(false);
        setSelectedIngredient(ing);
        setAmount(mealAmount);
      } else {
        setIsAddingNew(true);
        setNewName(meal.ingredient_name || '복구된 메뉴');
        setAmount(mealAmount);
        setNewBase(mealAmount);
        setNewKcal(meal.kcal.toString());
        setNewCarbs(meal.carbs.toString());
        setNewProtein(meal.protein.toString());
        setNewFat(meal.fat.toString());
      }
    }
  }, [ingredients]);

  const searchResults = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return ingredients.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).slice(0, 20);
  }, [ingredients, searchTerm]);

  const bookmarks = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 10);
  }, [ingredients]);

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    if (isAddingNew) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated >= 0) setNewKcal(calculated.toFixed(1));
    }
  }, [newCarbs, newProtein, newFat, isAddingNew]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const currentAmount = parseFloat(amount) || 0;
      const currentBase = parseFloat(newBase) || 1;
      const factor = currentBase === 0 ? 0 : currentAmount / currentBase;
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = ing.base_amount === 0 ? 0 : parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (finalStatus: MealStatus) => {
    if (!isAdmin) {
      alert(trialMessage);
      return;
    }
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = isAddingNew ? (newName || '직접 입력 식단') : (selectedIngredient?.name || '식재료 정보 없음');
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    // PLANNED 상태로 저장 시 시각을 23:59로 고정
    const finalTime = finalStatus === MealStatus.PLANNED ? '23:59' : time;

    onSave({
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status: finalStatus,
      date,
      time: finalTime,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      kcal: preview.kcal,
      carbs: preview.carbs,
      protein: preview.protein,
      fat: preview.fat,
      sugar: 0,
      fiber: 0
    }, newIngData);
    onClose();
  };

  const confirmDelete = async () => {
    if (!isAdmin) {
      alert(trialMessage);
      return;
    }
    if (editTarget && onDelete) {
      setIsDeleting(true);
      setShowDeleteConfirm(false); 
      try {
        const success = await onDelete(editTarget.uuid);
        if (success) onClose();
        else setIsDeleting(false);
      } catch (err) {
        setIsDeleting(false);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4" onClick={onClose}>
      <div className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 relative" onClick={e => e.stopPropagation()}>

        {showDeleteConfirm && (
          <div className="absolute inset-0 z-[130] bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in duration-200">
            <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center text-red-500 mb-6">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </div>
            <h3 className="text-2xl font-black text-gray-900 mb-2">정말 삭제할까요?</h3>
            <p className="text-gray-500 font-medium mb-8">기록된 영양 데이터가 통계에서 제외됩니다.</p>
            <div className="flex flex-col w-full space-y-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-500 text-white font-black rounded-2xl shadow-lg active:scale-95 transition-all">네, 삭제할게요</button>
              <button onClick={() => setShowDeleteConfirm(false)} className="w-full py-4 bg-gray-100 text-gray-500 font-bold rounded-2xl active:scale-95 transition-all">아니오, 유지할게요</button>
            </div>
          </div>
        )}

        {isDeleting && (
          <div className="absolute inset-0 z-[140] bg-white/60 backdrop-blur-[1px] flex flex-col items-center justify-center animate-in fade-in">
            <div className="w-10 h-10 border-4 border-red-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="mt-4 text-xs font-bold text-red-500">삭제하는 중...</p>
          </div>
        )}

        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-6 pb-3 space-y-4 overflow-y-auto min-h-[300px]">
          <div className="space-y-4 p-4 bg-gray-50 rounded-3xl">
            <div className="flex bg-gray-200/50 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map((mType) => (
                <button
                  key={mType}
                  onClick={() => setType(mType)}
                  className={`flex-1 py-2.5 text-xs rounded-xl transition-all font-black ${
                    type === mType ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'
                  }`}
                >
                  {mType}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="relative">
                <label className="absolute left-3 top-1 text-[8px] font-black text-gray-400 uppercase">날짜</label>
                <input 
                  type="date" 
                  value={date} 
                  onChange={e => setDate(e.target.value)} 
                  className="w-full pt-4 pb-2 px-3 rounded-xl border-none ring-1 ring-gray-200 bg-white text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                />
              </div>
              <div className="relative">
                <label className="absolute left-3 top-1 text-[8px] font-black text-gray-400 uppercase">시간</label>
                <input 
                  type="time" 
                  value={time} 
                  onChange={e => setTime(e.target.value)} 
                  className="w-full pt-4 pb-2 px-3 rounded-xl border-none ring-1 ring-gray-200 bg-white text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                />
              </div>
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-6 animate-in fade-in">
              <div className="relative">
                <input 
                  autoFocus 
                  type="text" 
                  placeholder="식재료 검색..." 
                  value={searchTerm} 
                  onChange={e => setSearchTerm(e.target.value)} 
                  className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white font-medium" 
                />
                <button onClick={() => setIsAddingNew(true)} className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-indigo-600 underline">직접 입력</button>
              </div>

              {searchTerm.trim() === '' ? (
                <div className="space-y-5">
                  {yesterdayMeals.length > 0 && (
                    <div className="space-y-3 animate-in slide-in-from-top-2">
                      <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-1 flex items-center">
                        <span className="mr-1">🕒</span> 어제 먹은 {type} 메뉴 ({yesterdayMeals.length})
                      </h3>
                      <div className="space-y-2">
                        {yesterdayMeals.map((meal) => (
                          <button 
                            key={meal.uuid}
                            onClick={() => handleSelectYesterdayMeal(meal)}
                            className="w-full p-4 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-50 flex justify-between items-center active:scale-[0.98] transition-all group border-b-2 border-indigo-700"
                          >
                            <div className="text-left flex-1 truncate mr-2">
                              <p className="text-[10px] font-black opacity-70 mb-0.5">그대로 가져오기</p>
                              <p className="text-sm font-bold truncate">{meal.ingredient_name || '식재료'} / {meal.amount}g</p>
                            </div>
                            <div className="bg-white/20 p-2 rounded-full group-hover:bg-white/30 transition-colors">
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                                <path d="M7 9a2 2 0 012-2h6a2 2 0 012 2v6a2 2 0 01-2 2H9a2 2 0 01-2-2V9z" />
                                <path d="M5 5a2 2 0 012-2h6a2 2 0 012 2v2H7a2 2 0 00-2 2v6H5a2 2 0 01-2-2V7a2 2 0 012-2z" />
                              </svg>
                            </div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}

                  <div className="space-y-3">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">자주 찾는 식재료</h3>
                    <div className="grid grid-cols-2 gap-2">
                      {bookmarks.length > 0 ? bookmarks.map(i => (
                        <button key={i.uuid} onClick={() => setSelectedIngredient(i)} className="p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-left hover:bg-indigo-100 transition-colors flex items-center space-x-2">
                          <span className="text-amber-500 text-xs">⭐</span>
                          <p className="text-xs font-bold text-indigo-900 truncate">{i.name}</p>
                        </button>
                      )) : (
                        <p className="col-span-2 text-center py-4 text-xs text-gray-300 italic">즐겨찾기한 식재료가 없습니다.</p>
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="space-y-3">
                  <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-1">검색 결과</h3>
                  <div className="space-y-2 max-h-[250px] overflow-y-auto pr-1 custom-scrollbar">
                    {searchResults.length > 0 ? searchResults.map(i => (
                      <button key={i.uuid} onClick={() => setSelectedIngredient(i)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl flex justify-between items-center shadow-sm hover:border-indigo-300 transition-colors">
                        <div>
                          <p className="text-sm font-bold text-gray-800">{i.name}</p>
                          <p className="text-[10px] text-gray-400">{i.base_amount}g 기준 {i.kcal}kcal</p>
                        </div>
                        <div className="text-right">
                          <p className="text-[10px] font-bold text-indigo-600">P {i.protein}g</p>
                        </div>
                      </button>
                    )) : (
                      <div className="text-center py-10 bg-gray-50 rounded-2xl">
                        <p className="text-xs text-gray-400 mb-3">검색 결과가 없습니다.</p>
                        <button onClick={() => { setIsAddingNew(true); setNewName(searchTerm); }} className="text-xs font-black text-indigo-600 underline">'{searchTerm}' 직접 등록하기</button>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          ) : isAddingNew ? (
            <div className="space-y-4 animate-in fade-in duration-300">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식단 이름</label>
                <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름 (예: 엄마표 볶음밥)" className="w-full p-4 rounded-2xl border bg-white focus:ring-2 focus:ring-indigo-500 outline-none font-bold" />
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">탄(g)</label>
                  <input type="number" placeholder="0" value={newCarbs} onChange={e => setNewCarbs(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">단(g)</label>
                  <input type="number" placeholder="0" value={newProtein} onChange={e => setNewProtein(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">지(g)</label>
                  <input type="number" placeholder="0" value={newFat} onChange={e => setNewFat(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
              </div>
              <div className="pt-2 border-t border-indigo-100">
                <div className="flex justify-between items-end mb-1 px-1">
                  <label className="text-[10px] font-black text-indigo-600 uppercase">현재 섭취량 (g)</label>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-[10px] font-bold text-gray-400">
                      C {Math.round(preview?.carbs || 0)}g · P {Math.round(preview?.protein || 0)}g · F {Math.round(preview?.fat || 0)}g
                    </span>
                    <span className="text-sm font-black text-indigo-600">{Math.round(preview?.kcal || 0)} kcal</span>
                  </div>
                </div>
                <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-4 rounded-2xl border-2 border-indigo-500 text-3xl font-black text-center bg-white outline-none" />
              </div>
              {!editTarget && (
                <div className="flex items-center space-x-2 pt-2">
                  <input type="checkbox" id="saveToIng" checked={shouldSaveToIngredients} onChange={e => setShouldSaveToIngredients(e.target.checked)} className="w-4 h-4 text-indigo-600 rounded" />
                  <label htmlFor="saveToIng" className="text-xs font-bold text-gray-500">이 식단 정보를 식재료 목록에도 저장할게요</label>
                </div>
              )}
              {isAddingNew && !isDirectEntryEdit && (
                <button onClick={() => { setIsAddingNew(false); setSelectedIngredient(null); setSearchTerm(''); }} className="w-full py-2 text-xs font-bold text-gray-400 hover:text-indigo-500 underline transition-colors">식재료 검색으로 돌아가기</button>
              )}
            </div>
          ) : (
            <div className="bg-indigo-50/50 p-5 pb-4 rounded-[40px] space-y-4 animate-in slide-in-from-right-4">
              <div className="flex justify-between items-start">
                <h3 className="font-black text-indigo-600 text-2xl truncate mr-4">{selectedIngredient?.name}</h3>
                {!editTarget && <button onClick={() => setSelectedIngredient(null)} className="text-xs text-indigo-400 font-bold underline shrink-0">변경</button>}
              </div>
              <div className="space-y-2">
                <div className="flex justify-between items-end px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">양 (g)</label>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-[9px] font-bold text-indigo-400">
                      C {Math.round(preview?.carbs || 0)}g · P {Math.round(preview?.protein || 0)}g · F {Math.round(preview?.fat || 0)}g
                    </span>
                    <span className="text-sm font-black text-indigo-600">{Math.round(preview?.kcal || 0)} kcal</span>
                  </div>
                </div>
                <input autoFocus type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-4 bg-white rounded-3xl ring-2 ring-indigo-500 text-3xl font-black text-center outline-none" />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 pt-3 border-t bg-gray-50 flex flex-col space-y-3">
          <div className="flex space-x-2">
            {editTarget && (
              <button 
                onClick={() => isAdmin ? setShowDeleteConfirm(true) : alert(trialMessage)} 
                disabled={isDeleting} 
                className="px-4 py-4 bg-red-50 text-red-500 font-black rounded-2xl border border-red-100 transition-all text-xs hover:bg-red-100 active:scale-95 disabled:opacity-30"
              >
                삭제
              </button>
            )}
            <button 
              disabled={!preview || isDeleting} 
              onClick={() => handleSave(MealStatus.PLANNED)} 
              className="flex-1 py-4 bg-white text-gray-500 border border-gray-200 font-black rounded-2xl active:scale-95 disabled:opacity-30 transition-all text-sm"
            >
              예정으로 저장
            </button>
            <button 
              disabled={!preview || isDeleting} 
              onClick={() => handleSave(MealStatus.ACTUAL)} 
              className="flex-[1.5] py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl active:scale-95 disabled:opacity-30 transition-all text-sm"
            >
              {editTarget ? '수정 완료' : '식단 저장'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealInputForm;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string;
  prefilledType: MealType | null;
  editTarget?: MealRecord | null;
  ingredients: Ingredient[];
  meals: MealRecord[];
  isAdmin: boolean;
  onSave: (meal: MealRecord, ingredient?: Ingredient) => void;
  onDelete?: (uuid: string) => Promise<boolean>;
  trialMessage?: string;
}

const MealInputForm: React.FC<Props> = ({ isOpen, onClose, selectedDate, prefilledType, editTarget, ingredients, meals, isAdmin, onSave, onDelete, trialMessage }) => {
  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const isDirectEntryEdit = editTarget?.ingredient_uuid === 'direct-entry';

  const [date, setDate] = useState(editTarget?.date || selectedDate);
  const [time, setTime] = useState(editTarget?.time || getKSTTime());
  const [type, setType] = useState<MealType>(editTarget?.type || prefilledType || MealType.BREAKFAST);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | null>(
    (editTarget && !isDirectEntryEdit) ? (ingredients.find(i => String(i.uuid) === String(editTarget.ingredient_uuid)) || null) : null
  );
  const [amount, setAmount] = useState(editTarget?.amount.toString() || '1');

  const [isAddingNew, setIsAddingNew] = useState(isDirectEntryEdit);
  const [newName, setNewName] = useState(editTarget?.ingredient_name || '');
  const [newBase, setNewBase] = useState(editTarget?.amount.toString() || '1');
  const [newKcal, setNewKcal] = useState(editTarget?.kcal.toString() || '');
  const [newCarbs, setNewCarbs] = useState(editTarget?.carbs.toString() || '');
  const [newProtein, setNewProtein] = useState(editTarget?.protein.toString() || '');
  const [newFat, setNewFat] = useState(editTarget?.fat.toString() || '');
  const [shouldSaveToIngredients, setShouldSaveToIngredients] = useState(false);

  const yesterdayMeals = useMemo(() => {
    if (editTarget) return []; 
    const current = new Date(date);
    current.setDate(current.getDate() - 1);
    const yesterdayStr = current.toISOString().split('T')[0];
    return meals.filter(m => m.date === yesterdayStr && m.type === type && m.status === MealStatus.ACTUAL);
  }, [meals, date, type, editTarget]);

  const handleSelectYesterdayMeal = useCallback((meal: MealRecord) => {
    const isDirect = meal.ingredient_uuid === 'direct-entry';
    const mealAmount = meal.amount.toString();
    if (isDirect) {
      setIsAddingNew(true);
      setNewName(meal.ingredient_name || '');
      setAmount(mealAmount);
      setNewBase(mealAmount); 
      setNewKcal(meal.kcal.toString());
      setNewCarbs(meal.carbs.toString());
      setNewProtein(meal.protein.toString());
      setNewFat(meal.fat.toString());
    } else {
      const ing = ingredients.find(i => String(i.uuid) === String(meal.ingredient_uuid));
      if (ing) {
        setIsAddingNew(false);
        setSelectedIngredient(ing);
        setAmount(mealAmount);
      } else {
        setIsAddingNew(true);
        setNewName(meal.ingredient_name || '복구된 메뉴');
        setAmount(mealAmount);
        setNewBase(mealAmount);
        setNewKcal(meal.kcal.toString());
        setNewCarbs(meal.carbs.toString());
        setNewProtein(meal.protein.toString());
        setNewFat(meal.fat.toString());
      }
    }
  }, [ingredients]);

  const searchResults = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return ingredients.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).slice(0, 20);
  }, [ingredients, searchTerm]);

  const bookmarks = useMemo(() => {
    return ingredients.filter(i => i.is_bookmarked).slice(0, 10);
  }, [ingredients]);

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    if (isAddingNew) {
      const c = parseFloat(newCarbs) || 0;
      const p = parseFloat(newProtein) || 0;
      const f = parseFloat(newFat) || 0;
      const calculated = (c * 4) + (p * 4) + (f * 9);
      if (calculated >= 0) setNewKcal(calculated.toFixed(1));
    }
  }, [newCarbs, newProtein, newFat, isAddingNew]);

  const preview = useMemo(() => {
    if (isAddingNew) {
      const currentAmount = parseFloat(amount) || 0;
      const currentBase = parseFloat(newBase) || 1;
      const factor = currentBase === 0 ? 0 : currentAmount / currentBase;
      return {
        kcal: (parseFloat(newKcal) || 0) * factor,
        carbs: (parseFloat(newCarbs) || 0) * factor,
        protein: (parseFloat(newProtein) || 0) * factor,
        fat: (parseFloat(newFat) || 0) * factor,
      };
    }
    const ing = selectedIngredient;
    if (!ing || !amount) return null;
    const factor = ing.base_amount === 0 ? 0 : parseFloat(amount) / ing.base_amount;
    return {
      kcal: ing.kcal * factor,
      carbs: (ing.carbs || 0) * factor,
      protein: (ing.protein || 0) * factor,
      fat: (ing.fat || 0) * factor,
    };
  }, [selectedIngredient, amount, isAddingNew, newBase, newKcal, newCarbs, newProtein, newFat]);

  const handleSave = (finalStatus: MealStatus) => {
    if (!isAdmin) {
      alert(trialMessage);
      return;
    }
    let finalIngredientUuid = selectedIngredient?.uuid || 'direct-entry';
    let finalIngredientName = isAddingNew ? (newName || '직접 입력 식단') : (selectedIngredient?.name || '식재료 정보 없음');
    let newIngData: Ingredient | undefined;

    if (isAddingNew && shouldSaveToIngredients) {
      newIngData = {
        uuid: crypto.randomUUID(),
        name: finalIngredientName,
        base_amount: parseFloat(newBase) || 1,
        kcal: parseFloat(newKcal) || 0,
        carbs: parseFloat(newCarbs || '0'),
        protein: parseFloat(newProtein || '0'),
        fat: parseFloat(newFat || '0'),
        sugar: 0,
        fiber: 0,
        is_bookmarked: false
      };
      finalIngredientUuid = newIngData.uuid;
    }

    if (!preview) return;

    // 시간 로직 수정
    let finalTime = time;
    if (finalStatus === MealStatus.PLANNED) {
      // 예정(PLANNED)으로 저장 시 항상 23:59
      finalTime = '23:59';
    } else if (finalStatus === MealStatus.ACTUAL && editTarget?.status === MealStatus.PLANNED) {
      // 기존 PLANNED 식단을 ACTUAL로 전환하여 저장 시 현재 한국 시각 적용
      finalTime = getKSTTime();
    }

    onSave({
      uuid: editTarget?.uuid || crypto.randomUUID(),
      type,
      status: finalStatus,
      date,
      time: finalTime,
      ingredient_name: finalIngredientName,
      ingredient_uuid: finalIngredientUuid,
      amount: parseFloat(amount),
      kcal: preview.kcal,
      carbs: preview.carbs,
      protein: preview.protein,
      fat: preview.fat,
      sugar: 0,
      fiber: 0
    }, newIngData);
    onClose();
  };

  const confirmDelete = async () => {
    if (!isAdmin) {
      alert(trialMessage);
      return;
    }
    if (editTarget && onDelete) {
      setIsDeleting(true);
      setShowDeleteConfirm(false); 
      try {
        const success = await onDelete(editTarget.uuid);
        if (success) onClose();
        else setIsDeleting(false);
      } catch (err) {
        setIsDeleting(false);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4" onClick={onClose}>
      <div className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-3xl shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in slide-in-from-bottom-10 relative" onClick={e => e.stopPropagation()}>

        {showDeleteConfirm && (
          <div className="absolute inset-0 z-[130] bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in duration-200">
            <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center text-red-500 mb-6">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </div>
            <h3 className="text-2xl font-black text-gray-900 mb-2">정말 삭제할까요?</h3>
            <p className="text-gray-500 font-medium mb-8">기록된 영양 데이터가 통계에서 제외됩니다.</p>
            <div className="flex flex-col w-full space-y-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-500 text-white font-black rounded-2xl shadow-lg active:scale-95 transition-all">네, 삭제할게요</button>
              <button onClick={() => setShowDeleteConfirm(false)} className="w-full py-4 bg-gray-100 text-gray-500 font-bold rounded-2xl active:scale-95 transition-all">아니오, 유지할게요</button>
            </div>
          </div>
        )}

        {isDeleting && (
          <div className="absolute inset-0 z-[140] bg-white/60 backdrop-blur-[1px] flex flex-col items-center justify-center animate-in fade-in">
            <div className="w-10 h-10 border-4 border-red-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="mt-4 text-xs font-bold text-red-500">삭제하는 중...</p>
          </div>
        )}

        <div className="p-6 border-b flex justify-between items-center bg-white">
          <h2 className="text-xl font-black">{editTarget ? '기록 수정' : '식단 입력'}</h2>
          <button onClick={onClose} className="bg-gray-100 p-2 rounded-full text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-6 pb-3 space-y-4 overflow-y-auto min-h-[300px]">
          <div className="space-y-4 p-4 bg-gray-50 rounded-3xl">
            <div className="flex bg-gray-200/50 p-1 rounded-2xl">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map((mType) => (
                <button
                  key={mType}
                  onClick={() => setType(mType)}
                  className={`flex-1 py-2.5 text-xs rounded-xl transition-all font-black ${
                    type === mType ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'
                  }`}
                >
                  {mType}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="relative">
                <label className="absolute left-3 top-1 text-[8px] font-black text-gray-400 uppercase">날짜</label>
                <input 
                  type="date" 
                  value={date} 
                  onChange={e => setDate(e.target.value)} 
                  className="w-full pt-4 pb-2 px-3 rounded-xl border-none ring-1 ring-gray-200 bg-white text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                />
              </div>
              <div className="relative">
                <label className="absolute left-3 top-1 text-[8px] font-black text-gray-400 uppercase">시간</label>
                <input 
                  type="time" 
                  value={time} 
                  onChange={e => setTime(e.target.value)} 
                  className="w-full pt-4 pb-2 px-3 rounded-xl border-none ring-1 ring-gray-200 bg-white text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                />
              </div>
            </div>
          </div>

          {!isAddingNew && !selectedIngredient ? (
            <div className="space-y-6 animate-in fade-in">
              <div className="relative">
                <input 
                  autoFocus 
                  type="text" 
                  placeholder="식재료 검색..." 
                  value={searchTerm} 
                  onChange={e => setSearchTerm(e.target.value)} 
                  className="w-full p-4 rounded-2xl ring-1 ring-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none bg-white font-medium" 
                />
                <button onClick={() => setIsAddingNew(true)} className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-indigo-600 underline">직접 입력</button>
              </div>

              {searchTerm.trim() === '' ? (
                <div className="space-y-5">
                  {yesterdayMeals.length > 0 && (
                    <div className="space-y-3 animate-in slide-in-from-top-2">
                      <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-1 flex items-center">
                        <span className="mr-1">🕒</span> 어제 먹은 {type} 메뉴 ({yesterdayMeals.length})
                      </h3>
                      <div className="space-y-2">
                        {yesterdayMeals.map((meal) => (
                          <button 
                            key={meal.uuid}
                            onClick={() => handleSelectYesterdayMeal(meal)}
                            className="w-full p-4 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-50 flex justify-between items-center active:scale-[0.98] transition-all group border-b-2 border-indigo-700"
                          >
                            <div className="text-left flex-1 truncate mr-2">
                              <p className="text-[10px] font-black opacity-70 mb-0.5">그대로 가져오기</p>
                              <p className="text-sm font-bold truncate">{meal.ingredient_name || '식재료'} / {meal.amount}g</p>
                            </div>
                            <div className="bg-white/20 p-2 rounded-full group-hover:bg-white/30 transition-colors">
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                                <path d="M7 9a2 2 0 012-2h6a2 2 0 012 2v6a2 2 0 01-2 2H9a2 2 0 01-2-2V9z" />
                                <path d="M5 5a2 2 0 012-2h6a2 2 0 012 2v2H7a2 2 0 00-2 2v6H5a2 2 0 01-2-2V7a2 2 0 012-2z" />
                              </svg>
                            </div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}

                  <div className="space-y-3">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">자주 찾는 식재료</h3>
                    <div className="grid grid-cols-2 gap-2">
                      {bookmarks.length > 0 ? bookmarks.map(i => (
                        <button key={i.uuid} onClick={() => setSelectedIngredient(i)} className="p-3 bg-indigo-50 border border-indigo-100 rounded-xl text-left hover:bg-indigo-100 transition-colors flex items-center space-x-2">
                          <span className="text-amber-500 text-xs">⭐</span>
                          <p className="text-xs font-bold text-indigo-900 truncate">{i.name}</p>
                        </button>
                      )) : (
                        <p className="col-span-2 text-center py-4 text-xs text-gray-300 italic">즐겨찾기한 식재료가 없습니다.</p>
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="space-y-3">
                  <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-1">검색 결과</h3>
                  <div className="space-y-2 max-h-[250px] overflow-y-auto pr-1 custom-scrollbar">
                    {searchResults.length > 0 ? searchResults.map(i => (
                      <button key={i.uuid} onClick={() => setSelectedIngredient(i)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl flex justify-between items-center shadow-sm hover:border-indigo-300 transition-colors">
                        <div>
                          <p className="text-sm font-bold text-gray-800">{i.name}</p>
                          <p className="text-[10px] text-gray-400">{i.base_amount}g 기준 {i.kcal}kcal</p>
                        </div>
                        <div className="text-right">
                          <p className="text-[10px] font-bold text-indigo-600">P {i.protein}g</p>
                        </div>
                      </button>
                    )) : (
                      <div className="text-center py-10 bg-gray-50 rounded-2xl">
                        <p className="text-xs text-gray-400 mb-3">검색 결과가 없습니다.</p>
                        <button onClick={() => { setIsAddingNew(true); setNewName(searchTerm); }} className="text-xs font-black text-indigo-600 underline">'{searchTerm}' 직접 등록하기</button>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          ) : isAddingNew ? (
            <div className="space-y-4 animate-in fade-in duration-300">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-1">식단 이름</label>
                <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="이름 (예: 엄마표 볶음밥)" className="w-full p-4 rounded-2xl border bg-white focus:ring-2 focus:ring-indigo-500 outline-none font-bold" />
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">탄(g)</label>
                  <input type="number" placeholder="0" value={newCarbs} onChange={e => setNewCarbs(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">단(g)</label>
                  <input type="number" placeholder="0" value={newProtein} onChange={e => setNewProtein(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase text-center block">지(g)</label>
                  <input type="number" placeholder="0" value={newFat} onChange={e => setNewFat(e.target.value)} className="w-full p-3 rounded-xl border text-center font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
              </div>
              <div className="pt-2 border-t border-indigo-100">
                <div className="flex justify-between items-end mb-1 px-1">
                  <label className="text-[10px] font-black text-indigo-600 uppercase">현재 섭취량 (g)</label>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-[10px] font-bold text-gray-400">
                      C {Math.round(preview?.carbs || 0)}g · P {Math.round(preview?.protein || 0)}g · F {Math.round(preview?.fat || 0)}g
                    </span>
                    <span className="text-sm font-black text-indigo-600">{Math.round(preview?.kcal || 0)} kcal</span>
                  </div>
                </div>
                <input type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-4 rounded-2xl border-2 border-indigo-500 text-3xl font-black text-center bg-white outline-none" />
              </div>
              {!editTarget && (
                <div className="flex items-center space-x-2 pt-2">
                  <input type="checkbox" id="saveToIng" checked={shouldSaveToIngredients} onChange={e => setShouldSaveToIngredients(e.target.checked)} className="w-4 h-4 text-indigo-600 rounded" />
                  <label htmlFor="saveToIng" className="text-xs font-bold text-gray-500">이 식단 정보를 식재료 목록에도 저장할게요</label>
                </div>
              )}
              {isAddingNew && !isDirectEntryEdit && (
                <button onClick={() => { setIsAddingNew(false); setSelectedIngredient(null); setSearchTerm(''); }} className="w-full py-2 text-xs font-bold text-gray-400 hover:text-indigo-500 underline transition-colors">식재료 검색으로 돌아가기</button>
              )}
            </div>
          ) : (
            <div className="bg-indigo-50/50 p-5 pb-4 rounded-[40px] space-y-4 animate-in slide-in-from-right-4">
              <div className="flex justify-between items-start">
                <h3 className="font-black text-indigo-600 text-2xl truncate mr-4">{selectedIngredient?.name}</h3>
                {!editTarget && <button onClick={() => setSelectedIngredient(null)} className="text-xs text-indigo-400 font-bold underline shrink-0">변경</button>}
              </div>
              <div className="space-y-2">
                <div className="flex justify-between items-end px-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase">양 (g)</label>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-[9px] font-bold text-indigo-400">
                      C {Math.round(preview?.carbs || 0)}g · P {Math.round(preview?.protein || 0)}g · F {Math.round(preview?.fat || 0)}g
                    </span>
                    <span className="text-sm font-black text-indigo-600">{Math.round(preview?.kcal || 0)} kcal</span>
                  </div>
                </div>
                <input autoFocus type="number" step="0.1" value={amount} onChange={e => setAmount(e.target.value)} className="w-full p-4 bg-white rounded-3xl ring-2 ring-indigo-500 text-3xl font-black text-center outline-none" />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 pt-3 border-t bg-gray-50 flex flex-col space-y-3">
          <div className="flex space-x-2">
            {editTarget && (
              <button 
                onClick={() => isAdmin ? setShowDeleteConfirm(true) : alert(trialMessage)} 
                disabled={isDeleting} 
                className="px-4 py-4 bg-red-50 text-red-500 font-black rounded-2xl border border-red-100 transition-all text-xs hover:bg-red-100 active:scale-95 disabled:opacity-30"
              >
                삭제
              </button>
            )}
            <button 
              disabled={!preview || isDeleting} 
              onClick={() => handleSave(MealStatus.PLANNED)} 
              className="flex-1 py-4 bg-white text-gray-500 border border-gray-200 font-black rounded-2xl active:scale-95 disabled:opacity-30 transition-all text-sm"
            >
              예정으로 저장
            </button>
            <button 
              disabled={!preview || isDeleting} 
              onClick={() => handleSave(MealStatus.ACTUAL)} 
              className="flex-[1.5] py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl active:scale-95 disabled:opacity-30 transition-all text-sm"
            >
              {editTarget ? '수정 완료' : '식단 저장'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealInputForm;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus, HealthDiary } from './types';
import Calendar from './components/Calendar';
import DailySummaryView from './components/DailySummary';
import MealSection from './components/MealSection';
import MealInputForm from './components/MealInputForm';
import AIAdviceModal from './components/AIAdviceModal';
import Sidebar from './components/Sidebar';
import IngredientManagement from './components/IngredientManagement';
import Statistics from './components/Statistics';
import ExitModal from './components/ExitModal';
import AdminLoginModal from './components/AdminLoginModal';
import DiaryModal from './components/DiaryModal';
import { 
  fetchInitialData, 
  saveMealToGAS, 
  updateMealInGAS, 
  saveIngredientToGAS, 
  updateIngredientInGAS,
  deleteIngredientFromGAS,
  updateIngredientBookmark,
  saveDiaryToGAS
} from './services/gasService';

const TRIAL_MESSAGE = "체험 모드 안내\n이 버전은 공개용 포트폴리오 버전입니다. 데이터의 보안과 무결성을 위해 기록 수정 기능이 제한되어 있습니다.";

const FOOD_EMOJIS = ['🥗', '🍎', '🥑', '🍗', '🍳', '🥛', '🍣', '🍱', '🥣', '🥦', '🍌', '🥪', '🥙', '🥗'];

const App: React.FC = () => {
  const getKSTDate = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[0];
  };

  const getKSTTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().split('T')[1].slice(0, 5);
  };

  const getKSTFullTime = () => {
    const now = new Date();
    const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
    return kst.toISOString().replace('T', ' ').slice(0, 19);
  };

  const [isAdmin, setIsAdmin] = useState<boolean>(() => localStorage.getItem('isAdmin') === 'true');
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [currentView, setCurrentView] = useState<'main' | 'ingredients' | 'stats'>('main');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(getKSTDate());

  const [meals, setMeals] = useState<MealRecord[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [diaries, setDiaries] = useState<HealthDiary[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [loadingEmoji, setLoadingEmoji] = useState('🥗');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const [isInputOpen, setIsInputOpen] = useState(false);
  const [isDiaryOpen, setIsDiaryOpen] = useState(false);
  const [editMealTarget, setEditMealTarget] = useState<MealRecord | null>(null);
  const [prefilledType, setPrefilledType] = useState<MealType | null>(null);
  const [adviceModalOpen, setAdviceModalOpen] = useState(false);
  const [isExitModalOpen, setIsExitModalOpen] = useState(false);

  // Toast handler
  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  useEffect(() => {
    window.history.pushState({ noBackExitsApp: true }, '');
    const handlePopState = (event: PopStateEvent) => {
      if (isSidebarOpen) { setIsSidebarOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isInputOpen) { setIsInputOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isDiaryOpen) { setIsDiaryOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (adviceModalOpen) { setAdviceModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      if (isAdminLoginOpen) { setIsAdminLoginOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); return; }
      setIsExitModalOpen(true);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, [isSidebarOpen, isInputOpen, isDiaryOpen, adviceModalOpen, isAdminLoginOpen]);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setLoadingEmoji(FOOD_EMOJIS[Math.floor(Math.random() * FOOD_EMOJIS.length)]);
      try {
        const data = await fetchInitialData();
        setMeals(data.meals || []);
        setIngredients(data.ingredients || []);
        setDiaries(data.diaries || []);
      } catch (error) {
        console.error("Failed to load data", error);
        showToast("데이터를 불러오는 중 오류가 발생했습니다.");
      } finally {
        setTimeout(() => setIsLoading(false), 1200);
      }
    };
    loadData();
  }, []);

  const filteredMeals = useMemo(() => meals.filter(m => String(m.date).startsWith(selectedDate) && m.status !== MealStatus.CANCELED), [meals, selectedDate]);
  const currentDiary = useMemo(() => diaries.find(d => d.date === selectedDate), [diaries, selectedDate]);

  const summary = useMemo(() => {
    const initial = { kcal: 0, carbs: 0, protein: 0, fat: 0 };
    const actual = filteredMeals.filter(m => m.status === MealStatus.ACTUAL).reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    const total = filteredMeals.reduce((acc, cur) => ({
      kcal: acc.kcal + (Number(cur.kcal) || 0),
      carbs: acc.carbs + (Number(cur.carbs) || 0),
      protein: acc.protein + (Number(cur.protein) || 0),
      fat: acc.fat + (Number(cur.fat) || 0),
    }), { ...initial });
    return { actual, planned: total };
  }, [filteredMeals]);

  const onSaveMeal = useCallback(async (newMeal: MealRecord, newIngredient?: Ingredient) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const prevMeals = [...meals];
    const prevIngredients = [...ingredients];
    const isUpdate = meals.some(m => String(m.uuid) === String(newMeal.uuid));
    setMeals(prev => isUpdate ? prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...newMeal, pending: true } : m) : [...prev, { ...newMeal, pending: true }]);
    if (newIngredient) setIngredients(prev => [...prev, newIngredient]);
    try {
      if (newIngredient) await saveIngredientToGAS(newIngredient);
      const success = isUpdate ? await updateMealInGAS(newMeal) : await saveMealToGAS(newMeal);
      if (!success) throw new Error("Server storage failed");
      setMeals(prev => prev.map(m => String(m.uuid) === String(newMeal.uuid) ? { ...m, pending: false } : m));
    } catch (error) {
      setMeals(prevMeals);
      setIngredients(prevIngredients);
      showToast("저장에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, ingredients, isAdmin]);

  const handleSetMealStatus = useCallback(async (uuid: string, status: MealStatus) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target || target.status === status) return;
    const prevMeals = [...meals];

    // ACTUAL이면 현재 시각, PLANNED이면 23:59로 자동 설정
    const newTime = status === MealStatus.ACTUAL 
      ? getKSTTime() 
      : (status === MealStatus.PLANNED ? '23:59' : target.time);

    const updatedMeal: MealRecord = { ...target, status, time: newTime, pending: true };
    setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? updatedMeal : m));
    try {
      const success = await updateMealInGAS(updatedMeal);
      if (!success) throw new Error("Update failed");
      setMeals(prev => prev.map(m => String(m.uuid) === String(uuid) ? { ...updatedMeal, pending: false } : m));
    } catch (err) {
      setMeals(prevMeals);
      showToast("상태 변경에 실패했습니다. 다시 시도해 주세요.");
    }
  }, [meals, isAdmin]);

  const onDeleteMeal = useCallback(async (uuid: string): Promise<boolean> => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return false; }
    const target = meals.find(m => String(m.uuid) === String(uuid));
    if (!target) return false;
    const prevMeals = [...meals];
    setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, status: MealStatus.CANCELED, pending: true } : m));
    try {
      const success = await updateMealInGAS({ ...target, status: MealStatus.CANCELED });
      if (success) {
        setMeals(p => p.map(m => String(m.uuid) === String(uuid) ? { ...m, pending: false } : m));
        return true;
      } else throw new Error("Delete failed");
    } catch (err) {
      setMeals(prevMeals);
      showToast("삭제에 실패했습니다. 다시 시도해 주세요.");
      return false;
    }
  }, [meals, isAdmin]);

  const getIngredientDisplayName = useCallback((meal: MealRecord) => {
    if (meal.ingredient_name) return meal.ingredient_name;
    if (!meal.ingredient_uuid) return '식재료 정보 없음';
    const targetUuid = String(meal.ingredient_uuid).trim();
    const found = ingredients.find(i => String(i.uuid).trim() === targetUuid);
    return found ? found.name : '알 수 없는 식재료';
  }, [ingredients]);

  const handleCopyTextToClipboard = useCallback(() => {
    const actualMealsToCopy = filteredMeals.filter(m => m.status === MealStatus.ACTUAL);
    if (actualMealsToCopy.length === 0) {
      alert("섭취 완료된(ACTUAL) 식단이 없습니다.");
      return;
    }

    const typeOrder = [MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER];
    let text = `[${selectedDate} 식단 기록]\n\n`;

    typeOrder.forEach(type => {
      // 시간순 정렬 제거: 입력된 순서(배열 인덱스 순서) 유지
      const typeMeals = actualMealsToCopy.filter(m => m.type === type);

      if (typeMeals.length > 0) {
        text += `[${type}]\n`;
        typeMeals.forEach(m => {
          const name = getIngredientDisplayName(m);
          text += `${m.time} | ${name} (${m.amount}g) - ${Math.round(m.kcal)}kcal (탄:${Math.round(m.carbs)}g, 단:${Math.round(m.protein)}g, 지:${Math.round(m.fat)}g)\n`;
        });
        text += `\n`;
      }
    });

    text += `총 섭취: ${Math.round(summary.actual.kcal)}kcal / 계획: ${Math.round(summary.planned.kcal)}kcal\n`;
    text += `영양합계(실제): 탄 ${Math.round(summary.actual.carbs)}g, 단 ${Math.round(summary.actual.protein)}g, 지 ${Math.round(summary.actual.fat)}g`;

    navigator.clipboard.writeText(text).then(() => {
      showToast("식단이 클립보드에 복사되었습니다! 📋");
    }).catch(err => {
      console.error("Clipboard copy failed", err);
      showToast("복사에 실패했습니다.");
    });
  }, [filteredMeals, selectedDate, summary, getIngredientDisplayName]);

  const onSaveDiary = useCallback(async (content: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const prevDiaries = [...diaries];
    const now = getKSTFullTime();
    const newDiary: HealthDiary = {
      uuid: currentDiary?.uuid || crypto.randomUUID(),
      date: selectedDate,
      content,
      updated_at: now,
      pending: true
    };
    setDiaries(prev => {
      const exists = prev.some(d => d.date === selectedDate);
      return exists ? prev.map(d => d.date === selectedDate ? newDiary : d) : [...prev, newDiary];
    });
    try {
      const success = await saveDiaryToGAS(newDiary);
      if (success) setDiaries(prev => prev.map(d => d.date === selectedDate ? { ...newDiary, pending: false } : d));
      else throw new Error("Diary storage failed");
    } catch (error) { 
      setDiaries(prevDiaries);
      showToast("일기 저장에 실패했습니다.");
    }
  }, [selectedDate, currentDiary, diaries, isAdmin]);

  const handleToggleBookmark = useCallback(async (uuid: string) => {
    if (!isAdmin) { alert(TRIAL_MESSAGE); return; }
    const target = ingredients.find(i => String(i.uuid) === String(uuid));
    if (!target) return;
    const prevIngredients = [...ingredients];
    const next = !target.is_bookmarked;
    setIngredients(prev => prev.map(i => String(i.uuid) === String(uuid) ? { ...i, is_bookmarked: next } : i));
    try { 
      const success = await updateIngredientBookmark(uuid, next); 
      if (!success) throw new Error("Bookmark failed");
    } catch (err) { 
      setIngredients(prevIngredients); 
      showToast("즐겨찾기 상태 변경에 실패했습니다.");
    }
  }, [ingredients, isAdmin]);

  const handleLogin = (s: boolean) => { if (s) { setIsAdmin(true); localStorage.setItem('isAdmin', 'true'); } };
  const handleLogout = () => { if (confirm('관리자 모드를 해제하시겠습니까?')) { setIsAdmin(false); localStorage.removeItem('isAdmin'); } };

  return (
    <div className={`max-w-md mx-auto min-h-screen pb-24 relative bg-gray-50 shadow-2xl transition-all ${!isAdmin ? 'ring-4 ring-orange-200 ring-inset' : ''}`}>
      {isLoading && (
        <div className="fixed inset-0 z-[1000] bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
          <div className="relative mb-8">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center animate-pulse">
              <span className="text-6xl animate-bounce" style={{ display: 'inline-block' }}>{loadingEmoji}</span>
            </div>
            <div className="absolute -inset-2 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          </div>
          <h2 className="text-xl font-black text-gray-800 mb-2">데이터를 불러오는 중입니다...</h2>
          <p className="text-sm text-gray-400 font-medium">잠시만 기다려 주세요 ✨</p>
        </div>
      )}

      {toastMessage && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] px-6 py-3 bg-gray-900/90 backdrop-blur-sm text-white text-xs font-bold rounded-full shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          {toastMessage}
        </div>
      )}

      {!isAdmin && <div className="bg-orange-500 text-white text-[10px] font-black text-center py-1 uppercase tracking-widest sticky top-0 z-[60]">체험 모드로 접속 중입니다</div>}

      <header className={`bg-indigo-600 text-white p-4 sticky ${!isAdmin ? 'top-6' : 'top-0'} z-50 shadow-lg flex items-center justify-between`}>
        <div className="flex items-center">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg></button>
          <h1 className="ml-2 text-xl font-bold">{currentView === 'main' ? '쿠쿠님의 식단 기록' : currentView === 'ingredients' ? '식재료 관리' : '나의 통계'}</h1>
        </div>
        {isAdmin && <button onClick={handleLogout} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-full flex items-center space-x-1 transition-all active:scale-95 group"><div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse group-hover:bg-red-400"></div><span className="text-[10px] font-black tracking-widest group-hover:text-red-100">ADMIN</span></button>}
      </header>

      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} currentView={currentView} onNavigate={setCurrentView} isAdmin={isAdmin} onLogout={handleLogout} onOpenAdminLogin={() => setIsAdminLoginOpen(true)} />

      <main className="p-4">
        {currentView === 'main' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <Calendar selectedDate={selectedDate} onSelectDate={setSelectedDate} meals={meals} diaries={diaries} />
            <DailySummaryView summary={summary} selectedDate={selectedDate} />

            <div className="space-y-4">
              {[MealType.BREAKFAST, MealType.LUNCH, MealType.SNACK, MealType.DINNER].map(type => (
                <MealSection key={type} type={type} meals={filteredMeals.filter(m => m.type === type)} ingredients={ingredients} isAdmin={isAdmin} onAdd={() => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(null); setPrefilledType(type); setIsInputOpen(true); }} onEdit={(m) => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setEditMealTarget(m); setIsInputOpen(true); }} onDelete={onDeleteMeal} onSetStatus={handleSetMealStatus} />
              ))}
            </div>

            <div className="pt-2 space-y-3">
              <button onClick={() => setIsDiaryOpen(true)} className={`w-full py-4 rounded-2xl border-2 transition-all flex items-center justify-center space-x-2 font-black shadow-sm active:scale-[0.98] ${currentDiary ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-white border-dashed border-gray-200 text-gray-400'}`}>
                <span className="text-xl">{currentDiary ? '📝' : '+'}</span>
                <span>{currentDiary ? '건강 일기 보기' : '오늘의 건강 일기 작성'}</span>
              </button>
              <button onClick={handleCopyTextToClipboard} className="w-full py-4 bg-white border-2 border-indigo-500 text-indigo-600 font-black rounded-2xl shadow-sm active:scale-95 transition-all flex items-center justify-center space-x-2">
                <span className="text-xl">📋</span>
                <span>식단 리스트 복사하기</span>
              </button>
              <button onClick={() => setAdviceModalOpen(true)} className="w-full py-4 bg-gradient-to-br from-indigo-500 to-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center space-x-2"><span className="text-xl">✨</span><span>AI 영양 추천 받기</span></button>
            </div>
          </div>
        ) : currentView === 'ingredients' ? (
          <IngredientManagement ingredients={ingredients} isAdmin={isAdmin} onToggleBookmark={handleToggleBookmark} onAddIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => [...p, ing]); saveIngredientToGAS(ing); }} onUpdateIngredient={ing => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.map(i => i.uuid === ing.uuid ? ing : i)); updateIngredientInGAS(ing); }} onDeleteIngredient={id => { if (!isAdmin) { alert(TRIAL_MESSAGE); return; } setIngredients(p => p.filter(i => i.uuid !== id)); deleteIngredientFromGAS(id); }} trialMessage={TRIAL_MESSAGE} />
        ) : (
          <Statistics meals={meals} onDateSelect={(d) => { setSelectedDate(d); setCurrentView('main'); }} />
        )}
      </main>

      {!isAdmin && <button onClick={() => setIsAdminLoginOpen(true)} className="fixed bottom-6 right-6 w-12 h-12 bg-white text-indigo-600 rounded-full shadow-2xl flex items-center justify-center z-40 active:scale-90 border-2 border-indigo-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>}

      {isInputOpen && <MealInputForm isOpen={isInputOpen} onClose={() => { setIsInputOpen(false); setEditMealTarget(null); }} selectedDate={selectedDate} prefilledType={prefilledType} editTarget={editMealTarget} ingredients={ingredients} meals={meals} isAdmin={isAdmin} onSave={onSaveMeal} onDelete={onDeleteMeal} trialMessage={TRIAL_MESSAGE} />}
      {isDiaryOpen && <DiaryModal isOpen={isDiaryOpen} onClose={() => setIsDiaryOpen(false)} selectedDate={selectedDate} diary={currentDiary} onSave={onSaveDiary} isAdmin={isAdmin} />}
      {adviceModalOpen && <AIAdviceModal isOpen={adviceModalOpen} onClose={() => setAdviceModalOpen(false)} currentKcal={summary.actual.kcal} currentProtein={summary.actual.protein} />}
      {isAdminLoginOpen && <AdminLoginModal isOpen={isAdminLoginOpen} onClose={() => setIsAdminLoginOpen(false)} onLogin={handleLogin} />}
      {isExitModalOpen && <ExitModal isOpen={isExitModalOpen} onClose={() => { setIsExitModalOpen(false); window.history.pushState({ noBackExitsApp: true }, ''); }} />}
    </div>
  );
};

export default App;

import React, { useMemo, useRef } from 'react';
import { MealRecord, Ingredient, MealType, MealStatus } from '../types';

interface Props {
  type: MealType;
  meals: MealRecord[];
  ingredients: Ingredient[];
  isAdmin: boolean;
  onAdd: () => void;
  onEdit: (meal: MealRecord) => void;
  onDelete: (uuid: string) => Promise<boolean>;
  onSetStatus: (uuid: string, status: MealStatus) => void;
}

const MealSection: React.FC<Props> = ({ type, meals, ingredients, isAdmin, onAdd, onEdit, onDelete, onSetStatus }) => {
  const getIngredientDisplayName = (meal: MealRecord) => {
    if (meal.ingredient_name) return meal.ingredient_name;
    if (!meal.ingredient_uuid) return '식재료 정보 없음';
    const targetUuid = String(meal.ingredient_uuid).trim();
    const found = ingredients.find(i => String(i.uuid).trim() === targetUuid);
    return found ? found.name : '알 수 없는 식재료';
  };

  const totalProteinActual = useMemo(() => {
    return meals
      .filter(m => m.status === MealStatus.ACTUAL)
      .reduce((sum, meal) => sum + (Number(meal.protein) || 0), 0);
  }, [meals]);

  const totalProteinPlanned = useMemo(() => {
    return meals.reduce((sum, meal) => sum + (Number(meal.protein) || 0), 0);
  }, [meals]);

  // 입력 순서(배열 인덱스 순서)를 그대로 유지하기 위해 정렬 로직 제거
  const displayMeals = useMemo(() => {
    return [...meals];
  }, [meals]);

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center px-1">
        <div className="flex items-center space-x-2">
          <h4 className="font-bold text-gray-700 flex items-center">
            <span className={`w-2 h-2 rounded-full mr-2 ${
              type === MealType.BREAKFAST ? 'bg-amber-400' :
              type === MealType.LUNCH ? 'bg-green-400' :
              type === MealType.SNACK ? 'bg-pink-400' : 'bg-indigo-400'
            }`} />
            {type}
          </h4>
          {meals.length > 0 && (
            <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-medium">
              단백질 {Math.round(totalProteinActual)}g <span className="opacity-60">({Math.round(totalProteinPlanned)}g)</span>
            </span>
          )}
        </div>
        <button 
          onClick={onAdd}
          className="w-8 h-8 flex items-center justify-center bg-gray-100 rounded-full text-gray-500 hover:bg-gray-200 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
          </svg>
        </button>
      </div>

      <div className="space-y-2">
        {displayMeals.length === 0 ? (
          <div className="bg-white/50 border border-dashed border-gray-200 p-4 rounded-xl text-center text-xs text-gray-400 italic">
            기록된 {type}이 없습니다.
          </div>
        ) : (
          displayMeals.map(meal => (
            <SwipeableMealCard 
              key={meal.uuid} 
              meal={meal} 
              displayName={getIngredientDisplayName(meal)}
              isAdmin={isAdmin}
              onEdit={onEdit}
              onSetStatus={onSetStatus}
            />
          ))
        )}
      </div>
    </div>
  );
};

const SwipeableMealCard: React.FC<{ 
  meal: MealRecord; 
  displayName: string;
  isAdmin: boolean;
  onEdit: (meal: MealRecord) => void;
  onSetStatus: (uuid: string, status: MealStatus) => void;
}> = ({ meal, displayName, isAdmin, onEdit, onSetStatus }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const bgActualRef = useRef<HTMLDivElement>(null);
  const bgPlannedRef = useRef<HTMLDivElement>(null);

  const startX = useRef(0);
  const currentDiff = useRef(0);
  const isDragging = useRef(false);
  const threshold = 80;

  const updateStyles = (diff: number) => {
    if (!cardRef.current) return;
    const dragX = diff * 0.6;
    cardRef.current.style.transform = `translate3d(${dragX}px, 0, 0)`;

    if (bgActualRef.current) {
      const opacity = Math.min(Math.max(dragX / 60, 0), 1);
      bgActualRef.current.style.opacity = opacity.toString();
    }
    if (bgPlannedRef.current) {
      const opacity = Math.min(Math.max(-dragX / 60, 0), 1);
      bgPlannedRef.current.style.opacity = opacity.toString();
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    if (!isAdmin) return;
    if (meal.pending) return;
    startX.current = e.touches[0].clientX;
    isDragging.current = true;
    if (cardRef.current) cardRef.current.style.transition = 'none';
  };

  const onTouchMove = (e: React.TouchEvent) => {
    if (!isAdmin || !isDragging.current) return;
    currentDiff.current = e.touches[0].clientX - startX.current;
    requestAnimationFrame(() => updateStyles(currentDiff.current));
  };

  const onTouchEnd = () => {
    if (!isAdmin || !isDragging.current) return;
    isDragging.current = false;
    const dragX = currentDiff.current * 0.6;

    if (cardRef.current) {
      cardRef.current.style.transition = 'transform 0.4s cubic-bezier(0.25, 1, 0.5, 1)';
      cardRef.current.style.transform = `translate3d(0, 0, 0)`;
    }
    if (bgActualRef.current) bgActualRef.current.style.opacity = '0';
    if (bgPlannedRef.current) bgPlannedRef.current.style.opacity = '0';

    if (dragX > threshold) onSetStatus(meal.uuid, MealStatus.ACTUAL);
    else if (dragX < -threshold) onSetStatus(meal.uuid, MealStatus.PLANNED);
    currentDiff.current = 0;
  };

  const isPlanned = meal.status === MealStatus.PLANNED;
  const isDirectEntry = meal.ingredient_uuid === 'direct-entry';

  return (
    <div className="relative overflow-hidden rounded-xl bg-gray-100 touch-pan-y">
      <div className="absolute inset-0 flex items-center justify-between px-6 z-0 pointer-events-none">
        <div ref={bgActualRef} className="opacity-0 flex items-center space-x-2">
          <div className="w-9 h-9 rounded-full bg-green-500 flex items-center justify-center text-white">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
          </div>
        </div>
        <div ref={bgPlannedRef} className="opacity-0 flex items-center space-x-2">
          <div className="w-9 h-9 rounded-full bg-gray-400 flex items-center justify-center text-white">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><rect x="3" y="3" width="18" height="18" rx="4" strokeWidth="2" /></svg>
          </div>
        </div>
      </div>

      <div 
        ref={cardRef}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        onClick={() => onEdit(meal)}
        className={`relative z-10 flex-1 p-4 rounded-xl shadow-sm flex justify-between items-center border-l-4 transition-all ${
          meal.pending ? 'opacity-50 grayscale border-gray-300 cursor-wait' : 
          isPlanned ? 'bg-gray-50 border-gray-300 border-dashed' : 'bg-white border-indigo-500 hover:border-indigo-600'
        }`}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center space-x-2 overflow-hidden">
            <p className={`font-bold text-sm truncate ${isPlanned ? 'text-gray-400 italic' : 'text-gray-800'}`}>
              {displayName}
            </p>
            {isDirectEntry && (
              <span className="shrink-0 text-[9px] bg-amber-100 text-amber-600 px-1.5 py-0.5 rounded-sm font-black uppercase tracking-tighter">임의입력</span>
            )}
            {isPlanned && (
              <span className="shrink-0 text-[9px] bg-gray-200 text-gray-500 px-1.5 py-0.5 rounded-sm font-black uppercase tracking-tighter">Planned</span>
            )}
          </div>
          <p className="text-xs text-gray-400 font-medium">{meal.amount}g • {meal.time}</p>
        </div>
        <div className="text-right shrink-0 ml-2">
          <p className={`font-black tracking-tight ${isPlanned ? 'text-gray-300' : 'text-indigo-600'}`}>
            {Math.round(meal.kcal)} <span className="text-[9px] font-bold ml-0.5">kcal</span>
          </p>
          <div className="flex items-center space-x-1 text-[9px] text-gray-400 justify-end font-bold">
            <span className={!isPlanned ? 'text-orange-500/80' : ''}>C {Math.round(meal.carbs || 0)}g</span>
            <span className="opacity-30 px-0.5">·</span>
            <span className={!isPlanned ? 'text-emerald-500/80' : ''}>P {Math.round(meal.protein || 0)}g</span>
            <span className="opacity-30 px-0.5">·</span>
            <span className={!isPlanned ? 'text-blue-500/80' : ''}>F {Math.round(meal.fat || 0)}g</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealSection;
